Here's a basic implementation of a native iOS habit tracking application using **Swift**. This example includes a simple UI with a list of habits, the ability to toggle habit completion, and persistence using `UserDefaults`.

---

### 📱 Habit Tracking App (Swift)

```swift
import UIKit

// MARK: - Habit Model
struct Habit: Codable {
    let name: String
    var completed: Bool
}

class HabitViewController: UITableViewController {
    // MARK: - Properties
    private var habits: [Habit] = []
    private let habitKey = "saved_habits"

    // MARK: - Lifecycle
    override func viewDidLoad() {
        super.viewDidLoad()
        title = "Habit Tracker"
        navigationItem.rightBarButtonItem = UIBarButtonItem(
            barButtonSystemItem: .add, target: self, action: #selector(addHabit)
        )
        loadHabits()
    }

    // MARK: - Data Loading
    private func loadHabits() {
        if let data = UserDefaults.standard.data(forKey: habitKey),
           let decodedHabits = try? JSONDecoder().decode([Habit].self, from: data) {
            habits = decodedHabits
        }
        tableView.reloadData()
    }

    private func saveHabits() {
        if let encodedData = try? JSONEncoder().encode(habits) {
            UserDefaults.standard.set(encodedData, forKey: habitKey)
        }
    }

    // MARK: - Table View Data Source
    override func tableView(_ tableView: UITableView, numberOfRowsInSection section: Int) -> Int {
        return habits.count
    }

    override func tableView(_ tableView: UITableView, cellForRowAt indexPath: IndexPath) -> UITableViewCell {
        let cell = tableView.dequeueReusableCell(withIdentifier: "HabitCell", for: indexPath)
        let habit = habits[indexPath.row]

        cell.textLabel?.text = habit.name
        cell.accessoryType = habit.completed ? .checkmark : .none

        // Optional: Add a toggle switch (example)
        if let switchView = cell.viewWithTag(1) as? UISwitch {
            switchView.isOn = habit.completed
            switchView.addTarget(self, action: #selector(toggleHabit(_:)), for: .valueChanged)
        }

        return cell
    }

    // MARK: - Table View Delegate
    override func tableView(_ tableView: UITableView, didSelectRowAt indexPath: IndexPath) {
        let habit = habits[indexPath.row]
        let alert = UIAlertController(
            title: "Edit Habit",
            message: nil,
            preferredStyle: .alert
        )

        alert.addTextField { textField in
            textField.text = habit.name
        }

        alert.addAction(UIAlertAction(title: "Save", style: .default) { _ in
            if let newName = alert.textFields?.first?.text, !newName.isEmpty {
                self.habits[indexPath.row].name = newName
                self.saveHabits()
                self.tableView.reloadRows(at: [indexPath], with: .automatic)
            }
        })

        alert.addAction(UIAlertAction(title: "Cancel", style: .cancel))
        present(alert, animated: true)
    }

    // MARK: - Actions
    @objc private func addHabit() {
        let alert = UIAlertController(
            title: "New Habit",
            message: nil,
            preferredStyle: .alert
        )

        alert.addTextField { textField in
            textField.placeholder = "Enter habit name"
        }

        alert.addAction(UIAlertAction(title: "Add", style: .default) { _ in
            if let name = alert.textFields?.first?.text, !name.isEmpty {
                let newHabit = Habit(name: name, completed: false)
                self.habits.append(newHabit)
                self.saveHabits()
                self.tableView.insertRows(at: [IndexPath(row: self.habits.count - 1, section: 0)], with: .automatic)
            }
        })

        alert.addAction(UIAlertAction(title: "Cancel", style: .cancel))
        present(alert, animated: true)
    }

    @objc private func toggleHabit(_ sender: UISwitch) {
        if let cell = sender.superview?.superview as? UITableViewCell,
           let indexPath = tableView.indexPath(for: cell),
           indexPath.row < habits.count {
            habits[indexPath.row].completed = sender.isOn
            saveHabits()
            tableView.reloadRows(at: [indexPath], with: .automatic)
        }
    }
}
```

---

### 🧩 How to Use This Code

1. **Create a new Xcode project** with a **Single View App** template.
2. Replace the `ViewController.swift` file with the above code.
3. **Register a cell** in `viewDidLoad` or in the storyboard:
   ```swift
   tableView.register(UITableViewCell.self, forCellReuseIdentifier: "HabitCell")
   ```
4. **Add a switch** to the cell (or use the `accessoryType` for simplicity).
5. Run the app and test adding, editing, and toggling habits.

---

### 📌 Notes
- This is a **basic implementation**. For a production app, consider:
  - Using **Core Data** or **Realm** for persistence.
  - Adding **habit statistics** (e.g., streaks, completion rates).
  - Supporting **custom habit intervals** (daily, weekly, etc.).
  - Implementing **dark/light mode** support.
- **UserDefaults** is used for simplicity, but it's not ideal for large datasets.

