Here's a simple, native iOS habit tracking application implemented in **Swift**. This example includes a basic interface to track daily habits, with the ability to toggle completion status and add new habits.

---

### 📱 Habit Tracking App in Swift

```swift
import UIKit

// MARK: - Habit Model
struct Habit {
    var name: String
    var isCompleted: Bool
    var streak: Int
}

// MARK: - HabitViewController
class HabitViewController: UITableViewController {

    // MARK: - Properties
    var habits: [Habit] = [
        Habit(name: "Drink Water", isCompleted: false, streak: 0),
        Habit(name: "Exercise", isCompleted: false, streak: 0),
        Habit(name: "Read Book", isCompleted: true, streak: 3)
    ]

    // MARK: - Lifecycle
    override func viewDidLoad() {
        super.viewDidLoad()
        title = "Habit Tracker"
        navigationItem.rightBarButtonItem = UIBarButtonItem(barButtonSystemItem: .add, target: self, action: #selector(addHabitButtonTapped))
    }

    // MARK: - Table View Data Source
    override func tableView(_ tableView: UITableView, numberOfRowsInSection section: Int) -> Int {
        return habits.count
    }

    override func tableView(_ tableView: UITableView, cellForRowAt indexPath: IndexPath) -> UITableViewCell {
        let cell = tableView.dequeueReusableCell(withIdentifier: "HabitCell", for: indexPath)
        let habit = habits[indexPath.row]

        cell.textLabel?.text = habit.name
        cell.accessoryType = habit.isCompleted ? .checkmark : .none

        return cell
    }

    // MARK: - Table View Delegate
    override func tableView(_ tableView: UITableView, didSelectRowAt indexPath: IndexPath) {
        var habit = habits[indexPath.row]
        habit.isCompleted.toggle()
        habits[indexPath.row] = habit
        tableView.reloadRows(at: [indexPath], with: .automatic)
    }

    // MARK: - Add Habit Button
    @objc private func addHabitButtonTapped() {
        let alert = UIAlertController(
            title: "New Habit",
            message: "Enter the name of your new habit",
            preferredStyle: .alert
        )

        alert.addTextField { textField in
            textField.placeholder = "e.g. 'Drink Water'"
        }

        let addAction = UIAlertAction(title: "Add", style: .default) { [weak self] _ in
            guard let textField = alert.textFields?.first, let text = textField.text, !text.isEmpty else { return }
            let newHabit = Habit(name: text, isCompleted: false, streak: 0)
            self?.habits.insert(newHabit, at: 0)
            self?.tableView.insertRows(at: [IndexPath(row: 0, section: 0)], with: .automatic)
        }

        alert.addAction(addAction)
        alert.addAction(UIAlertAction(title: "Cancel", style: .cancel))

        present(alert, animated: true)
    }
}
```

---

### 📱 Usage Instructions

1. **Add to a Project**: This code should be placed in a new `UITableViewController` subclass in your Xcode project.
2. **Set Cell Identifier**: In your storyboard or XIB file, set the cell identifier to `"HabitCell"`.
3. **Navigation**: This view controller should be embedded in a `UINavigationController` to make the "Add" button functional.

---

### 🔁 Features

- Toggle habit completion status.
- Add new habits with an alert.
- Simple in-memory data storage (for demonstration only).
- Clean and minimal UI for clarity.

---

