Here's a basic implementation of a **native iOS habit tracking application** in **Swift**. This code includes a habit tracker with the ability to add habits, mark them as completed, and persist data using `UserDefaults`. It uses a `UITableViewController` as the main interface.

---

<language>Swift</language>

```swift
import UIKit

// MARK: - Data Model
struct Habit: Codable, Identifiable {
    let id: UUID
    var name: String
    var isCompleted: Bool
    var lastCompletedDate: Date?

    init(name: String) {
        self.id = UUID()
        self.name = name
        self.isCompleted = false
        self.lastCompletedDate = nil
    }
}

// MARK: - Main View Controller
class HabitViewController: UITableViewController {

    // MARK: - Properties
    private var habits: [Habit] = []
    private let defaultsKey = "savedHabits"

    // MARK: - Lifecycle
    override func viewDidLoad() {
        super.viewDidLoad()
        navigationItem.title = "Habit Tracker"
        navigationItem.rightBarButtonItem = UIBarButtonItem(barButtonSystemItem: .add, target: self, action: #selector(addHabit))
        loadHabits()
    }

    // MARK: - Table View Data Source
    override func tableView(_ tableView: UITableView, numberOfRowsInSection section: Int) -> Int {
        return habits.count
    }

    override func tableView(_ tableView: UITableView, cellForRowAt indexPath: IndexPath) -> UITableViewCell {
        let cell = tableView.dequeueReusableCell(withIdentifier: "HabitCell", for: indexPath)
        let habit = habits[indexPath.row]

        cell.textLabel?.text = habit.name
        cell.accessoryType = habit.isCompleted ? .checkmark : .none

        return cell
    }

    override func tableView(_ tableView: UITableView, didSelectRowAt indexPath: IndexPath) {
        let habit = habits[indexPath.row]
        habit.isCompleted = !habit.isCompleted
        habit.lastCompletedDate = habit.isCompleted ? Date() : nil
        saveHabits()
        tableView.reloadData()
    }

    // MARK: - Actions
    @objc private func addHabit() {
        let alert = UIAlertController(
            title: "New Habit",
            message: "Enter the name of your habit",
            preferredStyle: .alert
        )

        alert.addTextField { textField in
            textField.placeholder = "e.g., Drink water"
        }

        let addAction = UIAlertAction(title: "Add", style: .default) { [weak self] _ in
            guard let textField = alert.textFields?.first, let name = textField.text, !name.isEmpty else { return }
            let newHabit = Habit(name: name)
            self?.habits.append(newHabit)
            self?.saveHabits()
            self?.tableView.reloadData()
        }

        let cancelAction = UIAlertAction(title: "Cancel", style: .cancel)

        alert.addAction(addAction)
        alert.addAction(cancelAction)

        present(alert, animated: true)
    }

    // MARK: - Persistence
    private func saveHabits() {
        if let encodedData = try? JSONEncoder().encode(habits) {
            UserDefaults.standard.set(encodedData, forKey: defaultsKey)
        }
    }

    private func loadHabits() {
        if let savedData = UserDefaults.standard.data(forKey: defaultsKey),
           let decodedHabits = try? JSONDecoder().decode([Habit].self, from: savedData) {
            habits = decodedHabits
        }
    }
}
```

