### 📱 Habit Tracker App (Swift + SwiftUI)

```swift
import SwiftUI

// MARK: - Habit Model
struct Habit: Identifiable {
    let id = UUID()
    var name: String
    var isCompleted: Bool
    var date: Date
}

// MARK: - ViewModel
class HabitViewModel: ObservableObject {
    @Published var habits: [Habit] = []

    func addHabit(name: String) {
        let newHabit = Habit(name: name, isCompleted: false, date: Date())
        habits.append(newHabit)
    }

    func toggleHabitCompletion(at index: Int) {
        habits[index].isCompleted.toggle()
    }
}

// MARK: - Main View
struct HabitTrackerView: View {
    @StateObject private var viewModel = HabitViewModel()
    @State private var newHabitName = ""

    var body: some View {
        NavigationView {
            VStack {
                List {
                    ForEach(viewModel.habits) { habit in
                        HabitRow(habit: habit, onToggle: {
                            viewModel.toggleHabitCompletion(at: viewModel.habits.firstIndex(where: { $0.id == habit.id })!)
                        })
                    }
                }

                HStack {
                    TextField("New habit", text: $newHabitName)
                        .textFieldStyle(RoundedBorderTextFieldStyle())
                        .padding(.horizontal)

                    Button(action: {
                        if !newHabitName.isEmpty {
                            viewModel.addHabit(name: newHabitName)
                            newHabitName = ""
                        }
                    }) {
                        Image(systemName: "plus.circle.fill")
                            .foregroundColor(.blue)
                            .font(.largeTitle)
                    }
                }
                .padding()
            }
            .navigationTitle("Habit Tracker")
        }
    }
}

// MARK: - Habit Row View
struct HabitRow: View {
    var habit: Habit
    var onToggle: () -> Void

    var body: some View {
        HStack {
            Text(habit.name)
                .strikethrough(habit.isCompleted)
                .foregroundColor(habit.isCompleted ? .gray : .black)

            Spacer()

            Image(systemName: habit.isCompleted ? "checkmark.circle.fill" : "circle")
                .foregroundColor(habit.isCompleted ? .green : .gray)
                .onTapGesture {
                    onToggle()
                }
        }
    }
}

// MARK: - Preview
struct HabitTrackerView_Previews: PreviewProvider {
    static var previews: some View {
        HabitTrackerView()
    }
}
```

