### 📱 **Habit Tracker App (SwiftUI Implementation)**

#### 1. **Habit Model**
```swift
import Foundation

struct Habit: Identifiable {
    let id = UUID()
    var name: String
    var goal: Int
    var progress: Int
}
```

---

#### 2. **Main View (ContentView.swift)**
```swift
import SwiftUI

struct ContentView: View {
    @AppStorage("habits") private var habitsData: Data = Data()
    @State private var habits: [Habit] = []
    @State private var showingAddHabit = false

    var body: some View {
        NavigationView {
            VStack {
                List {
                    ForEach(habits) { habit in
                        HabitRow(habit: habit)
                    }
                    .onDelete(perform: deleteHabit)
                }
                .navigationTitle("Habit Tracker")
                .toolbar {
                    ToolbarItem(placement: .navigationBarTrailing) {
                        Button(action: { showingAddHabit.toggle() }) {
                            Image(systemName: "plus")
                        }
                    }
                }
            }
            .sheet(isPresented: $showingAddHabit) {
                AddHabitView(habits: $habits)
            }
        }
        .onAppear {
            if let decodedHabits = try? JSONDecoder().decode([Habit].self, from: habitsData) {
                habits = decodedHabits
            }
        }
        .onChange(of: habits) { _ in
            if let encodedHabits = try? JSONEncoder().encode(habits) {
                habitsData = encodedHabits
            }
        }
    }

    func deleteHabit(at offsets: IndexSet) {
        habits.remove(atOffsets: offsets)
    }
}
```

---

#### 3. **Habit Row (HabitRow.swift)**
```swift
import SwiftUI

struct HabitRow: View {
    var habit: Habit

    var body: some View {
        HStack {
            Text(habit.name)
            Spacer()
            Text("\(habit.progress)/$habit.goal)")
                .foregroundColor(habit.progress >= habit.goal ? .green : .gray)
        }
        .padding()
    }
}
```

---

#### 4. **Add Habit View (AddHabitView.swift)**
```swift
import SwiftUI

struct AddHabitView: View {
    @Binding var habits: [Habit]
    @State private var name = ""
    @State private var goal = 1

    var body: some View {
        NavigationView {
            Form {
                TextField("Habit Name", text: $name)
                    .textFieldStyle(RoundedBorderTextFieldStyle())
                Stepper("Goal: $goal)", value: $goal, in: 1...100)
            }
            .navigationTitle("Add Habit")
            .toolbar {
                ToolbarItem(placement: .navigationBarTrailing) {
                    Button("Save") {
                        if !name.isEmpty {
                            let newHabit = Habit(name: name, goal: goal, progress: 0)
                            habits.append(newHabit)
                            name = ""
                            goal = 1
                        }
                    }
                }
            }
        }
    }
}
```

