#### 2. **Data Source**
```swift
import Foundation

class HabitDataSource {
    private let key = "savedHabits"
    private var habits: [Habit] = []

    init() {
        loadHabits()
    }

    func loadHabits() {
        if let data = UserDefaults.standard.data(forKey: key), let decoded = try? JSONDecoder().decode([Habit].self, from: data) {
            habits = decoded
        }
    }

    func saveHabits() {
        let encoded = try? JSONEncoder().encode(habits)
        UserDefaults.standard.set(encoded, forKey: key)
    }

    func addHabit(name: String, frequency: String) {
        let newHabit = Habit(name: name, frequency: frequency, count: 0)
        habits.append(newHabit)
        saveHabits()
    }

    func incrementHabit(at index: Int) {
        habits[index].count += 1
        saveHabits()
    }

    func getHabits() -> [Habit] {
        return habits
    }
}
```

