#### 3. **Main View Controller**
```swift
import UIKit

class HabitViewController: UITableViewController {
    private let habitDataSource = HabitDataSource()

    override func viewDidLoad() {
        super.viewDidLoad()
        title = "Habit Tracker"
        navigationItem.rightBarButtonItem = UIBarButtonItem(barButtonSystemItem: .add, target: self, action: #selector(addHabit))
    }

    override func tableView(_ tableView: UITableView, numberOfRowsInSection section: Int) -> Int {
        return habitDataSource.getHabits().count
    }

    override func tableView(_ tableView: UITableView, cellForRowAt indexPath: IndexPath) -> UITableViewCell {
        let cell = tableView.dequeueReusableCell(withIdentifier: "HabitCell", for: indexPath)
        let habit = habitDataSource.getHabits()[indexPath.row]
        cell.textLabel?.text = habit.name
        cell.detailTextLabel?.text = "Count: $habit.count)"
        return cell
    }

    override func tableView(_ tableView: UITableView, didSelectRowAt indexPath: IndexPath) {
        habitDataSource.incrementHabit(at: indexPath.row)
        tableView.reloadRows(at: [indexPath], with: .automatic)
    }

    @objc private func addHabit() {
        let alert = UIAlertController(
            title: "New Habit",
            message: nil,
            preferredStyle: .alert
        )
        alert.addTextField { textField in
            textField.placeholder = "Habit name"
        }
        alert.addTextField { textField in
            textField.placeholder = "Frequency (e.g., Daily/Weekly)"
        }

        let addAction = UIAlertAction(title: "Add", style: .default) { [weak self] _ in
            guard let name = alert.textFields?[0].text, !name.isEmpty,
                  let frequency = alert.textFields?[1].text, !frequency.isEmpty else { return }
            self?.habitDataSource.addHabit(name: name, frequency: frequency)
            self?.tableView.reloadData()
        }

        alert.addAction(addAction)
        alert.addAction(UIAlertAction(title: "Cancel", style: .cancel))
        present(alert, animated: true)
    }
}
```

---

#### 4. **App Delegate (Optional for Navigation)**
```swift
import UIKit

@main
class AppDelegate: UIResponder, UIApplicationDelegate {
    var window: UIWindow?

    func application(_ application: UIApplication, didFinishLaunchingWithOptions launchOptions: [UIApplication.LaunchOptionsKey: Any]?) -> Bool {
        window = UIWindow(frame: UIScreen.main.bounds)
        let viewController = HabitViewController()
        window?.rootViewController = viewController
        window?.makeKeyAndVisible()
        return true
    }
}
```

