### 📱 **Habit Tracker App (Minimal Version)**

```swift
import SwiftUI

// MARK: - Habit Model
struct Habit: Identifiable, Codable {
    let id: UUID
    var name: String
    var count: Int
}

// MARK: - Main App View
struct HabitTracker: View {
    @AppStorage("habits") private var habitsData: Data = Data()
    @State private var habits: [Habit] = []
    @State private var showingAddHabit = false
    @State private var newHabitName = ""

    var body: some View {
        NavigationView {
            List {
                ForEach(habits) { habit in
                    HStack {
                        Text(habit.name)
                        Spacer()
                        Button(action: {
                            habit.count += 1
                            saveHabits()
                        }) {
                            Text("\(habit.count)")
                                .frame(width: 40, height: 40)
                                .background(Color.blue)
                                .foregroundColor(.white)
                                .clipShape(Circle())
                        }
                    }
                }
                .onDelete(perform: deleteHabit)
            }
            .navigationTitle("Habits")
            .toolbar {
                ToolbarItem(placement: .navigationBarTrailing) {
                    Button(action: {
                        showingAddHabit = true
                    }) {
                        Image(systemName: "plus")
                    }
                }
            }
            .sheet(isPresented: $showingAddHabit) {
                AddHabitView(newHabitName: $newHabitName, onSave: addHabit)
            }
        }
        .onAppear {
            loadHabits()
        }
    }

    // MARK: - Load and Save Habits
    private func loadHabits() {
        if let data = habitsData, let decoded = try? JSONDecoder().decode([Habit].self, from: data) {
            habits = decoded
        }
    }

    private func saveHabits() {
        if let encoded = try? JSONEncoder().encode(habits) {
            habitsData = encoded
        }
    }

    // MARK: - Add/Delete Habits
    private func addHabit() {
        let newHabit = Habit(id: UUID(), name: newHabitName, count: 0)
        habits.append(newHabit)
        saveHabits()
        newHabitName = ""
        showingAddHabit = false
    }

    private func deleteHabit(at indexSet: IndexSet) {
        habits.remove(atOffsets: indexSet)
        saveHabits()
    }
}

// MARK: - Add Habit View
struct AddHabitView: View {
    @Binding var newHabitName: String
    var onSave: () -> Void

    var body: some View {
        VStack {
            TextField("Enter habit name", text: $newHabitName)
                .textFieldStyle(RoundedBorderTextFieldStyle())
                .padding()
            Button("Save") {
                onSave()
            }
            .padding()
        }
        .navigationTitle("Add Habit")
    }
}

@main
struct HabitTrackerApp: App {
    var body: some Scene {
        WindowGroup {
            HabitTracker()
        }
    }
}
```

