### 🔐 **Secure Storage (Android Keystore)**
```kotlin
// SecureStorage.kt
class SecureStorage(context: Context) {
    private val keyStore = KeyStore.getInstance(KeyStore.getDefaultType()).apply {
        load(null, null)
    }

    private val keyGenerator = KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES, "AndroidKeyStore").apply {
        init(KeyGenParameterSpec.Builder(
            "banking_app_key",
            KeyProperties.PURPOSE_ENCRYPT or KeyProperties.PURPOSE_DECRYPT
        ).setBlockModes(KeyProperties.BLOCK_MODE_GCM)
            .setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE)
            .setUserAuthenticationRequired(true)
            .build())
    }

    fun encrypt(data: String): String {
        val secretKey = keyStore.getKey("banking_app_key", null) as SecretKey
        val cipher = Cipher.getInstance("AES/GCM/NoPadding").apply { init(Cipher.ENCRYPT_MODE, secretKey) }
        return Base64.encodeToString(cipher.doFinal(data.toByteArray()), Base64.DEFAULT)
    }

    fun decrypt(encryptedData: String): String {
        val secretKey = keyStore.getKey("banking_app_key", null) as SecretKey
        val cipher = Cipher.getInstance("AES/GCM/NoPadding").apply { init(Cipher.DECRYPT_MODE, secretKey) }
        return String(cipher.doFinal(Base64.decode(encryptedData, Base64.DEFAULT)))
    }
}
