    val loginSuccess: LiveData<Boolean> = _loginSuccess

    fun login(username: String, password: String, userDao: UserDao) {
        viewModelScope.launch {
            userDao.getUser(username).collect { user ->
                if (user != null && user.passwordHash == SecureStorage("").hashPassword(password)) {
                    _loginSuccess.value = true
                } else {
                    _loginSuccess.value = false
                }
            }
        }
    }

    private fun hashPassword(password: String): String {
        return MessageDigest.getInstance("SHA-256").digest(password.toByteArray()).let {
            Base64.encodeToString(it, Base64.NO_WRAP)
        }
    }
}
