import React, { useState, useEffect } from 'react';
import { View, Text, TextInput, Button, Alert, StyleSheet } from 'react-native';
import SQLite from 'expo-sqlite';
import axios from 'axios';
import NetInfo from '@react-native-community/netinfo';

const db = SQLite.openDatabase('survey.db');

const App = () => {
  const [name, setName] = useState('');
  const [location, setLocation] = useState('');
  const [notes, setNotes] = useState('');
  const [isOnline, setIsOnline] = useState(false);

  // Initialize database
  useEffect(() => {
    db.transaction(tx => {
      tx.executeSql(
        'CREATE TABLE IF NOT EXISTS surveys (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT, location TEXT, notes TEXT, synced INTEGER DEFAULT 0)',
        [],
        () => console.log('Table created'),
        (_, error) => console.log('Error creating table', error)
      );
    });

    // Check internet connection
    const unsubscribe = NetInfo.addEventListener(state => {
      setIsOnline(state.isConnected);
      if (state.isConnected) {
        syncData();
      }
    });

    return () => unsubscribe();
  }, []);

  // Submit survey locally
  const submitSurvey = () => {
    if (!name || !location) {
      Alert.alert('Error', 'Name and Location are required!');
      return;
    }

    db.transaction(tx => {
      tx.executeSql(
        'INSERT INTO surveys (name, location, notes, synced) VALUES (?, ?, ?, 0)',
        [name, location, notes],
        (_, result) => {
          Alert.alert('Success', 'Survey saved locally!');
          setName('');
          setLocation('');
          setNotes('');
        },
        (_, error) => console.log('Error inserting', error)
      );
    });
  };

  // Sync data with backend
  const syncData = async () => {
    db.transaction(tx => {
      tx.executeSql(
        'SELECT * FROM surveys WHERE synced = 0',
        [],
        (_, { rows: { _array } }) => {
          if (_array.length === 0) return;

          axios
            .post('http://localhost:3000/surveys', _array)
            .then(() => {
              tx.executeSql(
                'UPDATE surveys SET synced = 1 WHERE id IN (?)',
                [_array.map(s => s.id).join(',')],
                () => console.log('Synced data to server')
              );
            })
            .catch(err => {
              console.error('Sync error:', err);
            });
        },
        (_, error) => console.log('Error fetching surveys', error)
      );
    });
  };

  return (
    <View style={styles.container}>
      <Text style={styles.title}>Field Survey App</Text>
      <TextInput
        placeholder="Name"
        value={name}
        onChangeText={setName}
        style={styles.input}
      />
      <TextInput
        placeholder="Location"
        value={location}
        onChangeText={setLocation}
        style={styles.input}
      />
      <TextInput
        placeholder="Notes"
        value={notes}
        onChangeText={setNotes}
        style={styles.input}
        multiline
      />
      <Button title="Submit Survey" onPress={submitSurvey} />
      {isOnline && <Text style={styles.status}>Syncing data...</Text>}
    </View>
  );
};

const styles = StyleSheet.create({
  container: { flex: 1, padding: 20, justifyContent: 'center' },
  title: { fontSize: 24, fontWeight: 'bold', marginBottom: 20 },
  input: { height: 40, borderColor: 'gray', borderWidth: 1, marginBottom: 15, padding: 10 },
  status: { marginTop: 10, color: 'green' },
});

export default App;
```

