```javascript
import React, { useEffect, useState } from 'react';
import { View, Text, TextInput, Button, Alert } from 'react-native';
import SQLite from 'react-native-sqlite-storage';
import NetInfo from '@react-native-community/netinfo';

// Initialize SQLite database
const db = SQLite.openDatabase({ name: 'survey.db', location: 'default' });

// Create table if not exists
db.executeSql(
  'CREATE TABLE IF NOT EXISTS surveys (id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT, notes TEXT, synced BOOLEAN DEFAULT 0)',
  [],
  () => console.log('Table created or already exists'),
  (err) => console.error('Error creating table', err)
);

const App = () => {
  const [title, setTitle] = useState('');
  const [notes, setNotes] = useState('');
  const [syncStatus, setSyncStatus] = useState('Offline');

  // Check network status
  useEffect(() => {
    const subscription = NetInfo.addEventListener(state => {
      setSyncStatus(state.isConnected ? 'Online' : 'Offline');
      if (state.isConnected) {
        syncData(); // Sync when online
      }
    });

    return () => subscription();
  }, []);

  // Save survey data locally
  const saveSurvey = () => {
    if (!title) return Alert.alert('Error', 'Title is required');

    db.transaction(tx => {
      tx.executeSql(
        'INSERT INTO surveys (title, notes) VALUES (?, ?)',
        [title, notes],
        () => {
          Alert.alert('Success', 'Survey saved locally');
          setTitle('');
          setNotes('');
        },
        (err) => console.error('Error saving survey', err)
      );
    });
  };

  // Sync data with server
  const syncData = () => {
    db.transaction(tx => {
      tx.executeSql(
        'SELECT * FROM surveys WHERE synced = 0',
        [],
        (tx, results) => {
          const rows = results.rows;
          if (rows.length === 0) {
            Alert.alert('Sync', 'No new data to sync.');
            return;
          }

          const surveys = [];
          for (let i = 0; i < rows.length; i++) {
            surveys.push(rows.item(i));
          }

          // Simulate sending data to server
          fetch('https://your-backend.com/sync', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(surveys),
          })
            .then(res => res.json())
            .then(() => {
              // Mark synced surveys as synced
              tx.executeSql(
                'UPDATE surveys SET synced = 1 WHERE id IN (?)',
                [surveys.map(s => s.id).join(',')],
                () => Alert.alert('Sync', 'Data synced successfully!'),
                (err) => console.error('Error marking as synced', err)
              );
            })
            .catch(err => {
              console.error('Sync error', err);
              Alert.alert('Sync Error', 'Failed to sync data.');
            });
        },
        (err) => console.error('Error fetching unsynced data', err)
      );
    });
  };

  return (
    <View style={{ padding: 20 }}>
      <Text>Survey Title</Text>
      <TextInput
        value={title}
        onChangeText={setTitle}
        style={{ borderWidth: 1, marginBottom: 10, padding: 5 }}
      />
      <Text>Notes</Text>
      <TextInput
        value={notes}
        onChangeText={setNotes}
        style={{ borderWidth: 1, marginBottom: 10, padding: 5 }}
      />
      <Button title="Save Survey" onPress={saveSurvey} />
      <Text style={{ marginTop: 20 }}>Connection Status: {syncStatus}</Text>
    </View>
  );
};

export default App;
```

