// models/survey.dart
class Survey {
  final String id;
  final String title;
  final String data; // JSON string for survey details
  final DateTime createdAt;
  final bool synced;

  Survey({
    required this.id,
    required this.title,
    required this.data,
    required this.createdAt,
    this.synced = false,
  });

  Map<String, dynamic> toMap() {
    return {
      'id': id,
      'title': title,
      'data': data,
      'createdAt': createdAt.toIso8601String(),
      'synced': synced,
    };
  }

  factory Survey.fromMap(Map<String, dynamic> map) {
    return Survey(
      id: map['id'],
      title: map['title'],
      data: map['data'],
      createdAt: DateTime.parse(map['createdAt']),
      synced: map['synced'] as bool,
    );
  }
}
```

