### 🌐 **3. Firebase Sync Service**
```dart
// services/firebase_sync.dart
import 'package:firebase_database/firebase_database.dart';
import 'models/survey.dart';
import 'database_helper.dart';

class FirebaseSyncService {
  final DatabaseReference _dbRef = FirebaseDatabase.instance.ref('surveys');

  Future<void> syncUnsyncedSurveys() async {
    final unsynced = await DatabaseHelper().getUnsyncedSurveys();
    for (var survey in unsynced) {
      try {
        await _dbRef.child(survey.id).set(survey.toMap());
        await DatabaseHelper().markAsSynced(survey.id);
      } catch (e) {
        print('Sync failed for survey ${survey.id}: $e');
      }
    }
  }
}
```

