class SurveyForm extends StatefulWidget {
  @override
  _SurveyFormState createState() => _SurveyFormState();
}

class _SurveyFormState extends State<SurveyForm> {
  final _formKey = GlobalKey<FormState>();
  final _titleController = TextEditingController();
  final _notesController = TextEditingController();
  Database? _database;

  @override
  void initState() {
    super.initState();
    _initDatabase();
  }

  Future<void> _initDatabase() async {
    final directory = await getApplicationDocumentsDirectory();
    final path = '${directory.path}/surveys.db';
    _database = await openDatabase(
      path,
      version: 1,
      onCreate: (db, version) {
        return db.execute(
          'CREATE TABLE surveys(id INTEGER PRIMARY KEY, title TEXT, notes TEXT, timestamp TEXT)',
        );
      },
    );
  }

  Future<void> _saveSurveyLocally(String title, String notes) async {
    final timestamp = DateTime.now().toString();
    await _database!.insert(
      'surveys',
      {'title': title, 'notes': notes, 'timestamp': timestamp},
    );
  }

  Future<void> _syncData() async {
    final connectivityResult = await Connectivity().checkConnectivity();
    if (connectivityResult != ConnectivityResult.none) {
      final unsyncedSurveys = await _getUnsyncedSurveys();
      if (unsyncedSurveys.isNotEmpty) {
        for (var survey in unsyncedSurveys) {
          await _sendToServer(survey);
          await _markAsSynced(survey['id']);
        }
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('Data synced successfully!')),
        );
      } else {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('No data to sync.')),
        );
      }
    } else {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('No internet connection.')),
      );
    }
  }

  Future<List<Map<String, dynamic>>> _getUnsyncedSurveys() async {
    return await _database!.query('surveys');
  }

  Future<void> _sendToServer(Map<String, dynamic> survey) async {
    final response = await http.post(
      Uri.parse('https://jsonplaceholder.typicode.com/posts'), // Mock server
      headers: {'Content-Type': 'application/json'},
      body: jsonEncode({
        'title': survey['title'],
        'body': survey['notes'],
        'userId': 1,
      }),
    );
    if (response.statusCode == 201) {
      print('Synced: ${survey['title']}');
    } else {
      print('Sync failed: ${survey['title']}');
    }
  }

  Future<void> _markAsSynced(int id) async {
    await _database!.update(
      'surveys',
      {'timestamp': DateTime.now().toString()},
      where: 'id = ?',
      whereArgs: [id],
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text('Field Survey')),
      body: Padding(
        padding: const EdgeInsets.all(16.0),
        child: Form(
          key: _formKey,
          child: Column(
            children: [
              TextFormField(
                controller: _titleController,
                decoration: InputDecoration(labelText: 'Title'),
                validator: (value) => value!.isEmpty ? 'Title required' : null,
              ),
              TextFormField(
                controller: _notesController,
