import SQLite from 'react-native-sqlite-storage';

const db = SQLite.openDatabase({ name: 'surveys.db', location: 'default' });

export const saveSurvey = (title, data) => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        'INSERT INTO Surveys (title, data, synced) VALUES (?, ?, 0)',
        [title, JSON.stringify(data)],
        (_, result) => resolve(result.insertId),
        (_, error) => reject(error)
      );
    });
  });
};

export const getUnsyncedSurveys = () => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        'SELECT * FROM Surveys WHERE synced = 0',
        [],
        (_, results) => resolve(results.rows._array),
        (_, error) => reject(error)
      );
    });
  });
};

export const markAsSynced = (id) => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        'UPDATE Surveys SET synced = 1 WHERE id = ?',
        [id],
        (_, result) => resolve(result),
        (_, error) => reject(error)
      );
    });
  });
};
```

