```javascript
import React, { useEffect } from 'react';
import { View, Button, Text } from 'react-native';
import { getUnsyncedSurveys, markAsSynced } from './database';
import firebase from 'firebase/app';
import 'firebase/database';

const SyncComponent = () => {
  const handleSync = async () => {
    try {
      const surveys = await getUnsyncedSurveys();
      if (surveys.length === 0) {
        alert('No unsynced surveys.');
        return;
      }

      for (const survey of surveys) {
        const { id, title, data } = survey;
        firebase
          .database()
          .ref(`surveys/${id}`)
          .set({ title, data })
          .then(() => {
            markAsSynced(id);
            alert('Synced to Firebase!');
          });
      }
    } catch (error) {
      console.error(error);
      alert('Sync failed.');
    }
  };

  return (
    <View style={{ padding: 20 }}>
      <Button title="Sync Data" onPress={handleSync} />
    </View>
  );
};

export default SyncComponent;
