import SQLite from 'react-native-sqlite-storage';

const db = SQLite.openDatabase({ name: 'survey.db', location: 'default' });

export const initDB = () => {
  db.transaction(tx => {
    tx.executeSql(
      'CREATE TABLE IF NOT EXISTS surveys (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT, createdAt TEXT)',
      [],
      () => console.log('Surveys table created'),
      (err) => console.error('Error creating surveys table', err)
    );

    tx.executeSql(
      'CREATE TABLE IF NOT EXISTS surveyData (id INTEGER PRIMARY KEY AUTOINCREMENT, surveyId INTEGER, fieldName TEXT, fieldValue TEXT, createdAt TEXT)',
      [],
      () => console.log('SurveyData table created'),
      (err) => console.error('Error creating surveyData table', err)
    );
  });
};

export const saveSurvey = (name) => {
  const now = new Date().toISOString();
  db.transaction(tx => {
    tx.executeSql(
      'INSERT INTO surveys (name, createdAt) VALUES (?, ?)',
      [name, now],
      (tx, results) => {
        const surveyId = results.insertId;
        console.log('Survey saved with ID:', surveyId);
      },
      (err) => console.error('Error saving survey', err)
    );
  });
};

export const saveSurveyData = (surveyId, fieldName, fieldValue) => {
  const now = new Date().toISOString();
  db.transaction(tx => {
    tx.executeSql(
      'INSERT INTO surveyData (surveyId, fieldName, fieldValue, createdAt) VALUES (?, ?, ?, ?)',
      [surveyId, fieldName, fieldValue, now],
      (tx, results) => {
        console.log('Survey data saved:', results.insertId);
      },
      (err) => console.error('Error saving survey data', err)
    );
  });
};

export const getAllSurveys = (callback) => {
  db.transaction(tx => {
    tx.executeSql(
      'SELECT * FROM surveys',
      [],
      (tx, results) => {
        const surveys = [];
        for (let i = 0; i < results.rows.length; i++) {
          surveys.push(results.rows.item(i));
        }
        callback(surveys);
      },
      (err) => console.error('Error fetching surveys', err)
    );
  });
};
```

