// lib/services/hive_service.dart
import 'package:hive/hive.dart';
import '../models/survey.dart';

class HiveService {
  static final Box<Survey> _box = Hive.box<Survey>('surveys');

  static Future<void> saveSurvey(Survey survey) async {
    await _box.put(survey.id, survey);
  }

  static List<Survey> getUnsyncedSurveys() {
    return _box.values.where((survey) => !survey.synced).toList();
  }

  static Future<void> markAsSynced(String id) async {
    final survey = _box.get(id);
    if (survey != null) {
      survey.synced = true;
      await _box.put(id, survey);
    }
  }
}
