import React, { useState, useEffect } from 'react';
import { View, Text, TextInput, Button, FlatList, StyleSheet } from 'react-native';
import SQLite from 'react-native-sqlite-storage';
import NetInfo from '@react-native-community/netinfo';

// Initialize SQLite database
const db = SQLite.openDatabase({ name: 'survey.db', location: 'default' });

// Initialize PouchDB for syncing (Firebase example)
const localDB = new PouchDB('local_survey_db');
const remoteDB = new PouchDB('https://your-firebase.firebaseio.com/surveys');

const App = () => {
  const [surveyText, setSurveyText] = useState('');
  const [surveys, setSurveys] = useState([]);

  // Create table if not exists
  useEffect(() => {
    db.executeSql(
      'CREATE TABLE IF NOT EXISTS surveys (id INTEGER PRIMARY KEY AUTOINCREMENT, text TEXT)',
      [],
      () => console.log('Table created'),
      (err) => console.error('Error creating table', err)
    );
  }, []);

  // Sync with remote database when online
  useEffect(() => {
    const unsubscribe = NetInfo.addEventListener(state => {
      if (state.isConnected) {
        console.log('Connected to network, syncing...');
        syncData();
      }
    });

    return () => unsubscribe();
  }, []);

  // Sync local SQLite with remote PouchDB
  const syncData = async () => {
    try {
      await localDB.sync(remoteDB, { live: false, retry: false });
      console.log('Sync complete');
      fetchLocalSurveys();
    } catch (err) {
      console.error('Sync failed', err);
    }
  };

  // Save survey to SQLite
  const addSurvey = () => {
    if (surveyText.trim()) {
      db.transaction(tx => {
        tx.executeSql(
          'INSERT INTO surveys (text) VALUES (?)',
          [surveyText],
          (_, result) => {
            console.log('Survey saved locally', result.insertId);
            setSurveyText('');
            fetchLocalSurveys();
          },
          (err) => console.error('Error saving survey', err)
        );
      });
    }
  };

  // Fetch surveys from SQLite
  const fetchLocalSurveys = () => {
    db.transaction(tx => {
      tx.executeSql(
        'SELECT * FROM surveys',
        [],
        (_, results) => {
          const rows = [];
          for (let i = 0; i < results.rows.length; i++) {
            rows.push(results.rows.item(i));
          }
          setSurveys(rows);
        },
        (err) => console.error('Error fetching surveys', err)
      );
    });
  };

  return (
    <View style={styles.container}>
      <Text style={styles.title}>Field Survey App</Text>
      <TextInput
        style={styles.input}
        placeholder="Enter survey data"
        value={surveyText}
        onChangeText={setSurveyText}
      />
      <Button title="Save Survey" onPress={addSurvey} />
      <FlatList
        data={surveys}
        keyExtractor={item => item.id.toString()}
        renderItem={({ item }) => (
          <View style={styles.surveyItem}>
            <Text>{item.text}</Text>
          </View>
        )}
      />
    </View>
  );
};

const styles = StyleSheet.create({
  container: { flex: 1, padding: 20, backgroundColor: '#fff' },
  title: { fontSize: 24, fontWeight: 'bold', marginBottom: 10 },
  input: { height: 40, borderColor: 'gray', borderWidth: 1, marginBottom: 10, paddingHorizontal: 10 },
  surveyItem: { padding: 10, borderBottomWidth: 1, borderBottomColor: '#ccc' },
});

export default App;
```

