```javascript
import React, { useState, useEffect } from 'react';
import { View, Text, TextInput, Button, FlatList, StyleSheet, Alert } from 'react-native';
import NetInfo from '@react-native-community/netinfo';
import PouchDB from 'pouchdb-react-native';

// Initialize local and remote databases
const localDB = new PouchDB('surveys');
const remoteDB = new PouchDB('https://your-couchdb-server/surveys', {
  ajax: {
    timeout: 10000,
  },
});

const App = () => {
  const [surveyTitle, setSurveyTitle] = useState('');
  const [surveys, setSurveys] = useState([]);
  const [isOnline, setIsOnline] = useState(false);

  // Check internet connection
  useEffect(() => {
    const unsubscribe = NetInfo.addEventListener(state => {
      setIsOnline(state.isConnected);
    });
    return () => unsubscribe();
  }, []);

  // Sync data with remote DB when online
  useEffect(() => {
    if (isOnline) {
      syncData();
    }
  }, [isOnline]);

  // Sync local and remote DBs
  const syncData = async () => {
    try {
      await localDB.sync(remoteDB, {
        live: false,
        retry: true,
        // Handle conflicts (e.g., choose the latest revision)
        docIds: ['survey-1', 'survey-2', 'survey-3'],
      });
      Alert.alert('Sync Success', 'Data synced with the server.');
      fetchSurveys();
    } catch (error) {
      Alert.alert('Sync Failed', error.message);
    }
  };

  // Fetch surveys from local DB
  const fetchSurveys = async () => {
    try {
      const result = await localDB.allDocs({ include_docs: true });
      setSurveys(result.rows.map(row => row.doc));
    } catch (error) {
      Alert.alert('Error', 'Failed to load surveys.');
    }
  };

  // Save a new survey
  const saveSurvey = async () => {
    if (!surveyTitle.trim()) return;
    try {
      const newSurvey = {
        _id: `survey-${Date.now()}`,
        title: surveyTitle,
        timestamp: new Date().toISOString(),
      };
      await localDB.put(newSurvey);
      setSurveyTitle('');
      fetchSurveys();
    } catch (error) {
      Alert.alert('Error', 'Failed to save survey.');
    }
  };

  return (
    <View style={styles.container}>
      <Text style={styles.title}>Field Survey App</Text>
      <TextInput
        style={styles.input}
        placeholder="Enter survey title"
        value={surveyTitle}
        onChangeText={setSurveyTitle}
      />
      <Button title="Save Survey" onPress={saveSurvey} />
      <Button
        title={isOnline ? 'Sync (Online)' : 'Sync (Offline)'}
        onPress={syncData}
        disabled={!isOnline}
      />
      <FlatList
        data={surveys}
        keyExtractor={item => item._id}
        renderItem={({ item }) => (
          <View style={styles.surveyItem}>
            <Text>{item.title}</Text>
            <Text style={styles.timestamp}>{new Date(item.timestamp).toLocaleString()}</Text>
          </View>
        )}
      />
    </View>
  );
};

const styles = StyleSheet.create({
  container: { padding: 20, flex: 1 },
  title: { fontSize: 24, fontWeight: 'bold', marginBottom: 20 },
  input: { borderWidth: 1, borderColor: '#ccc', padding: 10, marginBottom: 10 },
  surveyItem: { padding: 10, borderBottomWidth: 1, borderBottomColor: '#ccc' },
  timestamp: { color: '#666', fontSize: 12 },
});

export default App;
```

