```javascript
import React, { useState, useEffect } from 'react';
import { View, Text, TextInput, Button, FlatList, Alert } from 'react-native';
import SQLite from 'react-native-sqlite-storage';
import axios from 'axios';
import { NetInfo } from '@react-native-community/netinfo';

// Initialize SQLite database
const db = SQLite.openDatabase({ name: 'SurveyDB', location: 'default' });

// Create table if not exists
db.transaction(tx => {
  tx.executeSql(
    'CREATE TABLE IF NOT EXISTS Surveys (id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT, description TEXT, synced BOOLEAN DEFAULT 0)',
    [],
    () => console.log('Table created'),
    (err) => console.error(err)
  );
});

const App = () => {
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [surveys, setSurveys] = useState([]);

  // Load unsynced surveys from local storage
  useEffect(() => {
    db.transaction(tx => {
      tx.executeSql(
        'SELECT * FROM Surveys WHERE synced = 0',
        [],
        (tx, results) => {
          const rows = [];
          for (let i = 0; i < results.rows.length; i++) {
            rows.push(results.rows.item(i));
          }
          setSurveys(rows);
        },
        (err) => console.error(err)
      );
    });
  }, []);

  // Add a new survey to local storage
  const addSurvey = () => {
    if (!title || !description) return;
    db.transaction(tx => {
      tx.executeSql(
        'INSERT INTO Surveys (title, description) VALUES (?, ?)',
        [title, description],
        () => {
          setTitle('');
          setDescription('');
          Alert.alert('Survey saved offline!');
          refreshSurveys();
        },
        (err) => console.error(err)
      );
    });
  };

  // Sync unsynced surveys to server
  const syncSurveys = async () => {
    const netInfo = await NetInfo.fetch();
    if (!netInfo.isConnected) {
      Alert.alert('No internet connection. Cannot sync.');
      return;
    }

    db.transaction(tx => {
      tx.executeSql(
        'SELECT * FROM Surveys WHERE synced = 0',
        [],
        (tx, results) => {
          const unsynced = [];
          for (let i = 0; i < results.rows.length; i++) {
            unsynced.push(results.rows.item(i));
          }

          if (unsynced.length === 0) {
            Alert.alert('No unsynced surveys.');
            return;
          }

          unsynced.forEach(async (survey) => {
            try {
              await axios.post('https://your-server.com/api/sync', survey);
              tx.executeSql(
                'UPDATE Surveys SET synced = 1 WHERE id = ?',
                [survey.id],
                () => console.log(`Synced survey ID: ${survey.id}`)
              );
            } catch (error) {
              console.error('Sync failed:', error);
              Alert.alert('Sync failed. Retrying...');
            }
          });
        },
        (err) => console.error(err)
      );
    });
  };

  // Refresh local survey list
  const refreshSurveys = () => {
    db.transaction(tx => {
      tx.executeSql(
        'SELECT * FROM Surveys WHERE synced = 0',
        [],
        (tx, results) => {
          const rows = [];
          for (let i = 0; i < results.rows.length; i++) {
            rows.push(results.rows.item(i));
          }
          setSurveys(rows);
        },
        (err) => console.error(err)
      );
    });
  };

  return (
    <View style={{ padding: 20 }}>
      <Text>Field Survey App (Offline-First)</Text>
      <TextInput
        placeholder="Title"
        value={title}
        onChangeText={setTitle}
        style={{ borderWidth: 1, marginVertical: 10, padding: 10 }}
      />
      <TextInput
        placeholder="Description"
        value={description}
        onChangeText={setDescription}
        style={{ borderWidth: 1, marginVertical: 10, padding: 10 }}
      />
      <Button title="Save Survey" onPress={addSurvey} />

      <Text style={{ marginTop: 30 }}>Unsynced Surveys:</Text>
      <FlatList
        data={surveys}
        keyExtractor={item => item.id.toString()}
        renderItem={({ item }) => (
          <View style={{ marginVertical: 10, padding: 10, borderWidth: 1 }}>
            <Text>{item.title}</Text>
            <Text>{item.description}</Text>
          </View>
        )}
      />

      <Button title="Sync Data" onPress={syncSurveys} />
    </View>
  );
};

export default App;
```

