### 📄 `db.js` (PouchDB Setup)
```javascript
import PouchDB from 'pouchdb';
import { Platform } from 'react-native';

// Initialize local and remote databases
const localDB = new PouchDB('surveys', {
  adapter: Platform.OS === 'ios' ? 'idb' : 'indexeddb', // Use IndexedDB for iOS/Android
});

const remoteDB = new PouchDB('http://localhost:5984/surveys');

// Sync local and remote databases
const syncDB = async () => {
  try {
    await localDB.sync(remoteDB, {
      live: true, // Continuous sync
      retry: true, // Retry on failure
    });
    console.log('Sync successful!');
  } catch (error) {
    console.error('Sync failed:', error);
  }
};

export { localDB, syncDB };
```

