```javascript
import React, { useState, useEffect } from 'react';
import { View, Text, TextInput, Button, StyleSheet, Alert } from 'react-native';
import NetInfo from '@react-native-community/netinfo';
import { localDB, syncDB } from './db';

const App = () => {
  const [name, setName] = useState('');
  const [location, setLocation] = useState('');
  const [notes, setNotes] = useState('');
  const [isOnline, setIsOnline] = useState(false);

  // Check internet connectivity
  useEffect(() => {
    const unsubscribe = NetInfo.addEventListener(state => {
      setIsOnline(state.isConnected);
      if (state.isConnected) {
        syncDB(); // Sync when reconnected
      }
    });
    return () => unsubscribe();
  }, []);

  // Submit survey data
  const handleSubmit = async () => {
    if (!name || !location) {
      Alert.alert('Error', 'Name and location are required.');
      return;
    }

    const survey = { name, location, notes, timestamp: new Date().toISOString() };

    try {
      await localDB.put({
        _id: Date.now().toString(), // Unique ID
        ...survey,
      });
      Alert.alert('Success', 'Survey saved locally!');
    } catch (error) {
      Alert.alert('Error', 'Failed to save survey.');
      console.error('Local DB error:', error);
    }
  };

  return (
    <View style={styles.container}>
      <Text style={styles.title}>Field Survey App</Text>
      <TextInput
        placeholder="Name"
        value={name}
        onChangeText={setName}
        style={styles.input}
      />
      <TextInput
        placeholder="Location"
        value={location}
        onChangeText={setLocation}
        style={styles.input}
      />
      <TextInput
        placeholder="Notes"
        value={notes}
        onChangeText={setNotes}
        style={styles.input}
        multiline
      />
      <Button title="Submit Survey" onPress={handleSubmit} />
      <Text style={styles.status}>
        {isOnline ? 'Online (Syncing...)' : 'Offline (Saving locally)'}
      </Text>
    </View>
  );
};

const styles = StyleSheet.create({
  container: { flex: 1, padding: 20, justifyContent: 'center' },
  title: { fontSize: 24, fontWeight: 'bold', marginBottom: 20 },
  input: { borderWidth: 1, borderColor: '#ccc', padding: 10, marginBottom: 15 },
  status: { marginTop: 20, textAlign: 'center', color: '#555' },
});

export default App;
```

