const express = require('express');
const http = require('http');
const socketIO = require('socket.io');
const mongoose = require('mongoose');
const stripe = require('stripe')('your_stripe_secret_key');
const cors = require('cors');

const app = express();
const server = http.createServer(app);
const io = socketIO(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST"]
  }
});

// Middleware
app.use(cors());
app.use(express.json());

// MongoDB Connection
mongoose.connect('mongodb://localhost:27017/messaging-app', {
  useNewUrlParser: true,
  useUnifiedTopology: true
});

// Message Schema
const messageSchema = new mongoose.Schema({
  sender: String,
  receiver: String,
  content: String,
  timestamp: { type: Date, default: Date.now }
});
const Message = mongoose.model('Message', messageSchema);

// Payment Schema
const paymentSchema = new mongoose.Schema({
  userId: String,
  amount: Number,
  currency: String,
  description: String,
  timestamp: { type: Date, default: Date.now }
});
const Payment = mongoose.model('Payment', paymentSchema);

// Socket.IO for Real-Time Messaging
io.on('connection', (socket) => {
  console.log('User connected:', socket.id);

  // Send message
  socket.on('sendMessage', async (data) => {
    const { sender, receiver, content } = data;
    const message = new Message({ sender, receiver, content });
    await message.save();

    io.to(receiver).emit('receiveMessage', { sender, content });
  });

  // Handle disconnect
  socket.on('disconnect', () => {
    console.log('User disconnected:', socket.id);
  });
});

// In-App Monetization (Stripe Payment)
app.post('/create-payment-intent', async (req, res) => {
  const { amount, currency, description } = req.body;

  try {
    const paymentIntent = await stripe.paymentIntents.create({
      amount: Math.round(amount * 100), // Stripe expects cents
      currency: currency,
      description: description,
    });

    res.send({
      clientSecret: paymentIntent.client_secret,
    });
  } catch (err) {
    res.status(500).send({ error: err.message });
  }
});

// Save payment to database
app.post('/save-payment', async (req, res) => {
  const { userId, amount, currency, description } = req.body;
  const payment = new Payment({ userId, amount, currency, description });
  await payment.save();
  res.status(200).send({ message: 'Payment saved' });
});

// Start server
const PORT = 5000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

