// App.js
import React, { useState, useEffect } from 'react';
import io from 'socket.io-client';
import { getAuth, onAuthStateChanged } from 'firebase/auth';
import { getDatabase, ref, onValue } from 'firebase/database';

const socket = io('http://localhost:3000');

const App = () => {
  const [message, setMessage] = useState('');
  const [messages, setMessages] = useState([]);
  const [user, setUser] = useState(null);
  const [isSubscribed, setIsSubscribed] = useState(false);

  // Firebase setup
  const auth = getAuth();
  const database = getDatabase();

  // Check user authentication
  useEffect(() => {
    onAuthStateChanged(auth, (user) => {
      if (user) {
        setUser(user.email);
      } else {
        setUser(null);
      }
    });
  }, [auth]);

  // Fetch messages from Firebase
  useEffect(() => {
    const messagesRef = ref(database, 'messages');
    onValue(messagesRef, (snapshot) => {
      const data = snapshot.val();
      if (data) {
        setMessages(Object.values(data));
      }
    });
  }, [database]);

  // Send message
  const sendMessage = () => {
    if (user && message.trim()) {
      const newMessage = { user, text: message, timestamp: Date.now() };
      socket.emit('sendMessage', newMessage);
      setMessage('');
    }
  };

  // Check subscription status
  useEffect(() => {
    if (user) {
      // In a real app, this would query Stripe's API
      setIsSubscribed(true); // Simulated for demo
    }
  }, [user]);

  return (
    <div>
      <h1>Real-Time Messaging App</h1>
      {user ? (
        <div>
          <p>Welcome, {user}</p>
          <button onClick={() => setIsSubscribed(!isSubscribed)}>
            {isSubscribed ? 'Cancel Subscription' : 'Subscribe'}
          </button>
        </div>
      ) : (
        <p>Login to send messages</p>
      )}
      <div>
        {messages.map((msg, i) => (
          <div key={i}>
            <strong>{msg.user}</strong>: {msg.text}
          </div>
        ))}
      </div>
      <input
        type="text"
        value={message}
        onChange={(e) => setMessage(e.target.value)}
        placeholder="Type a message"
      />
      <button onClick={sendMessage}>Send</button>
    </div>
  );
};

export default App;
```

