```javascript
// App.js
import React, { useEffect, useState } from "react";
import io from "socket.io-client";

const socket = io("http://localhost:3000");

function App() {
  const [messages, setMessages] = useState([]);
  const [input, setInput] = useState("");
  const [paymentIntent, setPaymentIntent] = useState(null);

  // Load messages on connect
  useEffect(() => {
    socket.on("loadMessages", (msgs) => {
      setMessages(msgs);
    });

    socket.on("receiveMessage", (msg) => {
      setMessages((prev) => [...prev, msg]);
    });

    return () => {
      socket.off("loadMessages");
      socket.off("receiveMessage");
    };
  }, []);

  // Handle message submission
  const sendMessage = () => {
    if (input.trim()) {
      const message = { user: "User", text: input };
      socket.emit("sendMessage", message);
      setInput("");
    }
  };

  // Handle payment
  const handlePayment = async () => {
    try {
      const response = await fetch("http://localhost:3000/create-payment-intent", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ amount: 1000 }), // $10
      });
      const data = await response.json();
      setPaymentIntent(data.clientSecret);
    } catch (error) {
      console.error("Payment error:", error);
    }
  };

  return (
    <div>
      <h1>Social Messaging App</h1>
      <div>
        {messages.map((msg, i) => (
          <div key={i}>
            <strong>{msg.user}:</strong> {msg.text}
          </div>
        ))}
      </div>
      <input
        value={input}
        onChange={(e) => setInput(e.target.value)}
        onKeyPress={(e) => e.key === "Enter" && sendMessage()}
        placeholder="Type a message..."
      />
      <button onClick={sendMessage}>Send</button>
      <hr />
      <button onClick={handlePayment}>Pay $10 (In-App)</button>
      {paymentIntent && (
        <div>
          <p>Payment Intent Created. Use Stripe Elements to process.</p>
        </div>
      )}
    </div>
  );
}

export default App;
```

