import React, { useEffect, useState } from 'react';
import { View, Text, TextInput, Button, FlatList, StyleSheet, TouchableOpacity } from 'react-native';
import firebase from '@react-native-firebase/app';
import database from '@react-native-firebase/database';
import admob from '@react-native-firebase/admob';

// Initialize Firebase
const firebaseConfig = {
  apiKey: "YOUR_API_KEY",
  authDomain: "YOUR_PROJECT_ID.firebaseapp.com",
  databaseURL: "https://YOUR_PROJECT_ID.firebaseio.com",
  projectId: "YOUR_PROJECT_ID",
  storageBucket: "YOUR_PROJECT_ID.appspot.com",
  messagingSenderId: "YOUR_SENDER_ID",
  appId: "YOUR_APP_ID",
};
firebase.initializeApp(firebaseConfig);

// Reference to Firebase Realtime Database
const db = database().ref('/messages');

export default function App() {
  const [message, setMessage] = useState('');
  const [messages, setMessages] = useState([]);

  // Fetch real-time messages
  useEffect(() => {
    db.on('value', (snapshot) => {
      const data = snapshot.val();
      if (data) {
        const sorted = Object.keys(data).sort((a, b) => data[a].timestamp - data[b].timestamp);
        setMessages(sorted.map(key => ({ id: key, ...data[key] })));
      }
    });
  }, []);

  // Send message
  const sendMessage = () => {
    if (message.trim()) {
      const newMessage = {
        text: message,
        timestamp: Date.now(),
      };
      db.push(newMessage);
      setMessage('');
    }
  };

  // Show AdMob interstitial ad
  const showAd = () => {
    admob
      .interstitial()
      .load()
      .then(() => admob.interstitial().show())
      .catch((error) => console.error('Ad load failed:', error));
  };

  return (
    <View style={styles.container}>
      <Text style={styles.title}>Social Messenger</Text>
      <FlatList
        data={messages}
        keyExtractor={(item) => item.id}
        renderItem={({ item }) => <Text style={styles.message}>{item.text}</Text>}
      />
      <View style={styles.inputContainer}>
        <TextInput
          style={styles.input}
          value={message}
          onChangeText={setMessage}
          placeholder="Type a message..."
        />
        <Button title="Send" onPress={sendMessage} />
      </View>
      <TouchableOpacity style={styles.adButton} onPress={showAd}>
        <Text style={styles.adText}>Watch Ad for Premium Feature</Text>
      </TouchableOpacity>
    </View>
  );
}

const styles = StyleSheet.create({
  container: { flex: 1, padding: 16, backgroundColor: '#fff' },
  title: { fontSize: 24, fontWeight: 'bold', marginBottom: 16 },
  message: { fontSize: 16, marginBottom: 8 },
  inputContainer: { flexDirection: 'row', justifyContent: 'space-between', marginTop: 16 },
  input: { flex: 1, borderWidth: 1, borderColor: '#ccc', padding: 8, marginRight: 8 },
  adButton: { marginTop: 16, backgroundColor: '#f44336', padding: 12, borderRadius: 8 },
  adText: { color: '#fff', textAlign: 'center' },
});
```

