import React, { useState, useEffect } from 'react';
import io from 'socket.io-client';

const socket = io('http://localhost:5000');

function App() {
  const [message, setMessage] = useState('');
  const [messages, setMessages] = useState([]);
  const [showAd, setShowAd] = useState(false);

  useEffect(() => {
    // Listen for incoming messages
    socket.on('receiveMessage', (msg) => {
      setMessages((prev) => [...prev, msg]);
    });

    // Listen for ad toggle
    socket.on('adToggled', (isVisible) => {
      setShowAd(isVisible);
    });

    return () => {
      socket.off('receiveMessage');
      socket.off('adToggled');
    };
  }, []);

  const sendMessage = () => {
    if (message.trim()) {
      socket.emit('sendMessage', message);
      setMessage('');
    }
  };

  const toggleAd = () => {
    socket.emit('toggleAd');
  };

  return (
    <div className="App">
      <h1>Real-Time Messaging App</h1>
      <div>
        <ul>
          {messages.map((msg, index) => (
            <li key={index}>{msg}</li>
          ))}
        </ul>
        <input
          type="text"
          value={message}
          onChange={(e) => setMessage(e.target.value)}
          placeholder="Type a message..."
        />
        <button onClick={sendMessage}>Send</button>
      </div>
      {showAd && (
        <div className="ad">
          <h3>Ad: Watch this video to unlock premium features!</h3>
          <button onClick={toggleAd}>Dismiss</button>
        </div>
      )}
    </div>
  );
}

export default App;
