// server.js
const express = require('express');
const http = require('http');
const socketIO = require('socket.io');
const cors = require('cors');

const app = express();
const server = http.createServer(app);
const io = socketIO(server, { cors: { origin: '*' } });

app.use(cors());
app.use(express.json());

// Mock database
const messages = [];
const users = {};

// Handle WebSocket connections
io.on('connection', (socket) => {
  console.log('User connected:', socket.id);

  // Join a user to a room (e.g., chat room)
  socket.on('joinRoom', (roomId) => {
    socket.join(roomId);
    io.to(roomId).emit('message', { text: `${socket.id} has joined the room`, user: 'System' });
  });

  // Handle new message
  socket.on('sendMessage', (data) => {
    const { roomId, text, user } = data;
    messages.push({ roomId, text, user, timestamp: new Date() });
    io.to(roomId).emit('message', { text, user, timestamp: new Date() });
  });

  // Handle in-app purchase (mock)
  socket.on('makePurchase', (data) => {
    const { userId, amount, currency } = data;
    // Simulate payment success
    const success = true;
    if (success) {
      io.to(userId).emit('purchaseSuccess', { amount, currency });
    } else {
      io.to(userId).emit('purchaseFailed', { message: 'Payment failed' });
    }
  });

  socket.on('disconnect', () => {
    console.log('User disconnected:', socket.id);
  });
});

// Start server
const PORT = 5000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
