```javascript
// App.jsx
import React, { useEffect, useState } from 'react';
import { Line } from 'react-chartjs-2';
import io from 'socket.io-client';

const socket = io('http://localhost:3000');

const App = () => {
  const [formData, setFormData] = useState({ name: '', value: '' });
  const [chartData, setChartData] = useState({
    labels: [],
    datasets: [
      {
        label: 'Data Values',
        data: [],
        borderColor: 'rgba(75, 192, 192, 1)',
        fill: false,
      },
    ],
  });
  const [tableData, setTableData] = useState([]);

  // Handle form input
  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  // Submit form data
  const handleSubmit = (e) => {
    e.preventDefault();
    fetch('http://localhost:3000/submit', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(formData),
    });
    setFormData({ name: '', value: '' });
  };

  // Listen for real-time data updates
  useEffect(() => {
    socket.on('data', (newData) => {
      setTableData((prev) => [newData, ...prev].slice(0, 10)); // Keep last 10 entries
      setChartData((prev) => {
        const newLabels = [...prev.labels, newData.timestamp].slice(-10);
        const newDataPoints = [...prev.datasets[0].data, parseFloat(newData.value)].slice(-10);
        return {
          labels: newLabels,
          datasets: [
            {
              ...prev.datasets[0],
              data: newDataPoints,
            },
          ],
        };
      });
    });

    socket.on('initialData', (initialData) => {
      setTableData(initialData);
      setChartData({
        labels: initialData.map((d) => d.timestamp),
        datasets: [
          {
            label: 'Data Values',
            data: initialData.map((d) => parseFloat(d.value)),
            borderColor: 'rgba(75, 192, 192, 1)',
            fill: false,
          },
        ],
      });
    });

    return () => {
      socket.off('data');
      socket.off('initialData');
    };
  }, []);

  return (
    <div style={{ padding: '20px' }}>
      <h1>Interactive Dashboard</h1>
      <form onSubmit={handleSubmit}>
        <input
          type="text"
          name="name"
          value={formData.name}
          onChange={handleChange}
          placeholder="Name"
          required
        />
        <input
          type="number"
          name="value"
          value={formData.value}
          onChange={handleChange}
          placeholder="Value"
          required
        />
        <button type="submit">Submit</button>
      </form>

      <div style={{ marginTop: '30px' }}>
        <h2>Real-Time Chart</h2>
        <Line data={chartData} />
      </div>

      <div style={{ marginTop: '30px' }}>
        <h2>Latest Data</h2>
        <table border="1" cellPadding="10" style={{ width: '100%' }}>
          <thead>
            <tr>
              <th>Name</th>
              <th>Value</th>
              <th>Timestamp</th>
            </tr>
          </thead>
          <tbody>
            {tableData.map((item, index) => (
              <tr key={index}>
                <td>{item.name}</td>
                <td>{item.value}</td>
                <td>{item.timestamp}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default App;
```

