```javascript
const express = require('express');
const http = require('http');
const socketIO = require('socket.io');

const app = express();
const server = http.createServer(app);
const io = socketIO(server);

// Serve static files
app.use(express.static('public'));

// Real-time data source (simulated)
let counter = 0;
const incrementRate = 1; // Default increment rate

// Handle form submission
app.post('/update-rate', (req, res) => {
  const newRate = parseInt(req.body.rate);
  if (!isNaN(newRate)) {
    incrementRate.value = newRate;
    io.emit('rateUpdated', { rate: newRate });
  }
  res.sendStatus(200);
});

// Simulate real-time data updates
setInterval(() => {
  counter += incrementRate;
  io.emit('dataUpdate', { value: counter });
}, 1000);

server.listen(3000, () => {
  console.log('Server running on http://localhost:3000');
});
```

