<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Interactive Dashboard</title>
  <script src="https://cdn.jsdelivr.net/npm/chart.js"></script>
  <script src="/socket.io/socket.io.js"></script>
</head>
<body>
  <h1>Real-Time Dashboard</h1>
  <form id="rateForm">
    <label for="rateInput">Update Rate:</label>
    <input type="number" id="rateInput" name="rate" min="1" />
    <button type="submit">Submit</button>
  </form>
  <canvas id="dataChart" width="400" height="200"></canvas>

  <script>
    const socket = io();
    const ctx = document.getElementById('dataChart').getContext('2d');
    const chart = new Chart(ctx, {
      type: 'line',
      data: {
        labels: [],
        datasets: [{
          label: 'Real-Time Data',
          data: [],
          borderColor: 'rgba(75, 192, 192, 1)',
          fill: false,
        }]
      },
      options: {
        responsive: false,
        scales: {
          x: {
            type: 'time',
            time: {
              unit: 'second'
            }
          }
        }
      }
    });

    // Handle form submission
    document.getElementById('rateForm').addEventListener('submit', (e) => {
      e.preventDefault();
      const rate = parseInt(document.getElementById('rateInput').value);
      if (!isNaN(rate)) {
        fetch('/update-rate', {
          method: 'POST',
          headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
          body: `rate=${rate}`
        });
      }
    });

    // Listen for real-time updates
    socket.on('dataUpdate', (data) => {
      const now = new Date();
      chart.data.labels.push(now);
      chart.data.datasets[0].data.push(data.value);
      chart.update();
    });

    socket.on('rateUpdated', (data) => {
      alert(`Update rate changed to ${data.rate} per second`);
    });
  </script>
