### 🔧 Backend: `server.js` (Node.js + Express + Socket.IO)
```javascript
const express = require('express');
const http = require('http');
const socketIO = require('socket.io');

const app = express();
const server = http.createServer(app);
const io = socketIO(server);

app.use(express.static('public'));

// Store real-time data
let dataPoints = [];

io.on('connection', (socket) => {
  console.log('A client connected');

  // Send initial data to the client
  socket.emit('initialData', dataPoints);

  // Handle form submission
  socket.on('submitData', (input) => {
    const timestamp = new Date().toLocaleTimeString();
    dataPoints.push({ x: timestamp, y: parseFloat(input) });
    io.emit('updateChart', dataPoints); // Broadcast to all clients
  });

  socket.on('disconnect', () => {
    console.log('A client disconnected');
  });
});

const PORT = 3000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

