  "doubleclick.net",
  "adsense.com",
  "taboola.com",
  "taboola.io",
  "analytics.google.com"
];

// Function to block tracking scripts
function blockTrackingScripts() {
  const scripts = document.querySelectorAll("script[src]");
  scripts.forEach(script => {
    const src = script.src.toLowerCase();
    const domain = new URL(src).hostname;

    if (trackingDomains.includes(domain)) {
      script.remove();
      console.log(`Blocked tracking script from: ${src}`);
    }
  });
}

// Monitor for dynamically added scripts (e.g., via JS)
const observer = new MutationObserver(mutations => {
  mutations.forEach(mutation => {
    if (mutation.type === "childList") {
      mutation.addedNodes.forEach(node => {
        if (node.tagName === "SCRIPT") {
          const src = node.src.toLowerCase();
          const domain = new URL(src).hostname;

          if (trackingDomains.includes(domain)) {
            node.remove();
            console.log(`Blocked dynamically added tracking script from: ${src}`);
          }
        }
      });
    }
  });
});

observer.observe(document.body, {
  childList: true,
  subtree: true
});

// Run the initial block
blockTrackingScripts();
