// List of known tracking domains (update regularly)
const trackingDomains = [
  "doubleclick.net",
  "google-analytics.com",
  "facebook.com",
  "pixel.me.com",
  "adobe.com",
  "quantcast.com"
];

// Function to block scripts from tracking domains
function blockTrackingScripts() {
  const scripts = document.querySelectorAll("script");
  scripts.forEach(script => {
    const src = script.src || "";
    const domain = getDomainFromUrl(src);
    if (trackingDomains.includes(domain)) {
      script.remove();
    }
  });
}

// Helper function to extract domain from URL
function getDomainFromUrl(url) {
  try {
    const hostname = new URL(url).hostname;
    return hostname.split(".").slice(-2).join(".");
  } catch {
    return "";
  }
}

// Run on DOM content load
document.addEventListener("DOMContentLoaded", blockTrackingScripts);
```

