```javascript
// Configuration
const NUM_STOCKS = 50;
const NUM_DAYS = 30;
const CELL_SIZE = 20;

// Color scale: low price (blue) to high price (red)
const colorScale = d3.scaleSequential()
  .domain([0, 100])
  .interpolator(d3.interpolateBlues);

// Simulated real-time data
let stockData = [];

// Generate initial data
function generateData() {
  stockData = [];
  for (let i = 0; i < NUM_STOCKS; i++) {
    const stock = {
      id: `STOCK-${i + 1}`,
      prices: []
    };
    for (let j = 0; j < NUM_DAYS; j++) {
      stock.prices.push(Math.random() * 100);
    }
    stockData.push(stock);
  }
}

// Update heatmap with new data
function updateHeatmap() {
  const svg = d3.select("#heatmap");
  const width = svg.node().clientWidth;
  const height = svg.node().clientHeight;

  // Clear existing content
  svg.selectAll("*").remove();

  // Set up zoom behavior
  const zoom = d3.zoom()
    .scaleExtent([0.5, 4])
    .on("zoom", (event) => {
      const transform = event.transform;
      svg.selectAll("rect")
        .attr("transform", transform);
    });

  svg.call(zoom);

  // Create a group for the heatmap
  const g = svg.append("g");

  // Create grid of cells
  const cells = g.selectAll("rect")
    .data(stockData)
    .enter()
    .append("g")
    .attr("transform", (d, i) => `translate(${i * CELL_SIZE}, 0)`);

  cells.selectAll("rect")
    .data(d => d.prices)
    .enter()
    .append("rect")
    .attr("width", CELL_SIZE)
    .attr("height", CELL_SIZE)
    .attr("fill", d => colorScale(d))
    .attr("x", (_, i) => i * CELL_SIZE)
    .attr("y", (_, i) => 0)
    .attr("class", "cell");

  // Add labels (optional)
  g.selectAll("text")
    .data(stockData)
    .enter()
    .append("text")
    .text(d => d.id)
    .attr("x", (_, i) => i * CELL_SIZE + CELL_SIZE / 2)
    .attr("y", -5)
    .attr("text-anchor", "middle")
    .style("font-size", "10px");
}

// Simulate real-time updates
function simulateRealTimeUpdates() {
  setInterval(() => {
    stockData.forEach(stock => {
      const lastPrice = stock.prices[stock.prices.length - 1];
      const newPrice = lastPrice + (Math.random() - 0.5) * 5;
      stock.prices.push(newPrice);
      if (stock.prices.length > NUM_DAYS) stock.prices.shift();
    });
    updateHeatmap();
  }, 1000);
}

// Initialize
generateData();
updateHeatmap();
simulateRealTimeUpdates();
```

