// Configuration
const NUM_STOCKS = 50;
const NUM_TIMES = 50;
const CELL_SIZE = 10;
const WIDTH = NUM_STOCKS * CELL_SIZE;
const HEIGHT = NUM_TIMES * CELL_SIZE;

// Color scale
const colorScale = d3.scaleLinear()
  .domain([0, 1])
  .range(["#0000ff", "#ff0000"]);

// Create SVG
