  .data(data.flat(), (d, i) => i)
  .enter()
  .append("rect")
  .attr("x", (d, i) => (i % NUM_STOCKS) * CELL_SIZE)
  .attr("y", (d, i) => Math.floor(i / NUM_STOCKS) * CELL_SIZE)
  .attr("width", CELL_SIZE)
  .attr("height", CELL_SIZE)
  .attr("fill", d => colorScale(d));

// Zoom behavior
const zoom = d3.zoom()
  .scaleExtent([0.5, 4])
  .on("zoom", (event) => {
    g.attr("transform", event.transform);
  });

svg.call(zoom);

// Real-time update
setInterval(() => {
  // Update data (simulate new stock prices)
  data = data.map(row => {
    return row.map((val, i) => {
      if (i === row.length - 1) {
        return Math.random(); // New value at the end
      }
      return val; // Keep previous values
    });
  });

  // Redraw
  const updatedCells = g.selectAll("rect")
    .data(data.flat(), (d, i) => i);

  updatedCells
    .attr("fill", d => colorScale(d));

  // Append new cells if needed (for scrolling effect)
  if (data[0].length > NUM_TIMES) {
    const newCell = g.append("rect")
      .attr("x", (data[0].length - 1) % NUM_STOCKS * CELL_SIZE)
      .attr("y", Math.floor((data[0].length - 1) / NUM_STOCKS) * CELL_SIZE)
      .attr("width", CELL_SIZE)
      .attr("height", CELL_SIZE)
      .attr("fill", d => colorScale(1));
  }
}, 1000);
