```javascript
// Constants
const width = 600;
const height = 400;
const rows = 20;
const cols = 30;
const cellSize = 20;

// Create SVG
const svg = d3.select("svg");
const g = svg.append("g");

// Color scale: red to green for price changes
const color = d3.scaleLinear()
  .domain([-10, 0, 10])
  .range(["red", "white", "green"]);

// Generate mock stock data (price changes)
function generateData() {
  return d3.range(rows * cols).map(() => d3.randomNormal(0, 2)());
}

// Initial data
let data = generateData();

// Create heatmap cells
function drawHeatmap() {
  const cells = g.selectAll("rect")
    .data(data, (d, i) => i);

  cells.enter()
    .append("rect")
    .attr("x", (d, i) => (i % cols) * cellSize)
    .attr("y", (d, i) => Math.floor(i / cols) * cellSize)
    .attr("width", cellSize)
    .attr("height", cellSize)
    .attr("fill", d => color(d))
    .merge(cells)
    .attr("fill", d => color(d));

  cells.exit().remove();
}

// Zoom/pan behavior
const zoom = d3.zoom()
  .scaleExtent([0.5, 4])
  .on("zoom", (event) => {
    g.attr("transform", event.transform);
  });

svg.call(zoom);

// Real-time updates (every 2 seconds)
setInterval(() => {
  data = data.map(d => d + d3.randomNormal(0, 0.5)());
  drawHeatmap();
}, 2000);

// Initial draw
drawHeatmap();
```

