```javascript
// server.js
const express = require('express');
const http = require('http');
const { app, server } = require('./server');

const app = express();
const httpServer = http.createServer(app);
const io = require('socket.io')(httpServer, {
  cors: {
    origin: "*",
  },
});

let boardState = {
  columns: [
    { id: 'todo', title: 'To Do', tasks: ['Task 1', 'Task 2'] },
    { id: 'inprogress', title: 'In Progress', tasks: ['Task 3'] },
    { id: 'done', title: 'Done', tasks: [] },
  ],
};

io.on('connection', (socket) => {
  console.log('Client connected:', socket.id);

  // Sync initial board state
  socket.emit('syncBoard', boardState);

  // Handle task move
  socket.on('moveTask', (data) => {
    const { fromColumn, toColumn, taskId } = data;
    const fromIndex = boardState.columns.findIndex(col => col.id === fromColumn);
    const toIndex = boardState.columns.findIndex(col => col.id === toColumn);

    if (fromIndex === -1 || toIndex === -1) return;

    const task = boardState.columns[fromIndex].tasks.find(t => t === taskId);
    if (!task) return;

    boardState.columns[fromIndex].tasks = boardState.columns[fromIndex].tasks.filter(t => t !== taskId);
    boardState.columns[toIndex].tasks.push(taskId);

    io.emit('updateBoard', boardState);
  });

  socket.on('disconnect', () => {
    console.log('Client disconnected:', socket.id);
  });
});

httpServer.listen(3001, () => {
  console.log('Server running on http://localhost:3001');
});
```

