# Install dependencies
npm install react react-dom socket.io-client
```

```tsx
// App.tsx
import React, { useState, useEffect } from 'react';
import io from 'socket.io-client';

const socket = io('http://localhost:3001');

const App: React.FC = () => {
  const [board, setBoard] = useState({
    columns: [
      { id: 'todo', title: 'To Do', tasks: ['Task 1', 'Task 2'] },
      { id: 'inprogress', title: 'In Progress', tasks: ['Task 3'] },
      { id: 'done', title: 'Done', tasks: [] },
    ],
  });

  useEffect(() => {
    socket.on('syncBoard', (data) => {
      setBoard(data);
    });

    socket.on('updateBoard', (data) => {
      setBoard(data);
    });

    return () => {
      socket.off('syncBoard');
      socket.off('updateBoard');
    };
  }, []);

  const handleDragStart = (e: React.DragEvent, taskId: string) => {
    e.dataTransfer.setData('text/plain', taskId);
  };

  const handleDrop = (e: React.DragEvent, columnId: string) => {
    e.preventDefault();
    const taskId = e.dataTransfer.getData('text/plain');
    const fromColumn = board.columns.find(col => col.tasks.includes(taskId))?.id || 'todo';
    const toColumn = columnId;

    if (fromColumn === toColumn) return;

    socket.emit('moveTask', { fromColumn, toColumn, taskId });
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
  };

  return (
    <div style={{ display: 'flex', gap: '20px', padding: '20px' }}>
      {board.columns.map((column) => (
        <div
          key={column.id}
          onDrop={(e) => handleDrop(e, column.id)}
          onDragOver={handleDragOver}
          style={{
            border: '1px solid #ccc',
            padding: '10px',
            width: '300px',
            minHeight: '200px',
          }}
        >
          <h3>{column.title}</h3>
          {column.tasks.map((task, index) => (
            <div
              key={task}
              draggable
              onDragStart={(e) => handleDragStart(e, task)}
              style={{
                padding: '8px',
                margin: '5px 0',
                backgroundColor: '#f0f0f0',
                cursor: 'grab',
              }}
            >
              {task}
            </div>
          ))}
        </div>
      ))}
    </div>
  );
};

export default App;
```

