```javascript
// TaskBoard.js
import React, { useEffect, useState } from 'react';
import { DndProvider, Droppable, Draggable } from 'react-beautiful-dnd';
import { ref, onValue, update } from './Firebase';
import Task from './Task';

const TaskBoard = () => {
  const [tasks, setTasks] = useState({});
  const [columns, setColumns] = useState([]);

  useEffect(() => {
    const tasksRef = ref(database, 'tasks');
    onValue(tasksRef, (snapshot) => {
      const data = snapshot.val();
      if (data) {
        setTasks(data);
      }
    });
  }, []);

  const onDragEnd = (result) => {
    const { destination, source, draggableId } = result;

    if (!destination) return;

    const sourceColumn = columns[source.droppableId];
    const destColumn = columns[destination.droppableId];

    if (sourceColumn === destColumn) return;

    const task = tasks[draggableId];
    const updatedTasks = { ...tasks };

    // Remove from source column
    delete updatedTasks[draggableId];

    // Add to destination column
    updatedTasks[draggableId] = {
      ...task,
      columnId: destination.droppableId,
    };

    setTasks(updatedTasks);

    update(ref(database, 'tasks'), updatedTasks);
  };

  const addTask = (columnId, title) => {
    const newTaskRef = push(ref(database, 'tasks'));
    const taskId = newTaskRef.key;
    set(ref(database, `tasks/${taskId}`), {
      id: taskId,
      title,
      columnId,
    });
  };

  const deleteTask = (taskId) => {
    const updatedTasks = { ...tasks };
    delete updatedTasks[taskId];
    update(ref(database, 'tasks'), updatedTasks);
  };

  return (
    <DndProvider backend="HTML5Backend">
      <div className="task-board">
        {columns.map((column) => (
          <Droppable key={column.id} droppableId={column.id}>
            {(provided) => (
              <div
                ref={provided.innerRef}
                {...provided.droppableProps}
                className="column"
              >
                <h3>{column.title}</h3>
                {Object.values(tasks).filter(
                  (task) => task.columnId === column.id
                ).map((task) => (
                  <Draggable
                    key={task.id}
                    draggableId={task.id}
                    index={0}
                  >
                    {(provided) => (
                      <div
                        ref={provided.innerRef}
                        {...provided.draggableProps}
                        {...provided.dragHandleProps}
                      >
                        <Task
                          task={task}
                          columnId={column.id}
                          onTaskMove={deleteTask}
                        />
                      </div>
                    )}
                  </Draggable>
                ))}
                {provided.placeholder}
                <button onClick={() => addTask(column.id, `New Task ${Date.now()}`)}>Add Task</button>
              </div>
            )}
          </Droppable>
        ))}
      </div>
    </DndProvider>
  );
};

export default TaskBoard;
```

