// frontend/src/App.js
import React, { useEffect, useState } from 'react';
import { DndProvider, useDrag, useDrop } from 'react-beautiful-dnd';
import { io } from 'socket.io-client';

const socket = io('http://localhost:3001');

const Task = ({ task, index, columnId, onMoveTask }) => {
  const [{ isDragging }, drag] = useDrag({
    type: 'task',
    item: { id: task.id, column: task.column, index },
    collect: (monitor) => ({
      isDragging: monitor.isDragging(),
    }),
  });

  const opacity = isDragging ? 0 : 1;

  return (
    <div
      ref={drag}
      style={{ opacity, margin: '8px 0', padding: '8px', border: '1px solid #ccc' }}
    >
      {task.title}
    </div>
  );
};

const Column = ({ columnId, tasks, onMoveTask }) => {
  const [{ handlerId }, drop] = useDrop({
    accept: 'task',
    hover: (item, monitor) => {
      const hoverIndex = tasks.findIndex((task) => task.id === item.id);
      if (hoverIndex !== -1 && item.index !== hoverIndex) {
        const task = tasks[hoverIndex];
        const newTasks = [...tasks];
        newTasks.splice(item.index, 1);
        newTasks.splice(hoverIndex, 0, task);
        onMoveTask(newTasks);
      }
    },
    collect: (monitor) => ({
      handlerId: monitor.getHandlerId(),
    }),
  });

  return (
    <div ref={drop} style={{ padding: '16px', border: '1px solid #333' }}>
      <h3>{columnId}</h3>
      {tasks.map((task, index) => (
        <Task key={task.id} task={task} index={index} columnId={columnId} onMoveTask={onMoveTask} />
      ))}
    </div>
  );
};

const App = () => {
  const [tasks, setTasks] = useState([]);

  useEffect(() => {
    socket.on('loadTasks', (loadedTasks) => {
      setTasks(loadedTasks);
    });

    socket.on('updateTask', (updatedTask) => {
      setTasks((prevTasks) =>
        prevTasks.map((task) => (task.id === updatedTask.id ? updatedTask : task))
      );
    });

    return () => {
      socket.off('loadTasks');
      socket.off('updateTask');
    };
  }, []);

  const onMoveTask = (updatedTasks) => {
    socket.emit('moveTask', updatedTasks);
  };

  return (
    <DndProvider backend="HTML5Backend">
      <div style={{ display: 'flex', gap: '20px', padding: '20px' }}>
        <Column columnId="To Do" tasks={tasks.filter((t) => t.column === 'To Do')} onMoveTask={onMoveTask} />
        <Column columnId="In Progress" tasks={tasks.filter((t) => t.column === 'In Progress')} onMoveTask={onMoveTask} />
        <Column columnId="Done" tasks={tasks.filter((t) => t.column === 'Done')} onMoveTask={onMoveTask} />
      </div>
    </DndProvider>
  );
};

export default App;
```

