const express = require('express');
const http = require('http');
const socketIo = require('socket.io');

const app = express();
const server = http.createServer(app);
const io = socketIo(server);

// In-memory task storage
let tasks = {
  'todo': [{ id: 1, text: 'Task 1' }, { id: 2, text: 'Task 2' }],
  'inProgress': [],
  'done': []
};

// Serve static files
app.use(express.static('public'));

// Real-time task updates
io.on('connection', (socket) => {
  console.log('User connected:', socket.id);

  // Sync initial tasks to new client
  socket.emit('syncTasks', tasks);

  // Handle task movement
  socket.on('moveTask', (data) => {
    const { taskId, fromColumn, toColumn } = data;
    const task = tasks[fromColumn].find(t => t.id === taskId);

    if (task) {
      tasks[fromColumn] = tasks[fromColumn].filter(t => t.id !== taskId);
      tasks[toColumn].push(task);
      io.emit('updateTasks', tasks);
    }
  });

  socket.on('disconnect', () => {
    console.log('User disconnected:', socket.id);
  });
});

// Start server
const PORT = 3000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
