```javascript
const socket = io();

const columns = {
  todo: document.getElementById('todo'),
  inProgress: document.getElementById('inProgress'),
  done: document.getElementById('done')
};

let currentTasks = {};

// Initialize tasks from backend
socket.on('syncTasks', (tasks) => {
  currentTasks = tasks;
  renderTasks();
});

// Listen for updates from other users
socket.on('updateTasks', (tasks) => {
  currentTasks = tasks;
  renderTasks();
});

// Drag-and-drop setup
document.querySelectorAll('.column').forEach(column => {
  column.addEventListener('dragover', (e) => {
    e.preventDefault();
  });

  column.addEventListener('drop', (e) => {
    e.preventDefault();
    const taskId = e.dataTransfer.getData('text/plain');
    const fromColumn = e.dataTransfer.getData('fromColumn');
    const toColumn = column.id;

    if (fromColumn && toColumn && fromColumn !== toColumn) {
      socket.emit('moveTask', { taskId, fromColumn, toColumn });
    }
  });
});

// Render tasks
function renderTasks() {
  Object.keys(currentTasks).forEach(column => {
    const container = columns[column];
    container.innerHTML = `<h3>${column.charAt(0).toUpperCase() + column.slice(1)}</h3>`;
    currentTasks[column].forEach(task => {
      const taskEl = document.createElement('div');
      taskEl.className = 'task';
      taskEl.draggable = true;
      taskEl.textContent = task.text;
      taskEl.setAttribute('data-id', task.id);
      taskEl.addEventListener('dragstart', (e) => {
        e.dataTransfer.setData('text/plain', task.id);
        e.dataTransfer.setData('fromColumn', column);
      });
      container.appendChild(taskEl);
    });
  });
}
```

