import React, { useState, useEffect } from 'react';
import { DndProvider, useDrag, useDrop } from 'react-beautiful-dnd';
import { io } from 'socket.io-client';

const socket = io('http://localhost:3000');

type Task = {
  id: string;
  content: string;
};

type Board = {
  id: string;
  title: string;
  tasks: Task[];
};

const App: React.FC = () => {
  const [boards, setBoards] = useState<Board[]>([]);
  const [newTask, setNewTask] = useState<string>('');

  // Fetch initial data from backend
  useEffect(() => {
    fetch('/api/boards')
      .then((res) => res.json())
      .then((data) => setBoards(data));
  }, []);

  // Listen for real-time updates
  useEffect(() => {
    socket.on('updateBoard', (updatedBoard: Board) => {
      setBoards((prev) =>
        prev.map((board) => (board.id === updatedBoard.id ? updatedBoard : board))
      );
    });
  }, []);

  const onDragEnd = (result: any) => {
    const { source, destination } = result;

    if (!destination) return;

    const sourceBoard = boards.find((b) => b.id === source.droppableId);
    const destinationBoard = boards.find((b) => b.id === destination.droppableId);

    if (!sourceBoard || !destinationBoard) return;

    // Move task between boards
    const task = sourceBoard.tasks[source.index];
    const updatedSourceBoard = {
      ...sourceBoard,
      tasks: sourceBoard.tasks.filter((_, i) => i !== source.index),
    };
    const updatedDestinationBoard = {
      ...destinationBoard,
      tasks: [...destinationBoard.tasks, task],
    };

    setBoards([
      updatedSourceBoard,
      ...boards.filter((b) => b.id !== sourceBoard.id && b.id !== destinationBoard.id),
      updatedDestinationBoard,
    ]);

    // Emit update to backend
    socket.emit('updateBoard', updatedDestinationBoard);
  };

  const addTask = (boardId: string) => {
    if (newTask.trim()) {
      const updatedBoards = boards.map((board) => {
        if (board.id === boardId) {
          return {
            ...board,
            tasks: [
              ...board.tasks,
              { id: Date.now().toString(), content: newTask },
            ],
          };
        }
        return board;
      });
      setBoards(updatedBoards);
      socket.emit('updateBoard', updatedBoards.find((b) => b.id === boardId)!);
      setNewTask('');
    }
  };

  return (
    <DndProvider backend="HTML5Backend">
      <div style={{ display: 'flex', gap: '20px' }}>
        {boards.map((board) => (
          <div key={board.id} style={{ width: '300px', border: '1px solid #ccc', padding: '10px' }}>
            <h3>{board.title}</h3>
            <div>
              <input
                type="text"
                value={newTask}
                onChange={(e) => setNewTask(e.target.value)}
                placeholder="Add task"
              />
              <button onClick={() => addTask(board.id)}>Add</button>
            </div>
            <div style={{ minHeight: '200px' }}>
              {board.tasks.map((task, index) => (
                <div
                  key={task.id}
                  style={{ margin: '5px 0', padding: '10px', border: '1px solid #999' }}
                >
                  {task.content}
                </div>
              ))}
            </div>
          </div>
        ))}
      </div>
    </DndProvider>
  );
};

export default App;
```

