// frontend/src/App.tsx
import React, { useState, useEffect } from "react";
import { DragDropContext, Droppable, Draggable } from "react-beautiful-dnd";
import { io } from "socket.io-client";

const socket = io("http://localhost:3000");

const App: React.FC = () => {
  const [tasks, setTasks] = useState({
    todo: ["Task 1", "Task 2"],
    "in-progress": ["Task 3"],
    done: [],
  });

  useEffect(() => {
    // Sync tasks on initial load
    socket.on("syncTasks", (updatedTasks) => {
      setTasks(updatedTasks);
    });

    return () => {
      socket.off("syncTasks");
    };
  }, []);

  const onDragEnd = (result: any) => {
    const { source, destination } = result;

    if (!destination) return;

    const sourceColumn = tasks[source.droppableId];
    const destinationColumn = tasks[destination.droppableId];

    const [movedTask] = sourceColumn.splice(source.index, 1);
    destinationColumn.splice(destination.index, 0, movedTask);

    const updatedTasks = { ...tasks, [source.droppableId]: sourceColumn, [destination.droppableId]: destinationColumn };

    setTasks(updatedTasks);
    socket.emit("updateTask", updatedTasks);
  };

  return (
    <DragDropContext onDragEnd={onDragEnd}>
      <div style={{ display: "flex", gap: "20px", padding: "20px" }}>
        {Object.entries(tasks).map(([columnId, columnTasks]) => (
          <Droppable key={columnId} droppableId={columnId}>
            {(provided) => (
              <div
                ref={provided.innerRef}
                {...provided.droppableProps}
                style={{
                  width: "300px",
                  minHeight: "300px",
                  border: "1px solid #ccc",
                  padding: "10px",
                  borderRadius: "8px",
                }}
              >
                <h3>{columnId}</h3>
                {columnTasks.map((task, index) => (
                  <Draggable key={task} draggableId={task} index={index}>
                    {(provided) => (
                      <div
                        ref={provided.innerRef}
                        {...provided.draggableProps}
                        {...provided.dragHandleProps}
                        style={{
                          padding: "8px",
                          margin: "5px 0",
                          backgroundColor: "#f0f0f0",
                          borderRadius: "4px",
                        }}
                      >
                        {task}
                      </div>
                    )}
                  </Draggable>
                ))}
                {provided.placeholder}
              </div>
            )}
          </Droppable>
        ))}
      </div>
    </DragDropContext>
  );
};

export default App;
```

