```javascript
// server.js
const express = require("express");
const http = require("http");
const socketIO = require("socket.io");
const mongoose = require("mongoose");

const app = express();
const server = http.createServer(app);
const io = socketIO(server);

// MongoDB Connection
mongoose.connect("mongodb://localhost:27017/taskboard", {
  useNewUrlParser: true,
  useUnifiedTopology: true,
});

// Schema
const boardSchema = new mongoose.Schema({
  id: String,
  title: String,
  tasks: [
    {
      id: String,
      title: String,
    },
  ],
});

const Board = mongoose.model("Board", boardSchema);

// Initial Board State
const initialBoards = [
  {
    id: "1",
    title: "To Do",
    tasks: [
      { id: "1", title: "Task 1" },
      { id: "2", title: "Task 2" },
    ],
  },
  {
    id: "2",
    title: "In Progress",
    tasks: [],
  },
  {
    id: "3",
    title: "Done",
    tasks: [],
  },
];

// Load initial data
Board.insertMany(initialBoards).catch((err) => {
  console.error("Error initializing boards:", err);
});

// Real-Time Updates
io.on("connection", (socket) => {
  console.log("A user connected");

  // Emit current board state
  Board.find()
    .then((boards) => {
      socket.emit("updateBoard", boards);
    })
    .catch((err) => {
      console.error("Error fetching boards:", err);
    });

  // Handle board updates
  socket.on("updateBoard", (updatedBoards) => {
    Board.deleteMany().then(() => {
      Board.insertMany(updatedBoards).then(() => {
        io.emit("updateBoard", updatedBoards);
      });
    });
  });

  socket.on("disconnect", () => {
    console.log("A user disconnected");
  });
});

// Start server
const PORT = 3001;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
