```jsx
import React, { useState, useEffect } from 'react';
import { DndProvider, useDrag, useDrop } from 'react-beautiful-dnd';
import { getDatabase, ref, set, onValue } from 'firebase/database';

// Initialize Firebase
const firebaseConfig = {
  apiKey: "YOUR_FIREBASE_API_KEY",
  authDomain: "YOUR_PROJECT_ID.firebaseapp.com",
  databaseURL: "https://YOUR_PROJECT_ID.firebaseio.com",
  projectId: "YOUR_PROJECT_ID",
  storageBucket: "YOUR_PROJECT_ID.appspot.com",
  messagingSenderId: "YOUR_SENDER_ID",
  appId: "YOUR_APP_ID"
};

const database = getDatabase();

// Firebase Ref
const taskBoardRef = ref(database, 'tasks');

// Task Component
const Task = ({ task, index, onMoveTask }) => {
  const [{ isDragging }, drag] = useDrag({
    type: 'task',
    item: { id: task.id, index },
    collect: (monitor) => ({
      isDragging: monitor.isDragging(),
    }),
  });

  return (
    <div
      ref={drag}
      className="task"
      style={{ opacity: isDragging ? 0.5 : 1 }}
    >
      {task.title}
    </div>
  );
};

// Column Component
const Column = ({ column, tasks, onMoveTask }) => {
  const [{ isOver }, drop] = useDrop({
    accept: 'task',
    drop: (item) => onMoveTask(item.id, column.id, item.index),
    collect: (monitor) => ({
      isOver: monitor.isOver(),
    }),
  });

  return (
    <div ref={drop} className="column" style={{ backgroundColor: isOver ? '#f0f0f0' : '#fff' }}>
      <h3>{column.title}</h3>
      {tasks.map((task, index) => (
        <Task key={task.id} task={task} index={index} onMoveTask={onMoveTask} />
      ))}
    </div>
  );
};

// Main App Component
function App() {
  const [tasks, setTasks] = useState([]);
  const [columns, setColumns] = useState([]);

  // Initialize Firebase data
  useEffect(() => {
    onValue(taskBoardRef, (snapshot) => {
      const data = snapshot.val();
      if (data) {
        setTasks(data.tasks || []);
        setColumns(data.columns || []);
      }
    });
  }, []);

  // Handle task movement
  const handleMoveTask = (taskId, targetColumnId, sourceIndex) => {
    const updatedTasks = [...tasks];
    const sourceTask = updatedTasks.splice(sourceIndex, 1)[0];
    const targetColumn = columns.find(col => col.id === targetColumnId);
    const targetIndex = targetColumn.tasks.findIndex(task => task.id === taskId);

    if (targetIndex === -1) {
      targetColumn.tasks.push(sourceTask);
    } else {
      targetColumn.tasks[targetIndex] = sourceTask;
    }

    setTasks(updatedTasks);
    setColumns(columns);

    // Update Firebase
    set(ref(database, 'tasks'), { tasks: updatedTasks, columns: columns });
  };

  return (
    <DndProvider backend="HTML5Backend">
      <div className="board">
        {columns.map((column) => (
          <Column
            key={column.id}
            column={column}
            tasks={column.tasks}
            onMoveTask={handleMoveTask}
          />
        ))}
      </div>
    </DndProvider>
  );
}

export default App;
```

