// script.js
const socket = io();
const taskBoards = document.getElementById("task-boards");

// Initialize task lists
function initializeTaskLists(tasks) {
  Object.keys(tasks).forEach((column) => {
    const list = document.getElementById(`${column}-list`);
    list.innerHTML = "";
    tasks[column].forEach((task) => {
      const li = document.createElement("li");
      li.draggable = true;
      li.textContent = task;
      list.appendChild(li);
    });
  });
}

// Handle drag-and-drop
function setupDragAndDrop() {
  const taskItems = document.querySelectorAll(".task-list li");

  taskItems.forEach((task) => {
    task.addEventListener("dragstart", (e) => {
      e.dataTransfer.setData("text/plain", e.target.textContent);
    });
  });

  const columns = document.querySelectorAll(".column");
  columns.forEach((column) => {
    column.addEventListener("dragover", (e) => {
      e.preventDefault();
    });

    column.addEventListener("drop", (e) => {
      e.preventDefault();
      const taskId = e.dataTransfer.getData("text/plain");
      const fromColumn = Array.from(document.querySelectorAll(".column"))
        .find((col) => col.querySelector(`li[data-task="${taskId}"]`))?.id;
      const toColumn = column.id;

      if (fromColumn && fromColumn !== toColumn) {
        socket.emit("moveTask", { taskId, fromColumn, toColumn });
      }
    });
  });
}

// Sync with server
socket.on("sync", (tasks) => {
  initializeTaskLists(tasks);
  setupDragAndDrop();
});

socket.on("updateTasks", (tasks) => {
  initializeTaskLists(tasks);
  setupDragAndDrop();
});
