public:
    MarketDataFeed() : running_(true) {
        // Simulate market data feed (could be replaced with real data source)
        std::thread([this]() {
            while (running_) {
                // Simulate market data (price, volume, etc.)
                auto data = generateMarketData();
                processMarketData(std::move(data));
                std::this_thread::sleep_for(std::chrono::milliseconds(10));
            }
        }).detach();
    }

    ~MarketDataFeed() {
        running_ = false;
    }

    void processMarketData(Order data) {
        std::lock_guard<std::mutex> lock(mtx_);
        market_data_queue_.push(std::move(data));
    }

    std::vector<Order> getMarketData() {
        std::vector<Order> result;
        {
            std::lock_guard<std::mutex> lock(mtx_);
            while (!market_data_queue_.empty()) {
                result.push_back(market_data_queue_.front());
                market_data_queue_.pop();
            }
        }
        return result;
    }

private:
    std::vector<Order> generateMarketData() {
        // Simulated market data
        static int counter = 0;
        return {{"AAPL", 150.50 + counter * 0.01, 100, "BUY"}};
    }

    std::mutex mtx_;
    std::queue<Order> market_data_queue_;
    std::atomic<bool> running_;
};

// Order Book
class OrderBook {
public:
    void addOrder(Order order) {
        std::lock_guard<std::mutex> lock(mtx_);
        if (order.type == "BUY") {
            buy_orders_.push_back(order);
        } else if (order.type == "SELL") {
            sell_orders_.push_back(order);
        }
    }

    std::vector<Order> getBestBids() const {
