    ExecutionEngine() {
        std::thread([this]() {
            while (true) {
                auto orders = order_book_.getBestBids();
                for (const auto& order : orders) {
                    executeOrder(order);
                }
                std::this_thread::sleep_for(std::chrono::milliseconds(50));
            }
        }).detach();
    }

    void executeOrder(Order order) {
        std::cout << "Executing order: " << order.symbol << " @ " << order.price << " (" << order.quantity << ")\n";
        // Simulate execution (e.g., send to exchange)
    }

    void addOrderToBook(Order order) {
        order_book_.addOrder(std::move(order));
    }

private:
    OrderBook order_book_;
};

// Main Trading Platform
class TradingPlatform {
public:
    TradingPlatform() : market_data_feed_(std::make_unique<MarketDataFeed>()),
                        execution_engine_(std::make_unique<ExecutionEngine>()) {}

    void start() {
        std::thread([this]() {
            while (true) {
                auto data = market_data_feed_->getMarketData();
                for (const auto& order : data) {
                    execution_engine_->addOrderToBook(order);
                }
                std::this_thread::sleep_for(std::chrono::milliseconds(20));
            }
