            if (!orderQueue_.empty()) {
                auto order = orderQueue_.front();
                orderQueue_.pop();
                executionEngine_.executeOrder(order);
            } else {
                std::this_thread::sleep_for(std::chrono::microseconds(100));
            }
        }
    }

