        : io_(io), acceptor_(io, boost::asio::ip::tcp::endpoint(boost::asio::ip::tcp::v4(), 8080)), engine_(engine) {
        do_accept();
    }

private:
    void do_accept() {
        acceptor_.async_accept(
            [this](boost::system::error_code ec, boost::asio::ip::tcp::socket socket) {
                if (!ec) {
                    std::thread([socket = std::move(socket), this]() {
                        handle_request(socket);
                    }).detach();
                }
                do_accept();
            });
    }

    void handle_request(boost::asio::ip::tcp::socket& socket) {
        boost::asio::streambuf buffer;
        boost::asio::read_until(socket, buffer, "\r\n");
        std::string request(boost::asio::buffer_cast<const char*>(buffer.data()));
        std::istringstream iss(request);
        std::string method, path;
        iss >> method >> path;

        if (method == "POST" && path == "/order") {
            std::string body;
            boost::asio::read_until(socket, buffer, "\r\n\r\n");
            boost::asio::getline(buffer, body, '\r');
            Order order = parseOrder(body);
            engine_.processOrder(order);
            boost::asio::write(socket, boost::asio::buffer("HTTP/1.1 200 OK\r\nContent-Length: 12\r\n\r\nOrder added"));
        } else {
            boost::asio::write(socket, boost::asio::buffer("HTTP/1.1 404 Not Found\r\n\r\n"));
        }
    }

    Order parseOrder(const std::string& data) {
        Order order;
        // Simplified parsing (in real systems, use JSON or binary)
        std::istringstream iss(data);
        iss >> order.id >> order.symbol >> order.price >> order.quantity >> order.side >> order.type;
        return order;
    }

