        std::lock_guard<std::mutex> lock(mtx);
        if (is_buy) {
            bids[price] += quantity;
            if (price > best_bid) best_bid = price;
        } else {
            asks[price] += quantity;
            if (price < best_ask) best_ask = price;
        }
    }

