class OrderBookEngine {
public:
    OrderBookEngine() : next_order_id(1) {}

    void add_order(const std::string& symbol, double price, int quantity, bool is_buy) {
        std::lock_guard<std::mutex> lock(book_mutex);
        orders.push_back({next_order_id++, symbol, price, quantity, is_buy});
        match_orders();
    }

    void match_orders() {
        std::lock_guard<std::mutex> lock(book_mutex);
        std::sort(orders.begin(), orders.end(), [](const Order& a, const Order& b) {
            return a.price != b.price ? a.price < b.price : a.is_buy && !b.is_buy;
        });

        for (size_t i = 0; i < orders.size(); ++i) {
            for (size_t j = i + 1; j < orders.size(); ++j) {
                if (orders[i].is_buy && orders[j].is_buy) continue;
                if (!orders[i].is_buy && !orders[j].is_buy) continue;

                if (orders[i].price == orders[j].price && orders[i].quantity > 0 && orders[j].quantity > 0) {
                    std::cout << "Matched: Order " << orders[i].id << " and " << orders[j].id << std::endl;
                    orders[i].quantity = 0;
                    orders[j].quantity = 0;
                    break;
                }
            }
        }
    }

    void print_order_book() {
        std::lock_guard<std::mutex> lock(book_mutex);
        for (const auto& order : orders) {
            std::cout << "Order ID: " << order.id << ", Symbol: " << order.symbol
                      << ", Price: " << order.price << ", Quantity: " << order.quantity
                      << ", Buy: " << (order.is_buy ? "Yes" : "No") << std::endl;
        }
    }

private:
    OrderBook orders;
    int next_order_id;
    std::mutex book_mutex;
};

