// Trade represents a trade between a buy and sell order
type Trade struct {
	Price   float64
	Quantity int
	Buyer   string
	Seller  string
}

// Order represents a limit order
type Order struct {
	ID        string
	Side      string // "buy" or "sell"
	Price     float64
	Quantity  int
	Remaining int
}

// OrderBook holds buy and sell orders
type OrderBook struct {
	Buys  map[float64]int
	Sells map[float64]int
	mu    sync.Mutex
}

// NewOrderBook initializes a new order book
func NewOrderBook() *OrderBook {
	return &OrderBook{
		Buys:  make(map[float64]int),
		Sells: make(map[float64]int),
	}
}

// AddOrder adds a new order to the order book and matches it
func (ob *OrderBook) AddOrder(order Order) []Trade {
	ob.mu.Lock()
	defer ob.mu.Unlock()

	var trades []Trade

	if order.Side == "buy" {
		// Match with best sell price
		for price, qty := range ob.Sells {
			if price <= order.Price && qty > 0 {
				matchQty := min(order.Quantity, qty)
				trades = append(trades, Trade{
					Price:    price,
					Quantity: matchQty,
					Buyer:    order.ID,
					Seller:   fmt.Sprintf("sell_%v", price),
				})
				ob.Sells[price] -= matchQty
				order.Quantity -= matchQty
				if ob.Sells[price] == 0 {
					delete(ob.Sells, price)
				}
				if order.Quantity == 0 {
					break
				}
			}
		}
		if order.Quantity > 0 {
			ob.Buys[order.Price] += order.Quantity
		}
	} else if order.Side == "sell" {
		// Match with best buy price
		for price, qty := range ob.Buys {
			if price >= order.Price && qty > 0 {
				matchQty := min(order.Quantity, qty)
				trades = append(trades, Trade{
					Price:    price,
					Quantity: matchQty,
					Buyer:    fmt.Sprintf("buy_%v", price),
					Seller:   order.ID,
				})
				ob.Buys[price] -= matchQty
				order.Quantity -= matchQty
				if ob.Buys[price] == 0 {
					delete(ob.Buys, price)
				}
				if order.Quantity == 0 {
					break
				}
			}
		}
		if order.Quantity > 0 {
			ob.Sells[order.Price] += order.Quantity
		}
	}
	return trades
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

// HTTP handler to place orders
func placeOrderHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != "POST" {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	type OrderRequest struct {
		ID     string  `json:"id"`
		Side   string  `json:"side"`
		Price  float64 `json:"price"`
		Quantity int     `json:"quantity"`
	}

	var orderReq OrderRequest
	if err := json.NewDecoder(r.Body).Decode(&orderReq); err != nil {
		http.Error(w, "Invalid request body", http.StatusBadRequest)
		return
	}

	// Simulate a real-world scenario: process orders in a goroutine
	go func() {
		order := Order{
			ID:        orderReq.ID,
			Side:      orderReq.Side,
			Price:     orderReq.Price,
			Quantity:  orderReq.Quantity,
			Remaining: orderReq.Quantity,
		}

		trades := orderBook.AddOrder(order)
		fmt.Printf("Trades executed: %v\n", trades)
	}()

	w.WriteHeader(http.StatusOK)
	fmt.Fprintf(w, "Order received: %v\n", orderReq)
}

func main() {
	orderBook := NewOrderBook()

	http.HandleFunc("/order", placeOrderHandler)
	fmt.Println("Starting low-latency trading platform on :8080")
	http.ListenAndServe(":8080", nil)
}
