```cpp
#include <iostream>
#include <string>
#include <vector>
#include <thread>
#include <zmq.hpp>
#include <mutex>
#include <unordered_map>

// Order structure
struct Order {
    std::string symbol;
    double price;
    int quantity;
    std::string side; // "BUY" or "SELL"
};

// Order Book
class OrderBook {
public:
    void addOrder(const Order& order) {
        std::lock_guard<std::mutex> lock(mtx_);
        if (order.side == "BUY") {
            buyOrders_[order.symbol].push_back(order);
        } else {
            sellOrders_[order.symbol].push_back(order);
        }
        matchOrders(order.symbol);
    }

    void matchOrders(const std::string& symbol) {
        std::lock_guard<std::mutex> lock(mtx_);
        auto& buys = buyOrders_[symbol];
        auto& sells = sellOrders_[symbol];

        for (auto it_buy = buys.begin(); it_buy != buys.end(); ++it_buy) {
            for (auto it_sell = sells.begin(); it_sell != sells.end(); ++it_sell) {
                if (it_buy->price >= it_sell->price) {
                    std::cout << "Matched: " << it_buy->quantity << " @ " << it_sell->price << " for " << symbol << "\n";
                    buys.erase(it_buy);
                    sells.erase(it_sell);
                    break;
                }
            }
        }
    }

private:
    std::unordered_map<std::string, std::vector<Order>> buyOrders_;
    std::unordered_map<std::string, std::vector<Order>> sellOrders_;
    std::mutex mtx_;
};

// Market Data Feed (simulated)
void marketDataFeed(zmq::socket_t& publisher, const std::string& symbol) {
    while (true) {
        std::string price = "100.00"; // Simulated price
        std::string message = "MARKET_DATA|" + symbol + "|" + price;
        publisher.send(zmq::str_to_msg(message), zmq::send_flags::none);
        std::this_thread::sleep_for(std::chrono::milliseconds(100));
    }
}

// Matching Engine (receives orders from ZeroMQ)
void matchingEngine(zmq::socket_t& subscriber, OrderBook& orderBook) {
    while (true) {
        zmq::message_t message;
        subscriber.recv(message, zmq::recv_flags::none);
        std::string orderStr(static_cast<char*>(message.data()), message.size());
        std::istringstream iss(orderStr);
        std::string type, symbol, side;
        double price;
        int quantity;
        iss >> type >> symbol >> side >> price >> quantity;
        if (type == "ORDER") {
            Order order{symbol, price, quantity, side};
            orderBook.addOrder(order);
        }
    }
}

int main() {
    // ZeroMQ context
    zmq::context_t context(1);

    // Market Data Feed (Publisher)
    zmq::socket_t publisher(context, ZMQ_PUB);
    publisher.bind("tcp://*:5555");

    // Matching Engine (Subscriber)
    zmq::socket_t subscriber(context, ZMQ_SUB);
    subscriber.connect("tcp://localhost:5555");
    subscriber.setsockopt(ZMQ_SUBSCRIBE, "ORDER", 5);

    OrderBook orderBook;

    // Launch threads
    std::thread dataFeedThread(marketDataFeed, std::ref(publisher), "AAPL");
    std::thread engineThread(matchingEngine, std::ref(subscriber), std::ref(orderBook));

    // Simulate order submission (could be replaced with external input)
    zmq::socket_t client(context, ZMQ_REQ);
    client.connect("tcp://localhost:5555");

    std::string order = "ORDER|AAPL|BUY|100.50|100";
    client.send(zmq::str_to_msg(order), zmq::send_flags::none);
    client.recv(zmq::recv_flags::none);

    // Wait for threads to finish (for demonstration)
    dataFeedThread.join();
    engineThread.join();

    return 0;
}
```

