        cond_var.wait(lock, [this] { return !queue.empty(); });
        Message msg = queue.front();
        queue.pop();
        return msg;
    }

    bool empty() const {
        std::lock_guard<std::mutex> lock(queue_mutex);
        return queue.empty();
    }

private:
