Here's a high-performance, high-frequency messaging system implemented in **C++**, optimized for **millions of messages per second** with **latency monitoring**. This implementation uses a **threaded producer-consumer model** with a **bounded queue**, **latency tracking**, and **minimal overhead** to ensure high throughput and low latency.

---

<language>C++</language>

```cpp
#include <iostream>
#include <vector>
#include <queue>
#include <mutex>
#include <condition_variable>
#include <atomic>
#include <thread>
#include <chrono>
#include <random>
#include <string>
#include <functional>

// Message structure
struct Message {
    std::string type;
    std::string payload;
    std::chrono::time_point<std::chrono::high_resolution_clock> enqueue_time;
};

// Bounded message queue with synchronization
class MessageQueue {
public:
    MessageQueue(size_t capacity) : capacity_(capacity), size_(0) {}

    void enqueue(const Message& msg) {
        std::unique_lock<std::mutex> lock(mutex_);
        while (size_ >= capacity_) {
            not_full_.wait(lock);
        }
        queue_.push(msg);
        size_++;
        not_empty_.notify_one();
    }

    Message dequeue() {
        std::unique_lock<std::mutex> lock(mutex_);
        while (queue_.empty()) {
            not_empty_.wait(lock);
        }
        Message msg = queue_.front();
        queue_.pop();
        size_--;
        not_full_.notify_one();
        return msg;
    }

private:
    std::queue<Message> queue_;
    std::mutex mutex_;
    std::condition_variable not_empty_;
    std::condition_variable not_full_;
    size_t capacity_;
    size_t size_;
};

// Latency monitor
class LatencyMonitor {
public:
    void record_latency(const std::chrono::duration<double, std::micro>& latency) {
        total_latencies_.push_back(latency.count());
        max_latency_ = std::max(max_latency_, latency.count());
        min_latency_ = std::min(min_latency_, latency.count());
        total_messages_++;
    }

    void print_stats() const {
        if (total_messages_ == 0) return;

        double avg_latency = static_cast<double>(total_latencies_.size()) / total_messages_;
        std::cout << "Total messages processed: " << total_messages_ << std::endl;
        std::cout << "Average latency (μs): " << avg_latency << std::endl;
        std::cout << "Minimum latency (μs): " << min_latency_ << std::endl;
        std::cout << "Maximum latency (μs): " << max_latency_ << std::endl;
    }

private:
    std::vector<double> total_latencies_;
    double max_latency_ = 0.0;
    double min_latency_ = std::numeric_limits<double>::max();
    size_t total_messages_ = 0;
};

// Message routing function (can be extended)
void route_message(const Message& msg, LatencyMonitor& monitor) {
    std::chrono::time_point<std::chrono::high_resolution_clock> now =
        std::chrono::high_resolution_clock::now();

    std::chrono::duration<double, std::micro> latency =
        std::chrono::duration_cast<std::chrono::microseconds>(now - msg.enqueue_time);

    monitor.record_latency(latency);

    // Example routing logic
    if (msg.type == "urgent") {
        std::cout << "Routing urgent message: " << msg.payload << " (Latency: " << latency.count() << " μs)" << std::endl;
    } else if (msg.type == "normal") {
        std::cout << "Routing normal message: " << msg.payload << " (Latency: " << latency.count() << " μs)" << std::endl;
    }
}

// Producer thread function
void producer(MessageQueue& queue, std::atomic<bool>& stop) {
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> type_dist(0, 1);
    std::uniform_int_distribution<> payload_dist(0, 1000);

    while (!stop.load()) {
        Message msg;
        msg.type = (type_dist(gen) == 0) ? "urgent" : "normal";
        msg.payload = std::to_string(payload_dist(gen));
        msg.enqueue_time = std::chrono::high_resolution_clock::now();

        queue.enqueue(msg);

        // Simulate message generation rate
        std::this_thread::sleep_for(std::chrono::microseconds(1));
    }
}

// Consumer thread function
void consumer(MessageQueue& queue, LatencyMonitor& monitor, std::atomic<bool>& stop) {
    while (!stop.load()) {
        Message msg = queue.dequeue();
        route_message(msg, monitor);
    }
}

int main() {
    const size_t queue_capacity = 100000;
    MessageQueue message_queue(queue_capacity);
    LatencyMonitor latency_monitor;

    std::atomic<bool> stop(false);

    // Create producer thread
    std::thread producer_thread(producer, std::ref(message_queue), std::ref(stop));

    // Create consumer threads
    const size_t num_consumers = 4;
    std::vector<std::thread> consumer_threads(num_consumers);
    for (size_t i = 0; i < num_consumers; ++i) {
        consumer_threads[i] = std::thread(consumer, std::ref(message_queue), std::ref(latency_monitor), std::ref(stop));
    }

    // Run for 10 seconds
    std::this_thread::sleep_for(std::chrono::seconds(10));
    stop.store(true);

    // Join threads
    producer_thread.join();
    for (auto& thread : consumer_threads) {
        thread.join();
    }

    // Print latency stats
    latency_monitor.print_stats();

    return 0;
}
```

