```go
package main

import (
	"fmt"
	"math/rand"
	"runtime"
	"sync"
	"time"
)

// Message represents a message with a topic and payload
type Message struct {
	Topic     string
	Payload   string
	Timestamp time.Time
}

// Router is a map of topic to channel for message routing
type Router struct {
	topics map[string]chan Message
	mu     sync.RWMutex
}

// NewRouter creates a new router with a specified number of topic channels
func NewRouter(numTopics int) *Router {
	topics := make(map[string]chan Message)
	for i := 0; i < numTopics; i++ {
		topics[fmt.Sprintf("topic-%d", i)] = make(chan Message, 1000) // Buffered channel
	}
	return &Router{topics: topics}
}

// GetTopicChannel returns the channel for a given topic
func (r *Router) GetTopicChannel(topic string) chan Message {
	r.mu.RLock()
	defer r.mu.RUnlock()
	return r.topics[topic]
}

// LatencyMonitor tracks message latency
type LatencyMonitor struct {
	latencyChan chan time.Duration
	latencySum  time.Duration
	msgCount    int
	mu          sync.Mutex
}

// NewLatencyMonitor creates a new latency monitor
func NewLatencyMonitor() *LatencyMonitor {
	return &LatencyMonitor{
		latencyChan: make(chan time.Duration, 10000),
	}
}

// StartMonitor starts a goroutine to log latency statistics
func (lm *LatencyMonitor) StartMonitor() {
	go func() {
		ticker := time.NewTicker(1 * time.Second)
		defer ticker.Stop()

		for range ticker.C {
			lm.mu.Lock()
			avgLatency := time.Duration(0)
			if lm.msgCount > 0 {
				avgLatency = lm.latencySum / time.Duration(lm.msgCount)
			}
			fmt.Printf("Processed %d messages in last second. Avg latency: %v\n", lm.msgCount, avgLatency)
			lm.msgCount = 0
			lm.latencySum = 0
			lm.mu.Unlock()
		}
	}()
}

// ProcessMessage processes a message and logs latency
func (lm *LatencyMonitor) ProcessMessage(msg Message) {
	start := msg.Timestamp
	// Simulate message processing (e.g., database write, network send)
	time.Sleep(time.Duration(rand.Intn(10)) * time.Microsecond)
	latency := time.Since(start)
	lm.mu.Lock()
	lm.latencySum += latency
	lm.msgCount++
	lm.mu.Unlock()
	lm.latencyChan <- latency
}

func main() {
	runtime.GOMAXPROCS(runtime.NumCPU())

	// Initialize router and latency monitor
	router := NewRouter(10) // 10 topics
	monitor := NewLatencyMonitor()
	monitor.StartMonitor()

	// Start consumers for each topic
	var wg sync.WaitGroup
	for topic := range router.topics {
		wg.Add(1)
		go func(topic string) {
			defer wg.Done()
			for msg := range router.GetTopicChannel(topic) {
				monitor.ProcessMessage(msg)
			}
		}(topic)
	}

	// Producer: Send messages to random topics
	go func() {
		for i := 0; i < 10_000_000; i++ { // 10 million messages
			topic := fmt.Sprintf("topic-%d", rand.Intn(10))
			msg := Message{
				Topic:     topic,
				Payload:   fmt.Sprintf("msg-%d", i),
				Timestamp: time.Now(),
			}
			router.GetTopicChannel(topic) <- msg
		}
	}()

	// Wait for all consumers to finish
	wg.Wait()
	fmt.Println("All messages processed.")
}
```

