#include <iostream>
#include <queue>
#include <mutex>
#include <thread>
#include <chrono>
#include <vector>

// Message structure with a timestamp for latency monitoring
struct Message {
    std::chrono::steady_clock::time_point send_time;
};

// Shared queue and mutex for thread safety
std::queue<Message> message_queue;
std::mutex queue_mutex;

// Producer function: generates messages and adds them to the queue
void producer(int num_messages) {
    for (int i = 0; i < num_messages; ++i) {
        Message msg;
        msg.send_time = std::chrono::steady_clock::now();
        std::lock_guard<std::mutex> lock(queue_mutex);
        message_queue.push(msg);
    }
}

// Consumer function: processes messages and calculates latency
void consumer() {
    while (true) {
        std::lock_guard<std::mutex> lock(queue_mutex);
        if (message_queue.empty()) {
            break;
        }
        Message msg = message_queue.front();
        message_queue.pop();
        auto receive_time = std::chrono::steady_clock::now();
        auto latency = std::chrono::duration_cast<std::chrono::microseconds>(receive_time - msg.send_time).count();
        std::cout << "Latency: " << latency << " us" << std::endl;
    }
}

int main() {
    const int num_messages = 1000000; // 1 million messages

    std::thread producer_thread(producer, num_messages);
    std::thread consumer_thread(consumer);

    producer_thread.join();
    consumer_thread.join();

    return 0;
}
```

