Here's a **minimal working example** of a high-frequency messaging system in **C++** that routes millions of messages per second with **latency monitoring**. This example uses **UDP sockets** for low-latency communication and **std::chrono** for precise timing. It includes a **producer**, **router**, and **consumer** with basic latency tracking.

---

### ✅ **Key Features**
- **High-throughput routing** via UDP.
- **Latency tracking** for each message.
- **Threaded architecture** for concurrent operations.
- **Minimal footprint** (no external libraries).

---

### 📦 **Code: High-Frequency Messaging System in C++**

```cpp
#include <iostream>
#include <thread>
#include <chrono>
#include <cstring>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>

#define PRODUCER_PORT 8080
#define ROUTER_PORT 8081
#define CONSUMER_PORT 8082
#define MESSAGE_SIZE 1024

struct Message {
    uint64_t timestamp; // 8 bytes
    char payload[MESSAGE_SIZE - sizeof(uint64_t)];
};

// Producer: Sends messages with timestamps
void producer() {
    int sock = socket(AF_INET, SOCK_DGRAM, 0);
    struct sockaddr_in router_addr;
    memset(&router_addr, 0, sizeof(router_addr));
    router_addr.sin_family = AF_INET;
    router_addr.sin_port = htons(ROUTER_PORT);
    inet_pton(AF_INET, "127.0.0.1", &router_addr.sin_addr);

    for (int i = 0; i < 1000000; ++i) {
        Message msg;
        msg.timestamp = std::chrono::steady_clock::now().time_since_epoch().count();
        std::memset(msg.payload, 'a', sizeof(msg.payload));
        sendto(sock, &msg, sizeof(msg), 0, (struct sockaddr*)&router_addr, sizeof(router_addr));
    }
    close(sock);
}

// Router: Forwards messages from producer to consumer
void router() {
    int sock = socket(AF_INET, SOCK_DGRAM, 0);
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(ROUTER_PORT);
    inet_pton(AF_INET, "127.0.0.1", &addr.sin_addr);
    bind(sock, (struct sockaddr*)&addr, sizeof(addr));

    struct sockaddr_in consumer_addr;
    memset(&consumer_addr, 0, sizeof(consumer_addr));
    consumer_addr.sin_family = AF_INET;
    consumer_addr.sin_port = htons(CONSUMER_PORT);
    inet_pton(AF_INET, "127.0.0.1", &consumer_addr.sin_addr);

    while (true) {
        Message msg;
        socklen_t len = sizeof(addr);
        recvfrom(sock, &msg, sizeof(msg), 0, (struct sockaddr*)&addr, &len);
        sendto(sock, &msg, sizeof(msg), 0, (struct sockaddr*)&consumer_addr, sizeof(consumer_addr));
    }
    close(sock);
}

// Consumer: Receives messages and calculates latency
void consumer() {
    int sock = socket(AF_INET, SOCK_DGRAM, 0);
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(CONSUMER_PORT);
    inet_pton(AF_INET, "127.0.0.1", &addr.sin_addr);
    bind(sock, (struct sockaddr*)&addr, sizeof(addr));

    while (true) {
        Message msg;
        socklen_t len = sizeof(addr);
        recvfrom(sock, &msg, sizeof(msg), 0, (struct sockaddr*)&addr, &len);
        auto now = std::chrono::steady_clock::now().time_since_epoch().count();
        auto latency = now - msg.timestamp;
        std::cout << "Latency: " << latency << " ns" << std::endl;
    }
    close(sock);
}

int main() {
    std::thread t1(producer);
    std::thread t2(router);
    std::thread t3(consumer);

    t1.join();
    t2.join();
    t3.join();

    return 0;
}
```

---

### 📌 **Explanation of Key Components**
- **UDP Sockets**: Used for low-latency, high-throughput communication (no connection overhead).
- **std::chrono::steady_clock**: Ensures precise timestamping for latency tracking.
- **Threading**: Producer, router, and consumer run concurrently.
- **Message Structure**: Includes a timestamp and payload for routing and latency measurement.
- **Latency Calculation**: The consumer logs the difference between the message's sent time and received time.

---

### 📈 **Performance Considerations**
- **UDP Overhead**: Minimal compared to TCP, ideal for high-frequency systems.
- **Message Size**: Fixed-size messages (`MESSAGE_SIZE`) for predictable memory usage.
- **Scalability**: This is a **minimal prototype**. For production, you'd need:
  - **Multi-threaded producers/consumers**.
  - **Zero-copy techniques** (e.g., `sendfile`, `mmap`).
  - **Advanced routing logic** (e.g., topic-based filtering).
  - **Latency histograms** for statistical analysis.

---

### 🛠️ **Compilation**
Compile with:
```bash
g++ -std=c++11 -o high_freq_router high_freq_router.cpp -pthread
```

Run:
```bash
./high_freq_router
```

