#include <iostream>
#include <queue>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <chrono>
#include <vector>
#include <atomic>

struct Message {
    std::string payload;
    std::chrono::time_point<std::chrono::high_resolution_clock> send_time;
};

class ThreadSafeQueue {
public:
    void push(const Message& msg) {
        std::lock_guard<std::mutex> lock(mtx);
        queue.push(msg);
        cv.notify_one();
    }

    Message pop() {
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, [this]{ return !queue.empty(); });
        Message msg = queue.front();
        queue.pop();
        return msg;
    }

private:
    std::queue<Message> queue;
    std::mutex mtx;
    std::condition_variable cv;
};

void producer(ThreadSafeQueue& q, int num_messages) {
    for (int i = 0; i < num_messages; ++i) {
        Message msg;
        msg.payload = "test";
        msg.send_time = std::chrono::high_resolution_clock::now();
        q.push(msg);
    }
}

void consumer(ThreadSafeQueue& q, std::atomic<bool>& stop) {
    std::atomic<long long> total_latency(0);
    std::atomic<long long> count(0);
    auto start = std::chrono::high_resolution_clock::now();

    while (!stop.load()) {
        Message msg = q.pop();
        auto receive_time = std::chrono::high_resolution_clock::now();
        auto latency = std::chrono::duration_cast<std::chrono::microseconds>(receive_time - msg.send_time).count();
        total_latency += latency;
        count++;

        // Periodically print average latency
        auto now = std::chrono::high_resolution_clock::now();
        if (now - start >= std::chrono::seconds(1)) {
            double avg = static_cast<double>(total_latency) / count;
            std::cout << "Average latency: " << avg << " microseconds\n";
            total_latency = 0;
            count = 0;
            start = now;
        }
    }
}

int main() {
    ThreadSafeQueue q;
    std::atomic<bool> stop(false);

    std::thread producer_thread(producer, std::ref(q), 1000000); // 1 million messages
    std::thread consumer_thread(consumer, std::ref(q), std::ref(stop));

    // Let the threads run for a while
    std::this_thread::sleep_for(std::chrono::seconds(10));

    stop.store(true);
    producer_thread.join();
    consumer_thread.join();

    return 0;
}

