fn main() {
    // Step 1: Find a suitable network interface
    let interface = match find_interface() {
        Some(i) => i,
        None => {
            eprintln!("No suitable network interface found.");
            return;
        }
    };

    // Step 2: Open a datalink channel on the selected interface
    let mut channel = match datalink::channel(&interface, Config::default()) {
        Ok(Channel::Ethernet(mut channel)) => channel,
        Ok(_) => {
            eprintln!("Not an Ethernet interface.");
            return;
        }
        Err(e) => {
            eprintln!("Error getting datalink channel: {}", e);
            return;
        }
    };

    // Step 3: Create a UDP socket for packet forwarding
    let mut socket = match UdpSocket::bind("0.0.0.0:0") {
        Ok(s) => s,
        Err(e) => {
            eprintln!("Failed to bind UDP socket: {}", e);
            return;
        }
    };

    // Step 4: Main packet capture and filtering loop
    loop {
        match channel.next() {
            Ok(packet) => {
                if let Some(ethernet) = EthernetPacket::new(packet) {
                    if ethernet.get_ethertype() == EtherType(0x0800) { // IPv4
                        if let Some(ipv4) = Ipv4Packet::new(ethernet.payload()) {
                            let src_ip = ipv4.get_source();
                            let dst_ip = ipv4.get_destination();
                            let payload = ipv4.payload();

                            // Filter: forward packets from 192.168.1.1 to 192.168.1.2
                            if src_ip == [192, 168, 1, 1] {
                                let _ = socket.send_to(payload, "192.168.1.2:12345");
                            }
                        }
                    }
                }
            }
            Err(e) => {
                eprintln!("Error reading packet: {}", e);
            }
        }
    }
}

fn find_interface() -> Option<NetworkInterface> {
