#include <rte_ip.h>
#include <rte_tcp.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>

#define RX_QUEUE_SIZE 1024
#define TX_QUEUE_SIZE 1024
#define MAX_PKT_BURST 32
#define FILTER_SOURCE_IP 0xC0A80101  // 192.168.1.1

// Function to parse and filter packets
static inline int
filter_packet(struct rte_mbuf *mbuf) {
    struct rte_ether_hdr *eth_hdr = rte_pktmbuf_mtod(mbuf, struct rte_ether_hdr *);
    if (eth_hdr->ether_type != rte_be_to_cpu_16(RTE_ETHER_TYPE_IPV4))
        return 0;  // Not IPv4, skip

    struct rte_ipv4_hdr *ip_hdr = (struct rte_ipv4_hdr *)((char *)eth_hdr + sizeof(struct rte_ether_hdr));
    if (rte_be_to_cpu_32(ip_hdr->src_addr) == FILTER_SOURCE_IP) {
        return 1;  // Allow packet
    }
    return 0;  // Drop packet
}

// Main packet processing loop
static int
main_loop(uint16_t port_id, uint16_t tx_port_id) {
    struct rte_mbuf *pkts_burst[MAX_PKT_BURST];
    uint16_t nb_rx, nb_tx;

    while (!force_quit) {
        nb_rx = rte_eth_rx_burst(port_id, 0, pkts_burst, MAX_PKT_BURST);
        if (nb_rx == 0)
            continue;

        for (uint16_t i = 0; i < nb_rx; i++) {
            if (filter_packet(pkts_burst[i])) {
                // Forward packet to tx_port_id
                rte_eth_tx_burst(tx_port_id, 0, &pkts_burst[i], 1);
            } else {
                // Drop packet
                rte_pktmbuf_free(pkts_burst[i]);
            }
        }
    }
    return 0;
}

int
main(int argc, char **argv) {
    int ret;

    // Initialize DPDK environment
    ret = rte_eal_init(argc, argv);
    if (ret < 0)
        rte_exit(EXIT_FAILURE, "Error with EAL initialization\n");

    // Configure and start Ethernet ports
    uint16_t port_id = 0;
    uint16_t tx_port_id = 1;
    struct rte_eth_conf port_conf = {
        .rxmode = { .mq_mode = ETH_MQ_RX_RSS },
        .txmode = { .mq_mode = ETH_MQ_TX_NONE },
    };

    ret = rte_eth_dev_configure(port_id, 1, 1, &port_conf);
    if (ret < 0)
        rte_exit(EXIT_FAILURE, "Failed to configure RX/TX queues\n");

    ret = rte_eth_dev_start(port_id);
    if (ret < 0)
        rte_exit(EXIT_FAILURE, "Failed to start port %u\n", port_id);

    // Start the packet processing loop
    main_loop(port_id, tx_port_id);

    // Cleanup
    rte_eth_dev_stop(port_id);
    rte_eal_cleanup();

    return 0;
}
```

