#include <pcap.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <netinet/ether.h>
#include <netinet/ip.h>
#include <arpa/inet.h>

#define TARGET_SOURCE_IP "192.168.1.100"  // Packet source IP to forward

// Packet handler: filters and forwards packets
void packet_handler(u_char *user, const struct pcap_pkthdr *pkthdr, const u_char *packet) {
    struct ether_header *eth_hdr = (struct ether_header *)packet;
    if (ntohs(eth_hdr->ether_type) != ETHERTYPE_IP) return;

    struct iphdr *ip_hdr = (struct iphdr *)(packet + sizeof(struct ether_header));
    if (ip_hdr->version != 4) return;

    // Check source IP
    if (ntohl(ip_hdr->saddr) == inet_addr(TARGET_SOURCE_IP)) {
        // Forward the packet
        if (pcap_sendpacket((pcap_t *)user, packet, pkthdr->caplen) != 0) {
            fprintf(stderr, "Failed to forward packet: %s\n", pcap_geterr((pcap_t *)user));
        }
    }
}

int main() {
    char errbuf[PCAP_ERRBUF_SIZE];
    pcap_t *handle = pcap_open_live("eth0", 65536, 1, 1000, errbuf);
    if (!handle) {
        fprintf(stderr, "Error opening device: %s\n", errbuf);
        return 1;
    }

    // Set filter for IP packets to reduce processing overhead
    struct bpf_program fp;
    char filter_exp[] = "ip";
    if (pcap_compile(handle, &fp, filter_exp, 0, PCAP_NETMASK_UNKNOWN) == -1) {
        fprintf(stderr, "Error compiling filter: %s\n", pcap_geterr(handle));
        return 1;
    }
    if (pcap_setfilter(handle, &fp) == -1) {
        fprintf(stderr, "Error setting filter: %s\n", pcap_geterr(handle));
        return 1;
    }

    // Start packet loop
    pcap_loop(handle, 0, packet_handler, (u_char *)handle);

    pcap_close(handle);
    return 0;
}
```

