package main

import (
    "fmt"
    "net"
    "strings"
)

const (
    listenPort     = ":9090"
    forwardAddress = "127.0.0.1:9091"
    filterKeyword  = "FILTER"
)

func main() {
    // Create UDP listener
    addr, _ := net.ResolveUDPAddr("udp", listenPort)
    listener, _ := net.ListenUDP("udp", addr)
    defer listener.Close()

    fmt.Printf("Listening on %s\n", listenPort)

    buffer := make([]byte, 1500) // Max UDP packet size

    for {
        n, srcAddr, _ := listener.ReadFromUDP(buffer, nil)
        if n == 0 {
            continue
        }

        // Convert packet to string for filtering
        packet := string(buffer[:n])
        if strings.Contains(packet, filterKeyword) {
            fmt.Printf("Filtered packet from %s: %s\n", srcAddr, packet)

            // Forward packet
            forwardAddr, _ := net.ResolveUDPAddr("udp", forwardAddress)
            listener.WriteToUDP(buffer[:n], forwardAddr)
        }
    }
}
```

