```cpp
#include <rte_eal.h>
#include <rte_ethdev.h>
#include <rte_mbuf.h>
#include <rte_cycles.h>

#define RX_RING_SIZE 1024
#define TX_RING_SIZE 1024
#define NUM_PORTS 1
#define NUM_QUEUES 1

// Ethernet type for IPv4 (0x0800)
#define ETHER_TYPE_IPV4 0x0800

// Function to initialize a port
static int
port_init(uint8_t port, struct rte_mempool *mbuf_pool) {
    struct rte_eth_conf port_conf = {
        .rxmode = {
            .mq_mode = RTE_ETH_MQ_RX_RSS,
            .max_rx_pkt_len = RTE_ETH_MAX_JUMBO_FRAME_SIZE,
        },
        .txmode = {
            .mq_mode = RTE_ETH_MQ_TX_NONE,
        },
    };

    if (rte_eth_dev_configure(port, NUM_QUEUES, NUM_QUEUES, &port_conf) < 0)
        return -1;

    if (rte_eth_dev_rx_queue_setup(port, 0, RX_RING_SIZE, rte_eth_dev_socket_id(port),
                                   NULL, mbuf_pool) < 0)
        return -1;

    if (rte_eth_dev_tx_queue_setup(port, 0, TX_RING_SIZE, rte_eth_dev_socket_id(port),
                                   NULL) < 0)
        return -1;

    rte_eth_promiscuous_enable(port);
    return 0;
}

// Main function
int main(int argc, char **argv) {
    struct rte_mempool *mbuf_pool;
    uint16_t port_id;

    // Initialize the DPDK environment
    if (rte_eal_init(argc, argv) < 0)
        rte_exit(EXIT_FAILURE, "Error initializing DPDK\n");

    // Create a memory pool for mbufs
    mbuf_pool = rte_pktmbuf_pool_create("MBUF_POOL", 8192, 0, 0, RTE_MBUF_DEFAULT_BUF_SIZE, rte_socket_id());

    // Initialize the first port
    port_id = 0;
    if (port_init(port_id, mbuf_pool) < 0)
        rte_exit(EXIT_FAILURE, "Failed to initialize port %u\n", port_id);

    // Start the port
    if (rte_eth_dev_start(port_id) < 0)
        rte_exit(EXIT_FAILURE, "Failed to start port %u\n", port_id);

    // Main loop: receive and forward packets
    struct rte_mbuf *rx_pkts[RX_RING_SIZE];
    struct rte_mbuf *tx_pkts[TX_RING_SIZE];

    while (1) {
        uint16_t nb_rx = rte_eth_rx_burst(port_id, 0, rx_pkts, RX_RING_SIZE);
        if (nb_rx == 0)
            continue;

        for (uint16_t i = 0; i < nb_rx; i++) {
            struct rte_ether_hdr *eth_hdr = rte_pktmbuf_mtod(rx_pkts[i], struct rte_ether_hdr *);

            // Example: Filter for IPv4 packets
            if (ntohs(eth_hdr->ether_type) == ETHER_TYPE_IPV4) {
                // Forward the packet to the same port (or another port)
                uint16_t nb_tx = rte_eth_tx_burst(port_id, 0, &rx_pkts[i], 1);
                if (nb_tx != 1) {
                    rte_pktmbuf_free(rx_pkts[i]);
                }
            } else {
                // Drop non-IPv4 packets
                rte_pktmbuf_free(rx_pkts[i]);
            }
        }
    }

    return 0;
}
```

