#include <netpacket/packet.h>
#include <net/ethernet.h>

#define FILTER_SRC_IP "192.168.1.100" /* Example source IP to filter */
#define IFACE "eth0"                  /* Network interface to capture from */

void packet_handler(u_char *user, const struct pcap_pkthdr *pkthdr, const u_char *packet) {
    struct ip *ip_header = (struct ip*)(packet + 14); /* Skip Ethernet header */
    struct in_addr src_ip;
    src_ip.s_addr = ip_header->ip_src;

    if (strcmp(inet_ntoa(src_ip), FILTER_SRC_IP) == 0) {
        printf("Forwarding packet from %s\n", FILTER_SRC_IP);

        int sock = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_IP));
        if (sock < 0) {
            perror("socket");
            return;
        }

        if (sendto(sock, packet, pkthdr->len, 0, NULL, 0) < 0) {
            perror("sendto");
        }

        close(sock);
    }
}

int main() {
    pcap_t *handle;
    char errbuf[PCAP_ERRBUF_SIZE];
    struct bpf_program fp;
    char filter_exp[] = "ip src host 192.168.1.100"; /* BPF filter */
    bpf_u_int32 net;

    handle = pcap_open_live(IFACE, BUFSIZ, 1, 1000, errbuf);
    if (!handle) {
        fprintf(stderr, "Couldn't open device %s: %s\n", IFACE, errbuf);
        return 1;
