        syslog(LOG_INFO, "Memory: max RSS=%.2f KB\n", (double)usage.ru_maxrss);
    } else {
        syslog(LOG_ERR, "Failed to get resource usage.\n");
    }
}

// Monitor disk usage
void monitor_disk() {
    struct statvfs stat;
    if (statvfs("/", &stat) == 0) {
        double total = (double)(stat.f_blocks * stat.f_frsize);
        double free = (double)(stat.f_bfree * stat.f_frsize);
        syslog(LOG_INFO, "Disk: total=%.2f GB, free=%.2f GB\n", total / (1024 * 1024 * 1024), free / (1024 * 1024 * 1024));
    } else {
        syslog(LOG_ERR, "Failed to get disk usage.\n");
    }
}

