    pid_t pid = fork();
    if (pid < 0) {
        exit(EXIT_FAILURE);
    }
    if (pid > 0) {
        exit(EXIT_SUCCESS);
    }

    // Become session leader
    if (setsid() < 0) {
        exit(EXIT_FAILURE);
    }

    // Change working directory
    if (chdir("/") < 0) {
        exit(EXIT_FAILURE);
    }

    // Set umask
    umask(0);

    // Close file descriptors
    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);
}

int main() {
    // Open syslog
    openlog("sys_monitor", LOG_PID | LOG_CONS, LOG_DAEMON);

    // Daemonize
    daemonize();

    // Register signal handler
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        monitor_resources();
        monitor_disk();
        sleep(INTERVAL);
