### ✅ Features:
- **Daemonization** (forks into background, disassociates from terminal).
- **CPU usage monitoring** using `/proc/stat`.
- **Memory monitoring** using `sysinfo()`.
- **Graceful shutdown** via `SIGTERM`.

---

### 📦 Code: `system_daemon.c`

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/sysinfo.h>
#include <time.h>

// Function to daemonize the process
void daemonize() {
    pid_t pid = fork();
    if (pid < 0) {
        exit(EXIT_FAILURE);
    }
    if (pid > 0) {
        exit(EXIT_SUCCESS); // Parent exits
    }

    // Create a new session
    if (setsid() < 0) {
        exit(EXIT_FAILURE);
    }

    // Change working directory to root
    if (chdir("/") < 0) {
        exit(EXIT_FAILURE);
    }

    // Set file mode creation mask
    umask(0);

    // Close standard file descriptors
    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);
}

// Function to read CPU usage from /proc/stat
double get_cpu_usage() {
    FILE *fp = fopen("/proc/stat", "r");
    if (!fp) {
        return -1.0;
    }

    char line[1024];
    double user, nice, system, idle, total_prev, idle_prev, total_curr, idle_curr;
    if (fgets(line, sizeof(line), fp)) {
        sscanf(line, "cpu  %lf %lf %lf %lf", &user, &nice, &system, &idle);
        total_prev = user + nice + system + idle;
        idle_prev = idle;
    }

    // Wait for a short period to measure CPU usage
    usleep(100000); // 100ms

    if (fgets(line, sizeof(line), fp)) {
        sscanf(line, "cpu  %lf %lf %lf %lf", &user, &nice, &system, &idle);
        total_curr = user + nice + system + idle;
        idle_curr = idle;
    }

    fclose(fp);

    double cpu_usage = ((total_curr - total_prev) - (idle_curr - idle_prev)) / (total_curr - total_prev) * 100.0;
    return cpu_usage;
}

// Function to get memory usage
void get_memory_usage() {
    struct sysinfo mem_info;
    if (sysinfo(&mem_info) != 0) {
        return;
    }

    double total_memory = mem_info.totalram * mem_info.mem_unit / (1024.0 * 1024.0);
    double free_memory = mem_info.freeram * mem_info.mem_unit / (1024.0 * 1024.0);
    double used_memory = total_memory - free_memory;

    printf("Memory: %.2f MB used / %.2f MB total\n", used_memory, total_memory);
}

// Signal handler
void handle_signal(int sig) {
    if (sig == SIGTERM) {
        printf("Received SIGTERM, exiting...\n");
        exit(EXIT_SUCCESS);
    }
}

// Main daemon loop
void run_daemon() {
    signal(SIGTERM, handle_signal);

    while (1) {
        double cpu_usage = get_cpu_usage();
        if (cpu_usage >= 0.0) {
            printf("CPU: %.2f%%\n", cpu_usage);
        } else {
            printf("Failed to read CPU usage.\n");
        }

        get_memory_usage();

        sleep(1); // Monitor every second
    }
}

int main() {
    daemonize();
    run_daemon();
    return 0;
}
```

