        fclose(fp);
        return 0;
    }
    fclose(fp);

    double total = user + nice + system + idle + iowait + irq + softirq + steal;
    double idle_time = idle + iowait;
    double cpu_usage = (total - idle_time) / total * 100;
    return cpu_usage;
