#include <time.h>

#define MAX_FLOWS 1000000
#define FLOW_HASH_SIZE 1000003

// Flow key: src IP, dst IP, src port, dst port, protocol
typedef struct {
    struct in_addr src_ip;
    struct in_addr dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t protocol;
} flow_key_t;

// Flow statistics
typedef struct {
    uint64_t bytes;
    uint64_t packets;
    time_t first_seen;
    time_t last_seen;
} flow_stats_t;

// Hash table entry
