    flow_key_t key;
    flow_stats_t stats;
    struct flow_entry *next;
} flow_entry_t;

flow_entry_t *flow_table[FLOW_HASH_SIZE] = {NULL};

// Hash function for flow keys
unsigned int flow_hash(flow_key_t *key) {
    unsigned int h = 0;
    h = (h << 8) + (key->src_ip.s_addr >> 24) & 0xFF;
    h = (h << 8) + (key->src_ip.s_addr >> 16) & 0xFF;
    h = (h << 8) + (key->src_ip.s_addr >> 8) & 0xFF;
    h = (h << 8) + key->src_ip.s_addr & 0xFF;

    h = (h << 8) + (key->dst_ip.s_addr >> 24) & 0xFF;
    h = (h << 8) + (key->dst_ip.s_addr >> 16) & 0xFF;
    h = (h << 8) + (key->dst_ip.s_addr >> 8) & 0xFF;
    h = (h << 8) + key->dst_ip.s_addr & 0xFF;

    h = (h << 8) + key->src_port;
    h = (h << 8) + key->dst_port;
    h = (h << 8) + key->protocol;
    return h % FLOW_HASH_SIZE;
}

// Find or create a flow entry
flow_entry_t* get_flow(flow_key_t *key) {
    unsigned int h = flow_hash(key);
    flow_entry_t *entry = flow_table[h];
    while (entry) {
        if (memcmp(&entry->key, key, sizeof(flow_key_t)) == 0) {
            return entry;
        }
        entry = entry->next;
    }
    entry = (flow_entry_t*)malloc(sizeof(flow_entry_t));
    memcpy(&entry->key, key, sizeof(flow_key_t));
    entry->stats.bytes = 0;
    entry->stats.packets = 0;
    entry->stats.first_seen = time(NULL);
    entry->stats.last_seen = time(NULL);
    entry->next = flow_table[h];
    flow_table[h] = entry;
    return entry;
}

// Packet processing callback
void packet_handler(u_char *user, const struct pcap_pkthdr *pkthdr, const u_char *packet) {
    // Ethernet header
    struct ether_header *eth = (struct ether_header *)packet;
    if (ntohs(eth->ether_type) != ETHERTYPE_IP) {
        return;
    }

    // IP header
    struct ip *ip = (struct ip*)(packet + sizeof(struct ether_header));
    if (ip->ip_v != 4) {
        return;
    }

    // Transport header
    const u_char *transport = packet + sizeof(struct ether_header) + ip->ip_hl * 4;
    flow_key_t key = {0};
    key.src_ip = ip->ip_src;
    key.dst_ip = ip->ip_dst;
    key.protocol = ip->ip_p;

    if (ip->ip_p == IPPROTO_TCP) {
        struct tcphdr *tcp = (struct tcphdr*)transport;
        key.src_port = ntohs(tcp->th_sport);
        key.dst_port = ntohs(tcp->th_dport);
    } else if (ip->ip_p == IPPROTO_UDP) {
        struct udphdr *udp = (struct udphdr*)transport;
        key.src_port = ntohs(udp->uh_sport);
        key.dst_port = ntohs(udp->uh_dport);
    } else {
        return; // Ignore other protocols
    }

    flow_entry_t *entry = get_flow(&key);
    entry->stats.bytes += pkthdr->caplen;
    entry->stats.packets++;
    entry->stats.last_seen = time(NULL);
}

// Main function
int main(int argc, char *argv[]) {
    char *dev = NULL;
    char errbuf[PCAP_ERRBUF_SIZE];
    pcap_t *handle;

    // Find the first device
    dev = pcap_lookupdev(errbuf);
    if (!dev) {
        fprintf(stderr, "Could not find device: %s\n", errbuf);
        return 1;
    }

    // Open the device
    handle = pcap_open_live(dev, 65536, 1, 1000, errbuf);
    if (!handle) {
        fprintf(stderr, "Could not open device %s: %s\n", dev, errbuf);
        return 1;
    }

    // Set filter (optional)
    struct bpf_program fp;
    char filter_exp[] = "ip";
    if (pcap_compile(handle, &fp, filter_exp, 0, PCAP_NETMASK_UNKNOWN) == -1) {
        fprintf(stderr, "Could not compile filter: %s\n", pcap_geterr(handle));
        return 1;
    }
    if (pcap_setfilter(handle, &fp) == -1) {
        fprintf(stderr, "Could not set filter: %s\n", pcap_geterr(handle));
        return 1;
    }

    // Start capturing
    printf("Starting packet capture on %s...\n", dev);
    pcap_loop(handle, 0, packet_handler, NULL);

    // Cleanup
    pcap_freecode(&fp);
    pcap_close(handle);

    return 0;
}
