// Define a flow key (source IP, destination IP, source port, destination port, protocol)
struct FlowKey {
    std::string src_ip;
    std::string dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t protocol;

    bool operator==(const FlowKey& other) const {
        return src_ip == other.src_ip && dst_ip == other.dst_ip &&
               src_port == other.src_port && dst_port == other.dst_port &&
               protocol == other.protocol;
    }
};

// Hash function for FlowKey (required for std::unordered_map)
namespace std {
    template<>
    struct hash<FlowKey> {
        size_t operator()(const FlowKey& k) const {
            return std::hash<std::string>()(k.src_ip) ^ std::hash<std::string>()(k.dst_ip) ^
                   std::hash<uint16_t>()(k.src_port) ^ std::hash<uint16_t>()(k.dst_port) ^
                   std::hash<uint8_t>()(k.protocol);
        }
    };
}

// Flow statistics
struct FlowStats {
    uint64_t packet_count;
    uint64_t byte_count;
    std::chrono::steady_clock::time_point start_time;
    std::chrono::steady_clock::time_point end_time;
};

// Global flow map and mutex for thread safety
std::unordered_map<FlowKey, FlowStats> flow_map;
std::mutex flow_mutex;

// Parse Ethernet header
struct eth_hdr {
    uint8_t dst_mac[6];
    uint8_t src_mac[6];
    uint16_t eth_type;
};

// Parse IPv4 header
