    uint8_t ip_hl_v;
    uint8_t ip_tos;
    uint16_t ip_len;
    uint16_t ip_id;
    uint16_t ip_off;
    uint8_t ip_ttl;
    uint8_t ip_p;
    uint16_t ip_sum;
    struct in_addr ip_src, ip_dst;
};

// Parse TCP/UDP header
struct tcp_hdr {
    uint16_t th_sport;
    uint16_t th_dport;
    uint32_t th_seq;
    uint32_t th_ack;
    uint8_t th_off_x2;
    uint8_t th_flags;
    uint16_t th_win;
    uint16_t th_sum;
    uint16_t th_urp;
};

struct udp_hdr {
    uint16_t uh_sport;
    uint16_t uh_dport;
    uint16_t uh_len;
    uint16_t uh_sum;
};

// Callback function for packet capture
void packet_handler(u_char* user, const struct pcap_pkthdr* pkthdr, const u_char* packet) {
    // Parse Ethernet header
    eth_hdr* eth = (eth_hdr*)packet;
    if (ntohs(eth->eth_type) != ETH_P_IP) return; // Only IPv4 for now

    // Parse IPv4 header
    ip_hdr* ip = (ip_hdr*)(packet + sizeof(eth_hdr));
    if (ip->ip_hl_v & 0x0F) { // Check IP header length
        uint8_t ip_hl = (ip->ip_hl_v & 0x0F) * 4;
        if (ip_hl < sizeof(ip_hdr)) return;
    }

    // Parse TCP or UDP header
    uint8_t* transport = (uint8_t*)(packet + sizeof(eth_hdr) + (ip->ip_hl_v & 0x0F) * 4);
    if (ip->ip_p == IPPROTO_TCP) {
        tcp_hdr* tcp = (tcp_hdr*)transport;
        FlowKey key;
        key.src_ip = inet_ntoa(ip->ip_src);
        key.dst_ip = inet_ntoa(ip->ip_dst);
        key.src_port = ntohs(tcp->th_sport);
        key.dst_port = ntohs(tcp->th_dport);
        key.protocol = IPPROTO_TCP;

        // Update flow stats
        std::lock_guard<std::mutex> lock(flow_mutex);
        auto it = flow_map.find(key);
        if (it == flow_map.end()) {
            flow_map[key] = {1, pkthdr->caplen, std::chrono::steady_clock::now(), std::chrono::steady_clock::now()};
        } else {
            it->second.packet_count++;
            it->second.byte_count += pkthdr->caplen;
            it->second.end_time = std::chrono::steady_clock::now();
        }
    } else if (ip->ip_p == IPPROTO_UDP) {
        udp_hdr* udp = (udp_hdr*)transport;
        FlowKey key;
        key.src_ip = inet_ntoa(ip->ip_src);
        key.dst_ip = inet_ntoa(ip->ip_dst);
        key.src_port = ntohs(udp->uh_sport);
        key.dst_port = ntohs(udp->uh_dport);
        key.protocol = IPPROTO_UDP;

        // Update flow stats
        std::lock_guard<std::mutex> lock(flow_mutex);
        auto it = flow_map.find(key);
        if (it == flow_map.end()) {
            flow_map[key] = {1, pkthdr->caplen, std::chrono::steady_clock::now(), std::chrono::steady_clock::now()};
        } else {
            it->second.packet_count++;
            it->second.byte_count += pkthdr->caplen;
            it->second.end_time = std::chrono::steady_clock::now();
        }
    }
}

// Main function
int main(int argc, char* argv[]) {
    if (argc < 2) {
        std::cerr << "Usage: " << argv[0] << " <interface>" << std::endl;
        return 1;
    }

    char* dev = argv[1];
    char errbuf[PCAP_ERRBUF_SIZE];
    pcap_t* handle = pcap_open_live(dev, BUFSIZ, 1, 1000, errbuf);
    if (!handle) {
