        std::cerr << "Couldn't parse filter " << filter_exp << ": " << pcap_geterr(handle) << std::endl;
        return 3;
    }
    if (pcap_setfilter(handle, &fp) == -1) {
        std::cerr << "Couldn't install filter " << filter_exp << ": " << pcap_geterr(handle) << std::endl;
        return 4;
    }

    // Start packet capture in a separate thread
    std::thread capture_thread([&]() {
        pcap_loop(handle, 0, packet_handler, nullptr);
    });

    // Simulate periodic flow reporting (e.g., every 5 seconds)
    while (true) {
        std::this_thread::sleep_for(std::chrono::seconds(5));
        std::lock_guard<std::mutex> lock(flow_mutex);
        for (const auto& [key, stats] : flow_map) {
            std::cout << "Flow: " << key.src_ip << ":" << key.src_port << " -> "
                      << key.dst_ip << ":" << key.dst_port << " (Proto: " << key.protocol << ")\n"
                      << "  Packets: " << stats.packet_count << ", Bytes: " << stats.byte_count << "\n"
                      << "  Duration: " << std::chrono::duration_cast<std::chrono::seconds>(stats.end_time - stats.start_time).count()
                      << "s\n";
        }
    }

    capture_thread.join();
    pcap_close(handle);
    return 0;
}
