```c
#include <pcap.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <netinet/ip.h>
#include <netinet/tcp.h>
#include <netinet/udp.h>
#include <arpa/inet.h>

#define MAX_FLOWS 100000
#define HASH_SIZE 10000

typedef struct {
    char src_ip[16];
    char dst_ip[16];
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t protocol;
    uint64_t bytes;
    uint64_t packets;
    struct timeval start_time;
    struct timeval end_time;
} Flow;

typedef struct {
    Flow *flow;
    struct FlowHashEntry *next;
} FlowHashEntry;

FlowHashEntry *flow_table[HASH_SIZE];

void init_flow_table() {
    for (int i = 0; i < HASH_SIZE; i++) {
        flow_table[i] = NULL;
    }
}

unsigned int hash_flow(const Flow *flow) {
    unsigned int hash = 0;
    hash ^= (unsigned int)flow->src_port;
    hash ^= (unsigned int)flow->dst_port;
    hash ^= (unsigned int)flow->protocol;
    hash ^= (unsigned int)(flow->src_ip[0] << 24);
    hash ^= (unsigned int)(flow->src_ip[1] << 16);
    hash ^= (unsigned int)(flow->src_ip[2] << 8);
    hash ^= (unsigned int)(flow->src_ip[3]);
    hash ^= (unsigned int)(flow->dst_ip[0] << 24);
    hash ^= (unsigned int)(flow->dst_ip[1] << 16);
    hash ^= (unsigned int)(flow->dst_ip[2] << 8);
    hash ^= (unsigned int)(flow->dst_ip[3]);
    return hash % HASH_SIZE;
}

void add_flow(Flow *flow) {
    unsigned int h = hash_flow(flow);
    FlowHashEntry *entry = (FlowHashEntry *)malloc(sizeof(FlowHashEntry));
    entry->flow = flow;
    entry->next = flow_table[h];
    flow_table[h] = entry;
}

Flow *find_flow(const Flow *flow) {
    unsigned int h = hash_flow(flow);
    FlowHashEntry *entry = flow_table[h];
    while (entry) {
        if (strcmp(entry->flow->src_ip, flow->src_ip) == 0 &&
            strcmp(entry->flow->dst_ip, flow->dst_ip) == 0 &&
            entry->flow->src_port == flow->src_port &&
            entry->flow->dst_port == flow->dst_port &&
            entry->flow->protocol == flow->protocol) {
            return entry->flow;
        }
        entry = entry->next;
    }
    return NULL;
}

void update_flow(Flow *flow, int bytes) {
    Flow *existing = find_flow(flow);
    if (existing) {
        existing->bytes += bytes;
        existing->packets++;
        gettimeofday(&existing->end_time, NULL);
    } else {
        add_flow(flow);
    }
}

void print_flows() {
    for (int i = 0; i < HASH_SIZE; i++) {
        FlowHashEntry *entry = flow_table[i];
        while (entry) {
            Flow *flow = entry->flow;
            printf("Flow: %s:%d -> %s:%d (Proto: %d)\n",
                   flow->src_ip, ntohs(flow->src_port),
                   flow->dst_ip, ntohs(flow->dst_port),
                   flow->protocol);
            printf("  Bytes: %lu | Packets: %lu\n",
                   flow->bytes, flow->packets);
            entry = entry->next;
        }
    }
}

void packet_handler(u_char *user, const struct pcap_pkthdr *pkthdr, const u_char *packet) {
    static int packet_count = 0;
    if (packet_count++ % 10000 == 0) {
        printf("Processing packet %d (%lu bytes)\n", packet_count, pkthdr->caplen);
    }

    // Ethernet header
    struct ether_header *eth_hdr = (struct ether_header *)packet;
    if (ntohs(eth_hdr->ether_type) != ETHERTYPE_IP) return;

    // IP header
    struct ip *ip_hdr = (struct ip *)(packet + sizeof(struct ether_header));
    if (ip_hdr->ip_v != 4) return; // IPv4 only

    // TCP/UDP header
    uint16_t ip_len = ip_hdr->ip_hl * 4;
    uint16_t transport_hdr_offset = 0;
    if (ip_hdr->ip_p == IPPROTO_TCP) {
        struct tcphdr *tcp_hdr = (struct tcphdr *)(packet + ip_len);
        transport_hdr_offset = tcp_hdr->th_off * 4;
    } else if (ip_hdr->ip_p == IPPROTO_UDP) {
        struct udphdr *udp_hdr = (struct udphdr *)(packet + ip_len);
        transport_hdr_offset = sizeof(struct udphdr);
    } else {
        return; // Ignore other protocols
    }

    // Extract 5-tuple
    Flow *flow = (Flow *)malloc(sizeof(Flow));
    inet_ntop(AF_INET, &(ip_hdr->ip_src), flow->src_ip, sizeof(flow->src_ip));
    inet_ntop(AF_INET, &(ip_hdr->ip_dst), flow->dst_ip, sizeof(flow->dst_ip));
    flow->src_port = 0;
    flow->dst_port = 0;
    flow->protocol = ip_hdr->ip_p;

    if (flow->protocol == IPPROTO_TCP || flow->protocol == IPPROTO_UDP) {
        if (flow->protocol == IPPROTO_TCP) {
            struct tcphdr *tcp_hdr = (struct tcphdr *)(packet + ip_len);
            flow->src_port = tcp_hdr->th_sport;
            flow->dst_port = tcp_hdr->th_dport;
        } else {
            struct udphdr *udp_hdr = (struct udphdr *)(packet + ip_len);
            flow->src_port = udp_hdr->uh_sport;
            flow->dst_port = udp_hdr->uh_dport;
        }
    }

    gettimeofday(&flow->start_time, NULL);
    flow->end_time = flow->start_time;
    flow->bytes = pkthdr->caplen;
    flow->packets = 1;

    update_flow(flow);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <interface>\n", argv[0]);
        return 1;
    }

    char *device = argv[1];
    char errbuf[PCAP_ERRBUF_SIZE];
    pcap_t *handle = pcap_open_live(device, BUFSIZ, 1, 1000, errbuf);
    if (!handle) {
        fprintf(stderr, "Couldn't open device %s: %s\n", device, errbuf);
        return 1;
    }

    init_flow_table();
    pcap_loop(handle, 0, packet_handler, NULL);

    print_flows();

    return 0;
}
