#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <pfring.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <time.h>

#define MAX_FLOWS 1000000
#define HASH_SIZE 1024

// Flow 5-tuple structure
typedef struct {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t protocol;
} flow_key_t;

// Flow statistics
typedef struct {
    time_t start_time;
    time_t end_time;
    uint64_t packets;
    uint64_t bytes;
} flow_data_t;

// Hash table entry
typedef struct {
    flow_key_t key;
    flow_data_t data;
    struct hash_entry *next;
} hash_entry_t;

// Global hash table
hash_entry_t *hash_table[HASH_SIZE];

// Hash function for flow keys
unsigned int flow_hash(flow_key_t *key) {
    return (key->src_ip ^ key->dst_ip ^ key->src_port ^ key->dst_port ^ key->protocol) % HASH_SIZE;
}

// Find or create a hash entry for a flow
hash_entry_t* get_flow_entry(flow_key_t *key) {
    unsigned int index = flow_hash(key);
    hash_entry_t *entry = hash_table[index];

    while (entry) {
        if (memcmp(&entry->key, key, sizeof(flow_key_t)) == 0) {
            return entry;
        }
        entry = entry->next;
    }

    // Create new entry
    entry = (hash_entry_t *)malloc(sizeof(hash_entry_t));
    memcpy(&entry->key, key, sizeof(flow_key_t));
    entry->data.start_time = time(NULL);
