Here's a **minimal working example** of a performance-critical network flow analyzer in **C**, using **libpcap** for packet capture and a basic hash table for flow tracking. This example is optimized for simplicity and performance, suitable for monitoring gigabit-scale traffic.

---

### <language>C</language>
```c
#include <pcap.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <netinet/ip.h>
#include <netinet/tcp.h>
#include <arpa/inet.h>

#define HASH_TABLE_SIZE 1024

// Flow struct to track network flows
typedef struct {
    char src_ip[16];
    char dst_ip[16];
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t protocol;
    uint64_t packet_count;
    struct Flow *next;
} Flow;

Flow *flows[HASH_TABLE_SIZE];

// Simple hash function
unsigned int hash(const char *src_ip, const char *dst_ip, uint16_t src_port, uint16_t dst_port, uint8_t protocol) {
    unsigned int h = 0;
    h = (h * 31 + (unsigned int)src_ip[0]) % HASH_TABLE_SIZE;
    h = (h * 31 + (unsigned int)src_ip[1]) % HASH_TABLE_SIZE;
    h = (h * 31 + (unsigned int)src_ip[2]) % HASH_TABLE_SIZE;
    h = (h * 31 + (unsigned int)src_ip[3]) % HASH_TABLE_SIZE;
    h = (h * 31 + (unsigned int)dst_ip[0]) % HASH_TABLE_SIZE;
    h = (h * 31 + (unsigned int)dst_ip[1]) % HASH_TABLE_SIZE;
    h = (h * 31 + (unsigned int)dst_ip[2]) % HASH_TABLE_SIZE;
    h = (h * 31 + (unsigned int)dst_ip[3]) % HASH_TABLE_SIZE;
    h = (h * 31 + (unsigned int)src_port) % HASH_TABLE_SIZE;
    h = (h * 31 + (unsigned int)dst_port) % HASH_TABLE_SIZE;
    h = (h * 31 + (unsigned int)protocol) % HASH_TABLE_SIZE;
    return h;
}

// Packet handler for libpcap
void packet_handler(u_char *user, const struct pcap_pkthdr *pkthdr, const u_char *packet) {
    const struct ether_header *eth = (struct ether_header *)packet;
    const struct ip *ip = (struct ip *)(packet + sizeof(struct ether_header));
    const struct tcphdr *tcp = (struct tcphdr *)(packet + sizeof(struct ether_header) + (ip->ip_hl << 2));

    // Skip non-IPv4 or non-TCP packets
    if (ip->ip_v != 4 || ip->ip_p != IPPROTO_TCP) return;

    char src_ip[16], dst_ip[16];
    inet_ntop(AF_INET, &ip->ip_src, src_ip, sizeof(src_ip));
    inet_ntop(AF_INET, &ip->ip_dst, dst_ip, sizeof(dst_ip));

    unsigned int h = hash(src_ip, dst_ip, ntohs(tcp->th_sport), ntohs(tcp->th_dport), IPPROTO_TCP);

    // Update flow count
    Flow *f;
    for (f = flows[h]; f; f = f->next) {
        if (strcmp(f->src_ip, src_ip) == 0 && strcmp(f->dst_ip, dst_ip) == 0 &&
            f->src_port == ntohs(tcp->th_sport) && f->dst_port == ntohs(tcp->th_dport) &&
            f->protocol == IPPROTO_TCP) {
            f->packet_count++;
            return;
        }
    }

    // Create new flow
    f = (Flow *)malloc(sizeof(Flow));
    strcpy(f->src_ip, src_ip);
    strcpy(f->dst_ip, dst_ip);
    f->src_port = ntohs(tcp->th_sport);
    f->dst_port = ntohs(tcp->th_dport);
    f->protocol = IPPROTO_TCP;
    f->packet_count = 1;
    f->next = flows[h];
    flows[h] = f;
}

// Main function
int main(int argc, char **argv) {
    char errbuf[PCAP_ERRBUF_SIZE];
    pcap_t *handle;

    // Open live device
    handle = pcap_open_live("eth0", BUFSIZ, 1, 1000, errbuf);
    if (!handle) {
        fprintf(stderr, "pcap_open_live: %s\n", errbuf);
        return 1;
    }

    // Start packet capture
    pcap_loop(handle, 0, packet_handler, NULL);

    // Print flows
    for (int i = 0; i < HASH_TABLE_SIZE; i++) {
        Flow *f;
        for (f = flows[i]; f; f = f->next) {
            printf("Flow: %s:%d -> %s:%d (TCP) | Packets: %lu\n",
                   f->src_ip, f->src_port, f->dst_ip, f->dst_port, f->packet_count);
        }
    }

    // Cleanup
    for (int i = 0; i < HASH_TABLE_SIZE; i++) {
        Flow *f, *next;
        for (f = flows[i]; f; f = next) {
            next = f->next;
            free(f);
        }
    }

    pcap_close(handle);
    return 0;
}
```

