### 🧪 Minimal Working Code

```cpp
#include <rte_eal.h>
#include <rte_ethdev.h>
#include <rte_mbuf.h>
#include <unordered_map>
#include <iostream>
#include <thread>
#include <chrono>

// Define a flow key (IPv4, TCP/UDP)
struct FlowKey {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t protocol;

    bool operator==(const FlowKey& other) const {
        return src_ip == other.src_ip && dst_ip == other.dst_ip &&
               src_port == other.src_port && dst_port == other.dst_port &&
               protocol == other.protocol;
    }
};

// Hash function for FlowKey
namespace std {
    template<>
    struct hash<FlowKey> {
        size_t operator()(const FlowKey& key) const {
            return std::hash<uint32_t>()(key.src_ip) ^ std::hash<uint32_t>()(key.dst_ip) ^
                   std::hash<uint16_t>()(key.src_port) ^ std::hash<uint16_t>()(key.dst_port) ^
                   std::hash<uint8_t>()(key.protocol);
        }
    };
}

// Flow statistics
struct FlowStats {
    uint64_t bytes = 0;
    uint64_t packets = 0;
};

// Global flow map
std::unordered_map<FlowKey, FlowStats> flow_map;

// Packet processing function
void packet_processing(uint16_t port_id) {
    const uint16_t nb_rx = rte_eth_rx_burst(port_id, 0, 128);
    for (uint16_t i = 0; i < nb_rx; ++i) {
        rte_mbuf* mbuf = rte_eth_rx_burst(port_id, 0, &mbuf, 1);
        if (!mbuf) continue;

        // Parse Ethernet header
        rte_ether_hdr* eth_hdr = rte_pktmbuf_mtod(mbuf, rte_ether_hdr*);
        if (eth_hdr->ether_type != rte_be_to_cpu_16(RTE_ETHER_TYPE_IPv4)) {
            rte_pktmbuf_free(mbuf);
            continue;
        }

        // Parse IPv4 header
        rte_ipv4_hdr* ip_hdr = reinterpret_cast<rte_ipv4_hdr*>(eth_hdr + 1);
        if (ip_hdr->next_proto_id != IPPROTO_TCP && ip_hdr->next_proto_id != IPPROTO_UDP) {
            rte_pktmbuf_free(mbuf);
            continue;
        }

        // Parse TCP/UDP header
        rte_udp_hdr* udp_hdr = reinterpret_cast<rte_udp_hdr*>(ip_hdr + 1);
        rte_tcp_hdr* tcp_hdr = reinterpret_cast<rte_tcp_hdr*>(ip_hdr + 1);

        FlowKey key;
        key.src_ip = ip_hdr->src_addr;
        key.dst_ip = ip_hdr->dst_addr;
        key.protocol = ip_hdr->next_proto_id;

        if (key.protocol == IPPROTO_UDP) {
            key.src_port = udp_hdr->src_port;
            key.dst_port = udp_hdr->dst_port;
        } else if (key.protocol == IPPROTO_TCP) {
            key.src_port = tcp_hdr->src_port;
            key.dst_port = tcp_hdr->dst_port;
        }

        // Update flow statistics
        FlowStats& stats = flow_map[key];
        stats.bytes += mbuf->pkt_len;
        stats.packets += 1;

        rte_pktmbuf_free(mbuf);
    }
}

int main(int argc, char** argv) {
    // Initialize DPDK
    int ret = rte_eal_init(argc, argv);
    if (ret < 0) {
        std::cerr << "Error with EAL initialization\n";
        return -1;
    }

    // Configure Ethernet port
    uint16_t port_id = 0;
    if (rte_eth_dev_count() == 0) {
        std::cerr << "No Ethernet ports found\n";
        return -1;
    }

    // Start packet processing loop
    std::thread processing_thread(packet_processing, port_id);
    processing_thread.detach();

    // Print flow statistics periodically
    while (true) {
        std::this_thread::sleep_for(std::chrono::seconds(1));
        std::cout << "Current flows:\n";
        for (const auto& [key, stats] : flow_map) {
            std::cout << "Flow: " << key.src_ip << ":" << key.src_port << " -> "
                      << key.dst_ip << ":" << key.dst_port << " (Proto: " << key.protocol << ")\n"
                      << "  Bytes: " << stats.bytes << " | Packets: " << stats.packets << "\n";
        }
    }

    return 0;
}
```

