        ip->ip_dst.s_addr,       // dst IP
        ntohs(tcp->th_sport),    // src port
        ntohs(tcp->th_dport),    // dst port
        IPPROTO_TCP              // protocol
    );

    // Update flow stats
    flowMap[key].bytes += pkthdr->len;
    flowMap[key].packets += 1;

    // Optional: Print flows periodically (not shown for performance)
}

