        std::size_t h4 = std::hash<uint16_t>()(key.dst_port);
        std::size_t h5 = std::hash<uint8_t>()(key.protocol);
        return h1 ^ (h2 << 1) ^ (h3 << 2) ^ (h4 << 3) ^ (h5 << 4);
    }
};

