    if (ip_version != 4) return; // Only IPv4 for simplicity

    uint8_t ip_header_length = (ip_header[0] & 0x0F) * 4;
    uint8_t ip_protocol = ip_header[9];
    uint32_t src_ip = *(uint32_t*)(ip_header + 12);
    uint32_t dst_ip = *(uint32_t*)(ip_header + 16);

    // Parse TCP/UDP header
    uint16_t ip_header_offset = ip_header_length;
    const uint8_t* transport_header = packet + 14 + ip_header_offset;

    uint16_t src_port = *(uint16_t*)(transport_header);
    uint16_t dst_port = *(uint16_t*)(transport_header + 2);

    // Create flow key
    FlowKey key;
    key.src_ip = std::to_string(src_ip);
    key.dst_ip = std::to_string(dst_ip);
    key.src_port = ntohs(src_port);
    key.dst_port = ntohs(dst_port);
    key.protocol = ip_protocol;

    // Update flow statistics
    auto now = std::time(nullptr);
    auto it = flows.find(key);
    if (it != flows.end()) {
        it->second.bytes += pkthdr->len;
        it->second.packets++;
        it->second.last_seen = now;
    } else {
        FlowStats stats;
        stats.bytes = pkthdr->len;
        stats.packets = 1;
        stats.first_seen = now;
        stats.last_seen = now;
        flows.insert({key, stats});
    }
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        std::cerr << "Usage: " << argv[0] << " <interface>" << std::endl;
        return 1;
    }

    char* dev = argv[1];
    char errbuf[PCAP_ERRBUF_SIZE];
    pcap_t* handle = pcap_open_live(dev, BUFSIZ, 1, 1000, errbuf);
    if (!handle) {
        std::cerr << "Error opening device " << dev << ": " << errbuf << std::endl;
        return 1;
    }

    std::cout << "Starting packet capture on " << dev << "... Press Ctrl+C to stop." << std::endl;

    // Capture packets
    pcap_loop(handle, 0, packetHandler, nullptr);

    // Print flow statistics
    std::cout << "\nFlow statistics:\n";
    for (const auto& [key, stats] : flows) {
        std::cout << "Flow: " << key.src_ip << ":" << key.src_port << " -> "
                  << key.dst_ip << ":" << key.dst_port << " (Proto: " << (int)key.protocol << ")\n"
                  << "  Bytes: " << stats.bytes << ", Packets: " << stats.packets << "\n"
                  << "  First seen: " << std::ctime(&stats.first_seen)
                  << "  Last seen: " << std::ctime(&stats.last_seen) << std::endl;
    }

    pcap_close(handle);
    return 0;
}
