### 🧑‍💻 Code: `flow_analyzer.c`
```c
#include <pcap.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <time.h>

// Flow structure
typedef struct {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t proto; // IPPROTO_TCP, IPPROTO_UDP
    uint64_t bytes;
    uint64_t packets;
    struct timespec start_time;
} Flow;

// Hash table for flows (simplified for minimal example)
#define FLOW_TABLE_SIZE 1024
Flow *flow_table[FLOW_TABLE_SIZE];

// Hash function (basic XOR-based)
unsigned int flow_hash(uint32_t src_ip, uint16_t src_port, uint32_t dst_ip, uint16_t dst_port, uint8_t proto) {
    return (src_ip ^ dst_ip ^ src_port ^ dst_port ^ proto) % FLOW_TABLE_SIZE;
}

// Initialize flow table
void init_flow_table() {
    for (int i = 0; i < FLOW_TABLE_SIZE; i++) {
        flow_table[i] = NULL;
    }
}

// Find or create a flow in the table
Flow *get_flow(uint32_t src_ip, uint16_t src_port, uint32_t dst_ip, uint16_t dst_port, uint8_t proto) {
    unsigned int hash = flow_hash(src_ip, src_port, dst_ip, dst_port, proto);
    Flow *flow = flow_table[hash];
    if (flow) {
        // Match: check if all fields match (simplified)
        if (flow->src_ip == src_ip && flow->dst_ip == dst_ip &&
            flow->src_port == src_port && flow->dst_port == dst_port &&
            flow->proto == proto) {
            return flow;
        }
    }
    // No match: create a new flow
    flow = (Flow *)malloc(sizeof(Flow));
    flow->src_ip = src_ip;
    flow->dst_ip = dst_ip;
    flow->src_port = src_port;
    flow->dst_port = dst_port;
    flow->proto = proto;
    flow->bytes = 0;
    flow->packets = 0;
    clock_gettime(CLOCK_MONOTONIC, &flow->start_time);
    flow_table[hash] = flow;
    return flow;
}

// Callback for packet processing
void packet_handler(u_char *user, const struct pcap_pkthdr *pkthdr, const u_char *packet) {
    // Skip Ethernet header (14 bytes)
    const u_char *ip_header = packet + 14;
    struct ip *ip = (struct ip *)ip_header;
    uint32_t src_ip = ip->ip_src.s_addr;
    uint32_t dst_ip = ip->ip_dst.s_addr;
    uint8_t proto = ip->ip_p;

    // Skip IP header (20 bytes for IPv4)
    const u_char *transport_header = ip_header + 20;
    if (proto == IPPROTO_TCP || proto == IPPROTO_UDP) {
        struct tcphdr *tcp = (struct tcphdr *)transport_header;
        uint16_t src_port = ntohs(tcp->th_sport);
        uint16_t dst_port = ntohs(tcp->th_dport);

        Flow *flow = get_flow(src_ip, src_port, dst_ip, dst_port, proto);
        flow->bytes += pkthdr->caplen;
        flow->packets += 1;
    }
}

// Main function
int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <interface>\n", argv[0]);
        return 1;
    }

    char *device = argv[1];
    char errbuf[PCAP_ERRBUF_SIZE];
    pcap_t *handle = pcap_open_live(device, BUFSIZ, 1, 1000, errbuf);
    if (!handle) {
        fprintf(stderr, "Could not open device %s: %s\n", device, errbuf);
        return 1;
    }

    init_flow_table();
    pcap_loop(handle, 0, packet_handler, NULL);

    // Clean up (not shown for brevity)
    return 0;
}
```

