### <language>C</language>
```c
#include "stm32f4xx_hal.h"
#include "stdio.h"

// I2C and UART handles
I2C_HandleTypeDef hi2c1;
UART_HandleTypeDef huart2;

// BME280 I2C address
#define BME280_ADDR 0x76

// Sensor data structure
typedef struct {
    uint16_t pressure;
    uint16_t temperature;
    uint16_t humidity;
} SensorData;

// I2C write function
void I2C_Write(uint8_t reg, uint8_t data) {
    uint8_t txData[2] = {reg, data};
    HAL_I2C_Master_Transmit(&hi2c1, BME280_ADDR << 1, txData, sizeof(txData), HAL_MAX_DELAY);
}

// I2C read function
void I2C_Read(uint8_t reg, uint8_t *data, uint16_t size) {
    HAL_I2C_Master_Transmit(&hi2c1, BME280_ADDR << 1, &reg, 1, HAL_MAX_DELAY);
    HAL_I2C_Master_Receive(&hi2c1, BME280_ADDR << 1, data, size, HAL_MAX_DELAY);
}

