#include <iostream>
#include <chrono>
#include <thread>
#include <vector>
#include <cmath>

// Forward declarations
class SensorFusion;
class MotorController;
class ControlLoop;

// --- Sensor Fusion (Kalman Filter for IMU data) ---
class SensorFusion {
public:
    struct SensorData {
        double gyro_x;     // Angular velocity (rad/s)
        double acc_x;      // Acceleration (m/s²)
        double acc_y;
        double acc_z;
        double position_x; // Estimated position (m)
        double position_y;
    };

    SensorFusion() : dt(0.01), last_time(0.0) {}

    SensorData update(const SensorData& raw_data) {
        // Simplified Kalman filter: fuse IMU data to estimate position
        double filtered_acc_x = raw_data.acc_x * 0.8 + raw_data.acc_y * 0.2;
        double filtered_acc_y = raw_data.acc_y * 0.8 + raw_data.acc_x * 0.2;

        // Integrate acceleration to estimate velocity and position
        double delta_time = dt;
        position_x += velocity_x * delta_time + 0.5 * filtered_acc_x * delta_time * delta_time;
        velocity_x += filtered_acc_x * delta_time;

        position_y += velocity_y * delta_time + 0.5 * filtered_acc_y * delta_time * delta_time;
        velocity_y += filtered_acc_y * delta_time;

        SensorData fused_data;
        fused_data.gyro_x = raw_data.gyro_x;
        fused_data.acc_x = filtered_acc_x;
        fused_data.acc_y = filtered_acc_y;
        fused_data.position_x = position_x;
        fused_data.position_y = position_y;
        return fused_data;
    }

private:
    double dt;               // Time step (s)
    double position_x = 0.0, position_y = 0.0;
    double velocity_x = 0.0, velocity_y = 0.0;
    std::chrono::steady_clock::time_point last_time;
};

// --- Motor Controller (PID) ---
class MotorController {
public:
    MotorController(double kp, double ki, double kd)
        : kp(kp), ki(ki), kd(kd), last_error(0.0), integral(0.0) {}

    double computeControlSignal(double target, double current) {
        double error = target - current;
        integral += error * dt;
        double derivative = (error - last_error) / dt;

        double output = kp * error + ki * integral + kd * derivative;
        last_error = error;
        return std::clamp(output, -1.0, 1.0); // Clamp to motor limits
    }

private:
    double kp, ki, kd;
    double dt = 0.01; // Match time step from SensorFusion
    double last_error = 0.0;
    double integral = 0.0;
};

// --- Control Loop (Real-time execution) ---
class ControlLoop {
public:
    ControlLoop(SensorFusion& fusion, MotorController& left_motor, MotorController& right_motor)
        : fusion(fusion), left_motor(left_motor), right_motor(right_motor) {}

    void run() {
        SensorFusion::SensorData raw_data;
        raw_data.gyro_x = 0.1;  // Simulated gyro data
        raw_data.acc_x = 1.0;   // Simulated acceleration
        raw_data.acc_y = 0.5;
        raw_data.position_x = 0.0;
        raw_data.position_y = 0.0;

        const double target_position_x = 1.0; // Desired position
        const double target_position_y = 0.0;

        while (true) {
            // Simulate sensor data
            raw_data.position_x += 0.01; // Simulated drift
            raw_data.position_y += 0.01;

            // Sensor fusion
            SensorFusion::SensorData fused_data = fusion.update(raw_data);

            // PID control for left and right motors
            double left_signal = left_motor.computeControlSignal(target_position_x, fused_data.position_x);
            double right_signal = right_motor.computeControlSignal(target_position_y, fused_data.position_y);

            // Simulate motor output
            std::cout << "Left Motor: " << left_signal << ", Right Motor: " << right_signal << std::endl;

            // Simulate real-time execution (100 Hz)
            std::this_thread::sleep_for(std::chrono::milliseconds(10));
        }
    }

private:
    SensorFusion& fusion;
    MotorController& left_motor;
    MotorController& right_motor;
};

// --- Main Function ---
