    SensorFusion fusion;
    MotorController left_motor(1.0, 0.1, 0.05);
    MotorController right_motor(1.0, 0.1, 0.05);

    // Start control loop
    ControlLoop control_loop(fusion, left_motor, right_motor);
    control_loop.run();

    return 0;
}
