        double error = setpoint - measured;
        integral += error * dt;
        double derivative = (error - last_error) / dt;
        double output = Kp * error + Ki * integral + Kd * derivative;
        last_error = error;
        return std::clamp(output, -1.0, 1.0); // Clamp output to [-1, 1]
    }

