// Kalman filter for sensor fusion (simplified 1D example)
class KalmanFilter {
private:
    double Q; // Process noise covariance
    double R; // Measurement noise covariance
    double x; // Estimated state
    double P; // Estimated error covariance
    double K; // Kalman gain

public:
    KalmanFilter(double Q, double R) : Q(Q), R(R), x(0), P(1), K(0) {}

    double update(double measurement) {
        K = P / (P + R);
        x = x + K * (measurement - x);
        P = (1 - K) * P + Q;
        return x;
    }
};

// PID controller for motor control
class PIDController {
private:
    double Kp, Ki, Kd;
    double integral, previous_error;
    double setpoint;

public:
    PIDController(double Kp, double Ki, double Kd) : Kp(Kp), Ki(Ki), Kd(Kd), integral(0), previous_error(0), setpoint(0) {}

    void setSetpoint(double setpoint) {
        this->setpoint = setpoint;
    }

    double compute(double current_value, double dt) {
        double error = setpoint - current_value;
        integral += error * dt;
        double derivative = (error - previous_error) / dt;

        double output = Kp * error + Ki * integral + Kd * derivative;
        previous_error = error;

        return output;
    }
};

