    uint16_t index;
    float mean_x;
    float mean_y;
    float mean_z;
    float std_dev_x;
    float std_dev_y;
    float std_dev_z;
} SensorWindow;

// Initialize the sliding window
void init_window(SensorWindow *window) {
    memset(window, 0, sizeof(SensorWindow));
    window->index = 0;
}

// Add a new data point to the sliding window
void add_data_point(SensorWindow *window, AccelerometerData *data) {
