#define SAMPLE_WINDOW 10      // Number of samples for anomaly detection
#define THRESHOLD 2.0         // Threshold for anomaly detection (g)

// Simulated accelerometer data (replace with actual sensor readings)
float get_accelerometer_data() {
    static float data = 0.0;
    data += (rand() % 10 - 5) * 0.1; // Simulate noise
    return data;
}

// Circular buffer for storing recent samples
typedef struct {
    float buffer[SAMPLE_WINDOW];
    uint8_t index;
} SampleBuffer;

// Initialize buffer
void buffer_init(SampleBuffer *buf) {
    buf->index = 0;
    for (int i = 0; i < SAMPLE_WINDOW; i++) {
        buf->buffer[i] = 0.0;
    }
}

// Add a new sample to the buffer
void buffer_add(SampleBuffer *buf, float value) {
    buf->buffer[buf->index] = value;
    buf->index = (buf->index + 1) % SAMPLE_WINDOW;
}

// Compute standard deviation of the buffer
float buffer_std_dev(SampleBuffer *buf) {
    float mean = 0.0, sum_sq_diff = 0.0;
    for (int i = 0; i < SAMPLE_WINDOW; i++) {
        mean += buf->buffer[i];
    }
    mean /= SAMPLE_WINDOW;

    for (int i = 0; i < SAMPLE_WINDOW; i++) {
        sum_sq_diff += (buf->buffer[i] - mean) * (buf->buffer[i] - mean);
    }
    return sqrt(sum_sq_diff / SAMPLE_WINDOW);
}

// Main pipeline loop
void process_pipeline() {
    SampleBuffer buffer;
    buffer_init(&buffer);

    while (1) {
        float raw_data = get_accelerometer_data();
        buffer_add(&buffer, raw_data);

        float std_dev = buffer_std_dev(&buffer);
        if (std_dev > THRESHOLD) {
            // Anomaly detected
            printf("Anomaly detected! Standard deviation: %.2f\n", std_dev);
        }

        // Simulate real-time delay
        for (volatile int i = 0; i < 10000; i++);
    }
}

int main() {
    process_pipeline();
    return 0;
}
