### ✅ Code: Basic 2D Platformer with Physics and Sprite Animation

```html
<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8" />
  <title>2D Platformer</title>
  <script src="https://cdn.jsdelivr.net/npm/phaser@3.55.2/dist/phaser.js"></script>
</head>
<body>
  <script>
    const config = {
      type: Phaser.AUTO,
      width: 800,
      height: 600,
      physics: {
        default: 'arcade',
        arcade: {
          gravity: { y: 300 },
          debug: false
        }
      },
      scene: {
        preload: preload,
        create: create,
        update: update
      }
    };

    const game = new Phaser.Game(config);

    let player;
    let platforms;
    let cursors;
    let animationTimer = 0;

    function preload() {
      // Load a placeholder sprite (you can replace this with your own sprite sheet)
      this.load.image('player', 'https://i.imgur.com/5Lc9g5g.png'); // Placeholder
      this.load.image('ground', 'https://i.imgur.com/7v6Vn0A.png'); // Placeholder
    }

    function create() {
      // Create platforms
      platforms = this.physics.add.staticGroup();
      platforms.create(400, 560, 'ground').setScale(2).refreshBody();

      // Create player
      player = this.physics.add.sprite(100, 450, 'player');
      player.setBounce(0.2);
      player.setCollideWorldBounds(true);

      // Animation setup (simple idle/run)
      this.anims.create({
        key: 'left',
        frames: [{ key: 'player' }],
        frameRate: 10,
        repeat: -1
      });

      this.anims.create({
        key: 'right',
        frames: [{ key: 'player' }],
        frameRate: 10,
        repeat: -1
      });

      // Input
      cursors = this.input.keyboard.createCursorKeys();

      // Collision between player and platforms
      this.physics.add.collider(player, platforms);
    }

    function update() {
      if (cursors.left.isDown) {
        player.setVelocityX(-160);
        player.anims.play('left', true);
      } else if (cursors.right.isDown) {
        player.setVelocityX(160);
        player.anims.play('right', true);
      } else {
        player.setVelocityX(0);
        player.anims.stop();
      }

      if (cursors.up.isDown && player.body.touching.down) {
        player.setVelocityY(-330);
      }
    }
  </script>
</body>
</html>
```

