### 🕹️ Minimal 2D Platformer (JavaScript + Phaser.js)

```html
<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8">
  <title>Minimal 2D Platformer</title>
  <script src="https://cdn.jsdelivr.net/npm/phaser@3.55.2/dist/phaser.js"></script>
</head>
<body>
  <script>
    const config = {
      type: Phaser.AUTO,
      width: 800,
      height: 600,
      physics: {
        default: 'arcade',
        arcade: {
          gravity: { y: 300 },
          debug: false
        }
      },
      scene: {
        preload: preload,
        create: create,
        update: update
      }
    };

    const game = new Phaser.Game(config);

    let player;
    let platforms;
    let cursors;

    function preload() {
      // Load a placeholder sprite sheet (e.g., from https://opengameart.org/)
      this.load.image('player', 'https://upload.wikimedia.org/wikipedia/commons/thumb/0/0d/Red_Square.svg/120px-Red_Square.svg.png');
      this.load.image('ground', 'https://upload.wikimedia.org/wikipedia/commons/thumb/6/62/Blue_Square.svg/120px-Blue_Square.svg.png');
    }

    function create() {
      // Create the ground and platforms
      platforms = this.physics.add.staticGroup();
      platforms.create(400, 560, 'ground').setScale(20).refreshBody();

      // Create the player
      player = this.physics.add.sprite(100, 450, 'player');
      player.setBounce(0.2);
      player.setCollideWorldBounds(true);

      // Create animations (simple frame cycling)
      this.anims.create({
        key: 'walk',
        frames: [{ key: 'player', frame: 0 }],
        frameRate: 10,
        repeat: -1
      });

      // Enable animation
      player.anims.play('walk', true);

      // Input controls
      cursors = this.input.keyboard.createCursorKeys();

      // Collision between player and platforms
      this.physics.add.collider(player, platforms);
    }

    function update() {
      // Horizontal movement
      if (cursors.left.isDown) {
        player.setVelocityX(-160);
      } else if (cursors.right.isDown) {
        player.setVelocityX(160);
      } else {
        player.setVelocityX(0);
      }

      // Jumping
      if (cursors.up.isDown && player.body.touching.down) {
        player.setVelocityY(-330);
      }
    }
  </script>
</body>
</html>
```

