### 📄 `main.js`

```javascript
// Scene Setup
const scene = new THREE.Scene();
const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
camera.position.z = 5;

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(window.innerWidth, window.innerHeight);
document.body.appendChild(renderer.domElement);

// Orbit Controls
const controls = new THREE.OrbitControls(camera, renderer.domElement);

// Dynamic Light
const light = new THREE.PointLight(0xffffff, 1, 100);
light.position.set(0, 0, 10);
scene.add(light);

// Custom Shader Material (Dynamic Lighting)
const vertexShader = `
  varying vec3 vNormal;
  void main() {
    vNormal = normalize(normalMatrix * normal);
    gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
  }
`;

const fragmentShader = `
  varying vec3 vNormal;
  uniform vec3 lightPosition;
  uniform float time;

  void main() {
    vec3 lightDir = normalize(lightPosition - gl_FragCoord.xyz);
    float diff = max(dot(vNormal, lightDir), 0.0);
    vec3 color = vec3(0.5 + 0.5 * diff, 0.3 + 0.3 * diff, 0.2 + 0.2 * diff);
    gl_FragColor = vec4(color, 1.0);
  }
`;

const material = new THREE.ShaderMaterial({
  vertexShader: vertexShader,
  fragmentShader: fragmentShader,
  uniforms: {
    lightPosition: { value: new THREE.Vector3(0, 0, 10) },
    time: { value: 0.0 }
  }
});

// Geometry
const geometry = new THREE.SphereGeometry(1, 32, 32);
const mesh = new THREE.Mesh(geometry, material);
scene.add(mesh);

// Animation Loop
function animate() {
  requestAnimationFrame(animate);

  // Update light position dynamically
  const time = performance.now() * 0.001;
  light.position.x = Math.sin(time) * 5;
  light.position.z = Math.cos(time) * 5;
  material.uniforms.lightPosition.value.copy(light.position);
  material.uniforms.time.value = time;

  mesh.rotation.y += 0.01;

  renderer.render(scene, camera);
}

animate();

// Handle Window Resize
window.addEventListener('resize', () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
});
```

