### ✅ **Implementation: Real-Time 3D Scene Viewer with Shaders and Dynamic Lighting**

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <title>Real-Time 3D Scene Viewer</title>
  <style>
    body { margin: 0; overflow: hidden; }
    canvas { display: block; }
  </style>
</head>
<body>
  <!-- Include Three.js from CDN -->
  <script src="https://cdn.jsdelivr.net/npm/three@0.157.0/build/three.min.js"></script>
  <script>
    // Scene setup
    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    document.body.appendChild(renderer.domElement);

    // Light (dynamic)
    const light = new THREE.PointLight(0xffffff, 1.5);
    light.position.set(5, 5, 5);
    scene.add(light);

    // Shader material (custom fragment shader for dynamic lighting)
    const vertexShader = `
      varying vec3 vPosition;
      void main() {
        vPosition = position;
        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
      }
    `;

    const fragmentShader = `
      varying vec3 vPosition;
      uniform vec3 lightPosition;
      void main() {
        // Calculate distance from light
        float distanceToLight = distance(vPosition, lightPosition);
        float glowIntensity = 1.0 / (distanceToLight * 0.5 + 0.1);

        // Base color with glow
        vec3 baseColor = vec3(0.2, 0.6, 1.0);
        vec3 glow = baseColor * glowIntensity;

        gl_FragColor = vec4(glow, 1.0);
      }
    `;

    const shaderMaterial = new THREE.ShaderMaterial({
      uniforms: {
        lightPosition: { value: new THREE.Vector3() }
      },
      vertexShader: vertexShader,
      fragmentShader: fragmentShader
    });

    // Mesh (sphere with shader)
    const geometry = new THREE.SphereGeometry(2, 64, 64);
    const mesh = new THREE.Mesh(geometry, shaderMaterial);
    scene.add(mesh);

    // Camera position
    camera.position.z = 5;

    // Animation loop
    function animate() {
      requestAnimationFrame(animate);

      // Animate light position
      light.position.x = Math.sin(Date.now() * 0.002) * 10;
      light.position.y = Math.cos(Date.now() * 0.002) * 10;
      light.position.z = Math.sin(Date.now() * 0.002) * 10;

      // Update shader uniform
      shaderMaterial.uniforms.lightPosition.value.copy(light.position);

      // Rotate mesh for visual feedback
      mesh.rotation.x += 0.01;
      mesh.rotation.y += 0.01;

      renderer.render(scene, camera);
    }

    animate();

    // Handle window resize
    window.addEventListener('resize', () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
    });
  </script>
</body>
