Here's a **minimal working version** of a real-time 3D scene viewer with **dynamic lighting** and **shader effects** using **JavaScript + WebGL** via **Three.js** (a high-level WebGL library). This example includes a glowing sphere with dynamic lighting and a simple shader effect.

---

### 📄 `index.html`
```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <title>Real-Time 3D Viewer</title>
  <style>
    body { margin: 0; overflow: hidden; }
    canvas { display: block; }
  </style>
</head>
<body>
  <script src="https://cdn.jsdelivr.net/npm/three@0.158.0/build/three.min.js"></script>
  <script>
    // Scene setup
    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    document.body.appendChild(renderer.domElement);

    // Light (dynamic)
    const light = new THREE.PointLight(0xffffff, 1, 100);
    light.position.set(5, 5, 5);
    scene.add(light);

    // Shader material (glowing effect)
    const shaderMaterial = new THREE.ShaderMaterial({
      uniforms: {
        u_time: { value: 0 },
        u_lightPosition: { value: new THREE.Vector3() },
      },
      vertexShader: `
        varying vec2 vUv;
        void main() {
          vUv = uv;
          gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
        }
      `,
      fragmentShader: `
        uniform float u_time;
        uniform vec3 u_lightPosition;
        varying vec2 vUv;

        void main() {
          vec3 lightDir = normalize(u_lightPosition - gl_FragCoord.xy);
          float intensity = 1.0 - length(lightDir);
          vec3 color = vec3(1.0, 0.5, 0.2) * intensity;
          gl_FragColor = vec4(color, 1.0);
        }
      `,
    });

    // Geometry and mesh
    const geometry = new THREE.SphereGeometry(1, 32, 32);
    const mesh = new THREE.Mesh(geometry, shaderMaterial);
    scene.add(mesh);

    // Camera position
    camera.position.z = 3;

    // Animation loop
    function animate() {
      requestAnimationFrame(animate);

      // Update light position dynamically
      light.position.x = Math.sin(Date.now() * 0.002) * 5;
      light.position.y = Math.cos(Date.now() * 0.002) * 5;
      light.position.z = Math.sin(Date.now() * 0.003) * 5;

      // Update shader uniforms
      shaderMaterial.uniforms.u_lightPosition.value.copy(light.position);
      shaderMaterial.uniforms.u_time.value += 0.01;

      renderer.render(scene, camera);
    }

    animate();

    // Handle window resize
    window.addEventListener('resize', () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
    });
  </script>
</body>
</html>
```

