        Vector3 relativeVelocity = a->velocity - b->velocity;
        Vector3 normal = (b->position - a->position).Normalize();

        float velocityAlongNormal = relativeVelocity.Dot(normal);

        if (velocityAlongNormal > 0.0f) return; // No collision

