```cpp
#include "PhysicsPlugin.h"
#include <iostream>

PhysicsSystem::PhysicsSystem() {
    collisionResolver = new CollisionResolver();
}

PhysicsSystem::~PhysicsSystem() {
    delete collisionResolver;
}

void PhysicsSystem::Update(float deltaTime) {
    for (auto body : rigidBodies) {
        body->Update(deltaTime);
    }
    ResolveCollisions();
}

void PhysicsSystem::AddRigidBody(RigidBody* body) {
    rigidBodies.push_back(body);
}

void PhysicsSystem::ResolveCollisions() {
    for (size_t i = 0; i < rigidBodies.size(); ++i) {
        for (size_t j = i + 1; j < rigidBodies.size(); ++j) {
            if (rigidBodies[i]->CheckCollision(rigidBodies[j])) {
                CollisionResolver::ResolveCollision(rigidBodies[i], rigidBodies[j]);
            }
        }
    }
}

RigidBody::RigidBody(float mass, float radius, const glm::vec3& position, const glm::vec3& velocity)
    : mass(mass), radius(radius), position(position), velocity(velocity) {}

