    position += velocity * deltaTime;
}

bool RigidBody::CheckCollision(RigidBody* other) {
    float distance = glm::distance(position, other->position);
    return distance < (radius + other->radius);
}

void CollisionResolver::ResolveCollision(RigidBody* a, RigidBody* b) {
    glm::vec3 normal = glm::normalize(a->position - b->position);
    float overlap = (a->radius + b->radius) - glm::distance(a->position, b->position);

    // Simple resolution: push apart
    a->position += normal * (overlap * 0.5f);
    b->position -= normal * (overlap * 0.5f);

    // Simple impulse-based velocity change
    float restitution = 0.5f;
    glm::vec3 relativeVelocity = b->velocity - a->velocity;
    float velocityAlongNormal = glm::dot(relativeVelocity, normal);

    if (velocityAlongNormal > 0.0f) return;

    float impulse = -(1.0f + restitution) * velocityAlongNormal;
    impulse /= (1.0f / a->mass + 1.0f / b->mass);

    a->velocity -= impulse * (1.0f / a->mass) * normal;
    b->velocity += impulse * (1.0f / b->mass) * normal;
}
