    float x, y, z;

    Vector3(float x = 0.0f, float y = 0.0f, float z = 0.0f) : x(x), y(y), z(z) {}

    Vector3 operator+(const Vector3& other) const {
        return Vector3(x + other.x, y + other.y, z + other.z);
    }

    Vector3 operator*(float scalar) const {
        return Vector3(x * scalar, y * scalar, z * scalar);
    }

    Vector3 operator-(const Vector3& other) const {
        return Vector3(x - other.x, y - other.y, z - other.z);
    }

    float magnitude() const {
        return std::sqrt(x * x + y * y + z * z);
    }

    Vector3 normalize() const {
        float mag = magnitude();
        return mag > 0.0f ? Vector3(x / mag, y / mag, z / mag) : Vector3();
    }
};

struct RigidBody {
    Vector3 position;
    Vector3 velocity;
    Vector3 acceleration;
    float mass;
    Vector3 boundsMin;
    Vector3 boundsMax;

    RigidBody(Vector3 pos, float mass = 1.0f, Vector3 min = {-0.5f, -0.5f, -0.5f}, Vector3 max = {0.5f, 0.5f, 0.5f})
        : position(pos), mass(mass), boundsMin(min), boundsMax(max), velocity(0.0f, 0.0f, 0.0f), acceleration(0.0f, 0.0f, 0.0f) {}
};

class PhysicsEngine {
public:
    static void UpdatePhysics(std::vector<RigidBody*>& bodies, float deltaTime);
    static bool CheckCollision(RigidBody* a, RigidBody* b);
};

#endif // PHYSICSPROJECT_PHYSICSPROGRAM_H
