#include "PhysicsPlugin.h"
#include <algorithm>

void PhysicsEngine::UpdatePhysics(std::vector<RigidBody*>& bodies, float deltaTime) {
    // Apply gravity
    for (auto body : bodies) {
        body->acceleration.y -= 9.81f; // gravity
    }

    // Integrate acceleration into velocity and position
    for (auto body : bodies) {
        body->velocity += body->acceleration * deltaTime;
        body->position += body->velocity * deltaTime;
        body->acceleration = Vector3(); // reset acceleration
    }

    // Check for collisions
    for (size_t i = 0; i < bodies.size(); ++i) {
        for (size_t j = i + 1; j < bodies.size(); ++j) {
            if (CheckCollision(bodies[i], bodies[j])) {
                // Basic collision response: reverse velocities
                std::swap(bodies[i]->velocity, bodies[j]->velocity);
            }
        }
    }
}

bool PhysicsEngine::CheckCollision(RigidBody* a, RigidBody* b) {
    // Axis-Aligned Bounding Box (AABB) collision
    bool xOverlap = (a->position.x + a->boundsMax.x) > (b->position.x + b->boundsMin.x) &&
                    (a->position.x + a->boundsMin.x) < (b->position.x + b->boundsMax.x);
    bool yOverlap = (a->position.y + a->boundsMax.y) > (b->position.y + b->boundsMin.y) &&
                    (a->position.y + a->boundsMin.y) < (b->position.y + b->boundsMax.y);
    bool zOverlap = (a->position.z + a->boundsMax.z) > (b->position.z + b->boundsMin.z) &&
                    (a->position.z + a->boundsMin.z) < (b->position.z + b->boundsMax.z);

    return xOverlap && yOverlap && zOverlap;
}
