// Forward declaration for collision detection
struct AABB {
    float x, y, z;
    float width, height, depth;
    bool Intersects(const AABB& other) const {
        return (x < other.x + other.width && 
                x + width > other.x &&
                y < other.y + other.height &&
                y + height > other.y &&
                z < other.z + other.depth &&
                z + depth > other.z);
    }
};

// Rigid body with position, velocity, and mass
struct RigidBody {
    float x, y, z;
    float vx, vy, vz;
    float mass;
    AABB bounds;

    RigidBody(float _x, float _y, float _z, float _mass, float _width, float _height, float _depth)
        : x(_x), y(_y), z(_z), mass(_mass), bounds{_x, _y, _z, _width, _height, _depth} {
        vx = 0.0f;
        vy = 0.0f;
        vz = 0.0f;
    }

    void ApplyForce(float fx, float fy, float fz) {
        vx += fx / mass * 0.01f; // dt = 0.01s
        vy += fy / mass * 0.01f;
        vz += fz / mass * 0.01f;
    }

    void Update(float gravity) {
        vy += gravity * 0.01f; // Apply gravity
        x += vx * 0.01f;
        y += vy * 0.01f;
        z += vz * 0.01f;
    }

    void ResolveCollision(RigidBody& other) {
        if (bounds.Intersects(other.bounds)) {
            // Simple collision resolution: reverse velocities
            std::swap(vx, other.vx);
            std::swap(vy, other.vy);
            std::swap(vz, other.vz);
        }
    }
};

// Custom Physics Plugin
