// Forward declaration of the engine's API
namespace Engine {
    class GameObject;
    class Transform;
    class PhysicsSystem;
}

// Custom Physics Plugin
class CustomPhysicsPlugin {
public:
    // Initialize the plugin with the engine's physics system
    void Initialize(Engine::PhysicsSystem* enginePhysicsSystem) {
        this->enginePhysicsSystem = enginePhysicsSystem;
        enginePhysicsSystem->RegisterPhysicsPlugin(this);
    }

    // Update physics for all registered rigid bodies
    void Update(float deltaTime) {
        for (auto& body : rigidBodies) {
            UpdateRigidBody(body, deltaTime);
        }
    }

    // Add a rigid body to the simulation
    void AddRigidBody(Engine::GameObject* gameObject) {
        rigidBodies.push_back(std::make_unique<RigidBody>(gameObject));
    }

    // Collision detection (simplified AABB check)
    bool CheckCollision(RigidBody& a, RigidBody& b) {
        // AABB collision test
        return (a.position.x < b.position.x + b.size.x &&
                a.position.x + a.size.x > b.position.x &&
                a.position.y < b.position.y + b.size.y &&
                a.position.y + a.size.y > b.position.y);
    }

    // Resolve collision (basic response)
    void ResolveCollision(RigidBody& a, RigidBody& b) {
        // Simple position separation
        float overlapX = (a.position.x + a.size.x) - (b.position.x);
        float overlapY = (a.position.y + a.size.y) - (b.position.y);
        float minOverlap = std::min(overlapX, overlapY);

        if (minOverlap > 0.0f) {
            a.position.x -= minOverlap * 0.5f;
            b.position.x += minOverlap * 0.5f;
        }
    }

private:
    std::vector<std::unique_ptr<RigidBody>> rigidBodies;
    Engine::PhysicsSystem* enginePhysicsSystem;

    // Simulate a single rigid body
    void UpdateRigidBody(RigidBody& body, float deltaTime) {
        // Gravity
        body.velocity.y -= 9.81f * deltaTime;

        // Apply velocity
        body.position += body.velocity * deltaTime;

        // Collision with ground (simple example)
        if (body.position.y < 0.0f) {
            body.position.y = 0.0f;
            body.velocity.y *= -0.7f; // Bounce
        }

        // Check for collisions with other bodies
        for (size_t i = 0; i < rigidBodies.size(); ++i) {
            if (&body == rigidBodies[i].get()) continue;
            if (CheckCollision(body, *rigidBodies[i])) {
                ResolveCollision(body, *rigidBodies[i]);
            }
        }
    }
};

