public:
    RigidBody(float mass, float x, float y, float vx, float vy)
        : mass(mass), x(x), y(y), vx(vx), vy(vy) {}

    float x, y;       // Position
    float vx, vy;     // Velocity
    float mass;       // Mass

    void applyForce(float fx, float fy, float dt) {
        float ax = fx / mass;
        float ay = fy / mass;
        vx += ax * dt;
        vy += ay * dt;
    }

    void integrate(float dt) {
        x += vx * dt;
        y += vy * dt;
    }
};

// Physics plugin interface
class PhysicsPlugin {
public:
    virtual void addRigidBody(RigidBody* body) = 0;
    virtual void simulate(float dt) = 0;
    virtual std::vector<RigidBody*> getBodies() = 0;
};

// Concrete implementation of the plugin
class SimplePhysicsPlugin : public PhysicsPlugin {
public:
    void addRigidBody(RigidBody* body) override {
        bodies.push_back(body);
    }

    void simulate(float dt) override {
        // Apply gravity (simplified)
        for (auto body : bodies) {
            body->applyForce(0.0f, -9.81f * body->mass, dt);
        }

        // Integrate motion
        for (auto body : bodies) {
            body->integrate(dt);
        }

        // Simple AABB collision detection between all pairs
        for (size_t i = 0; i < bodies.size(); ++i) {
            for (size_t j = i + 1; j < bodies.size(); ++j) {
                RigidBody* a = bodies[i];
                RigidBody* b = bodies[j];

                // AABB collision (simplified to point-to-point for this example)
                if (std::abs(a->x - b->x) < 1.0f && std::abs(a->y - b->y) < 1.0f) {
                    // Resolve collision (simplified: reverse velocities)
                    std::swap(a->vx, b->vx);
                    std::swap(a->vy, b->vy);
                }
            }
        }
    }

    std::vector<RigidBody*> getBodies() override {
        return bodies;
    }

private:
    std::vector<RigidBody*> bodies;
};

#endif // PHYSICS_PLUGIN_H
