bool CheckCollision(const RigidBody& a, const RigidBody& b) {
    return (a.position.x < b.position.x + b.size &&
            a.position.x + a.size > b.position.x &&
            a.position.y < b.position.y + b.size &&
            a.position.y + a.size > b.position.y);
}

