### 📦 Code: `main.cpp`

```cpp
#include <iostream>
#include <vector>
#include <chrono>
#include <cmath>

// Define a simple rigid body
struct RigidBody {
    float x, y;       // Position
    float vx, vy;     // Velocity
    float mass;       // Mass
    float radius;     // Radius for collision (simplified)
};

// Physics world with gravity
class PhysicsWorld {
public:
    PhysicsWorld() : gravity(0.0f, -9.81f), fixedDeltaTime(1.0f / 60.0f) {}

    void addBody(RigidBody body) {
        bodies.push_back(body);
    }

    void update(float deltaTime) {
        // Apply gravity
        for (auto& body : bodies) {
            body.vy += gravity.y * deltaTime;
            body.vx += gravity.x * deltaTime;
        }

        // Integrate motion (Euler integration)
        for (auto& body : bodies) {
            body.x += body.vx * deltaTime;
            body.y += body.vy * deltaTime;
        }

        // Collision with ground (y = 0)
        for (auto& body : bodies) {
            if (body.y - body.radius < 0.0f) {
                body.y = body.radius;
                body.vy *= -0.8f; // Bounce with damping
            }
        }
    }

    std::vector<RigidBody> getBodies() const { return bodies; }

private:
    std::vector<RigidBody> bodies;
    glm::vec2 gravity;
    float fixedDeltaTime;
};

// Main simulation loop
int main() {
    PhysicsWorld world;

    // Create two rigid bodies
    RigidBody body1 = {100.0f, 100.0f, 0.0f, 0.0f, 1.0f, 10.0f};
    RigidBody body2 = {200.0f, 150.0f, 0.0f, 0.0f, 1.0f, 15.0f};
    world.addBody(body1);
    world.addBody(body2);

    // Frame-rate independent simulation
    auto lastTime = std::chrono::high_resolution_clock::now();
    float accumulator = 0.0f;

    while (true) {
        auto now = std::chrono::high_resolution_clock::now();
        float deltaTime = std::chrono::duration<float>(now - lastTime).count();
        lastTime = now;

        accumulator += deltaTime;

        // Simulate physics with fixed time steps
        while (accumulator >= PhysicsWorld::fixedDeltaTime) {
            world.update(PhysicsWorld::fixedDeltaTime);
            accumulator -= PhysicsWorld::fixedDeltaTime;
        }

        // Render (console output for simplicity)
        std::cout << "Bodies:\n";
        for (const auto& body : world.getBodies()) {
            std::cout << "  Body at (" << body.x << ", " << body.y << ")\n";
        }
        std::cout << "\n";
    }

    return 0;
}
```

