### <language>C++</language> Implementation

```cpp
#include <iostream>
#include <vector>
#include <chrono>
#include <thread>
#include <cmath>

// Rigid Body Class
class RigidBody {
public:
    double x, y;      // Position
    double vx, vy;    // Velocity
    double mass;      // Mass
    double radius;    // For collision detection

    RigidBody(double x, double y, double mass, double radius)
        : x(x), y(y), vx(0.0), vy(0.0), mass(mass), radius(radius) {}

    void applyForce(double fx, double fy, double dt) {
        double ax = fx / mass;
        double ay = fy / mass;
        vx += ax * dt;
        vy += ay * dt;
    }

    void update(double dt) {
        x += vx * dt;
        y += vy * dt;
    }

    void resolveCollision(RigidBody& other) {
        double dx = x - other.x;
        double dy = y - other.y;
        double distance = std::sqrt(dx * dx + dy * dy);

        if (distance < radius + other.radius) {
            // Simple elastic collision: swap velocities
            std::swap(vx, other.vx);
            std::swap(vy, other.vy);
        }
    }

    void render() const {
        std::cout << "Body at (" << x << ", " << y << ") with velocity (" << vx << ", " << vy << ")\n";
    }
};

// Physics World Class
class PhysicsWorld {
public:
    std::vector<RigidBody> bodies;
    double gravity = 9.81; // m/s²

    void addBody(RigidBody body) {
        bodies.push_back(body);
    }

    void simulate(double dt) {
        // Apply gravity
        for (auto& body : bodies) {
            body.applyForce(0.0, -body.mass * gravity, dt);
        }

        // Update positions
        for (auto& body : bodies) {
            body.update(dt);
        }

        // Collision detection and resolution
        for (size_t i = 0; i < bodies.size(); ++i) {
            for (size_t j = i + 1; j < bodies.size(); ++j) {
                bodies[i].resolveCollision(bodies[j]);
            }
        }
    }
};

int main() {
    // Initialize physics world
    PhysicsWorld world;
    world.addBody(RigidBody(0.0, 10.0, 1.0, 1.0));
    world.addBody(RigidBody(5.0, 10.0, 1.0, 1.0));

    // Fixed time step (60 Hz)
    const double fixedDeltaTime = 1.0 / 60.0;
    double accumulator = 0.0;

    // Simulation loop
    auto start = std::chrono::high_resolution_clock::now();
    while (true) {
        auto now = std::chrono::high_resolution_clock::now();
        double dt = std::chrono::duration<double>(now - start).count();
        start = now;

        accumulator += dt;

        while (accumulator >= fixedDeltaTime) {
            world.simulate(fixedDeltaTime);
            accumulator -= fixedDeltaTime;
        }

        // Render (console-based)
        std::system("cls"); // Clear console
        for (const auto& body : world.bodies) {
            body.render();
        }

        // Sleep to avoid high CPU usage
        std::this_thread::sleep_for(std::chrono::milliseconds(16)); // ~60 FPS
    }

    return 0;
}
```

