### 🧱 Code: Minimal Real-Time Physics Simulation with Bullet Physics

```cpp
#include <iostream>
#include <chrono>
#include <vector>
#include <GL/glut.h>
#include "btBulletDynamicsCommon.h"

// Global variables
btDiscreteDynamicsWorld* dynamicsWorld;
btDefaultCollisionConfiguration* collisionConfiguration;
btCollisionDispatcher* dispatcher;
btBroadphaseInterface* overlappingPairCache;
btSequentialImpulseConstraintSolver* solver;

// Simple camera setup
float cameraX = 0.0f, cameraY = 5.0f, cameraZ = -10.0f;

// Frame-rate control
const float FIXED_TIME_STEP = 1.0f / 60.0f; // 60 Hz
float accumulator = 0.0f;

// Initialize physics world
void initPhysics() {
    collisionConfiguration = new btDefaultCollisionConfiguration();
    dispatcher = new btCollisionDispatcher(collisionConfiguration);
    overlappingPairCache = new btDbvtBroadphase();
    solver = new btSequentialImpulseConstraintSolver();
    dynamicsWorld = new btDiscreteDynamicsWorld(dispatcher, overlappingPairCache, solver, collisionConfiguration);

    dynamicsWorld->setGravity(btVector3(0, -9.81f, 0)); // Earth gravity

    // Ground plane
    btCollisionShape* groundShape = new btStaticPlaneShape(btVector3(0, 1, 0), 0);
    btDefaultMotionState* groundMotionState = new btDefaultMotionState(btTransform(btQuaternion(0, 0, 0, 1), btVector3(0, -1, 0)));
    btRigidBody::btRigidBodyConstructionInfo groundInfo(0, groundMotionState, groundShape, btVector3(0, 0, 0));
    btRigidBody* groundBody = new btRigidBody(groundInfo);
    dynamicsWorld->addRigidBody(groundBody);

    // Falling box
    btCollisionShape* boxShape = new btBoxShape(btVector3(1, 1, 1));
    btDefaultMotionState* boxMotionState = new btDefaultMotionState(btTransform(btQuaternion(0, 0, 0, 1), btVector3(0, 10, 0)));
    btScalar mass = 1.0f;
    btVector3 inertia;
    boxShape->calculateLocalInertia(mass, inertia);
    btRigidBody::btRigidBodyConstructionInfo boxInfo(mass, boxMotionState, boxShape, inertia);
    btRigidBody* boxBody = new btRigidBody(boxInfo);
    dynamicsWorld->addRigidBody(boxBody);
}

// Rendering callback
void display() {
    glClear(GL_COLOR_BUFFER_BIT | GL_DEPTH_BUFFER_BIT);
    glLoadIdentity();

    // Camera
    gluLookAt(cameraX, cameraY, cameraZ, 0, 0, 0, 0, 1, 0);

    // Draw ground
    glBegin(GL_QUADS);
    glColor3f(0.5f, 0.5f, 0.5f);
    glVertex3f(-10, -1, -10);
    glVertex3f(10, -1, -10);
    glVertex3f(10, -1, 10);
    glVertex3f(-10, -1, 10);
    glEnd();

    // Draw falling box
    btTransform trans;
    boxBody->getMotionState()->getWorldTransform(trans);
    btVector3 pos = trans.getOrigin();
    btQuaternion rot = trans.getRotation();

    glPushMatrix();
    glTranslatef(pos.getX(), pos.getY(), pos.getZ());
    glMultMatrixf(rot.getMatrix());
    glColor3f(1.0f, 0.0f, 0.0f);
    glutSolidCube(2.0f);
    glPopMatrix();

    glutSwapBuffers();
}

// Main loop
void mainLoop(int value) {
    auto currentTime = std::chrono::high_resolution_clock::now();
    float deltaTime = std::chrono::duration<float>(currentTime - lastTime).count();
    lastTime = currentTime;

    accumulator += deltaTime;

    while (accumulator >= FIXED_TIME_STEP) {
        dynamicsWorld->stepSimulation(FIXED_TIME_STEP, 10);
        accumulator -= FIXED_TIME_STEP;
    }

    display();
    glutTimerFunc(16, mainLoop, 0); // ~60 FPS
}

// Cleanup
void cleanup() {
    dynamicsWorld->removeRigidBody(boxBody);
    dynamicsWorld->removeRigidBody(groundBody);
    delete dynamicsWorld;
    delete solver;
    delete overlappingPairCache;
    delete dispatcher;
    delete collisionConfiguration;
}

// Main function
int main(int argc, char** argv) {
    glutInit(&argc, argv);
    glutInitDisplayMode(GLUT_DOUBLE | GLUT_RGB | GLUT_DEPTH);
    glutInitWindowSize(800, 600);
    glutCreateWindow("Real-Time Physics Simulation");

    glEnable(GL_DEPTH_TEST);

    initPhysics();

    lastTime = std::chrono::high_resolution_clock::now();
    glutDisplayFunc(display);
    glutTimerFunc(16, mainLoop, 0); // ~60 FPS
    glutMainLoop();

    cleanup();
    return 0;
}
```

---

### 📌 Key Features
1. **Physics Engine**: Uses **Bullet Physics** for accurate rigid body dynamics (gravity, collision, etc.).
2. **Frame-Rate Constraints**: Uses a **fixed time step** (`FIXED_TIME_STEP = 1/60`) to ensure consistent physics updates, even if rendering lags.
3. **Accumulator**: Accumulates elapsed time to "catch up" physics steps when the frame rate drops.
4. **OpenGL Rendering**: Visualizes the simulation with a falling box and ground plane.

