    pub amount: f64,
    pub timestamp: u64,
    pub status: TransactionStatus,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub enum TransactionStatus {
    Pending,
    Completed,
    Failed,
}

// Mock database interface
pub trait Database {
    fn get_balance(&self, account_id: &str) -> Result<f64, String>;
    fn update_balance(&self, account_id: &str, amount: f64) -> Result<(), String>;
    fn record_transaction(&self, transaction: &Transaction) -> Result<(), String>;
}

// In-memory mock database
struct MockDatabase {
    balances: HashMap<String, f64>,
    transactions: HashMap<String, Transaction>,
}

impl Database for MockDatabase {
    fn get_balance(&self, account_id: &str) -> Result<f64, String> {
        match self.balances.get(account_id) {
            Some(balance) => Ok(*balance),
            None => Err(format!("Account {} not found", account_id)),
        }
    }

    fn update_balance(&self, account_id: &str, amount: f64) -> Result<(), String> {
        let balance = self.get_balance(account_id)?;
        self.balances.insert(account_id.to_string(), balance + amount);
        Ok(())
    }

    fn record_transaction(&self, transaction: &Transaction) -> Result<(), String> {
        if self.transactions.contains_key(&transaction.transaction_id) {
            return Err("Transaction ID already exists".to_string());
        }
        self.transactions.insert(transaction.transaction_id.clone(), transaction.clone());
        Ok(())
    }
}

// Payment processor
pub struct PaymentProcessor {
    db: Arc<Mutex<dyn Database>>,
}

impl PaymentProcessor {
    pub fn new(db: Arc<Mutex<dyn Database>>) -> Self {
        PaymentProcessor { db }
    }

    pub async fn process_payment(
        &self,
        from_account: &str,
        to_account: &str,
        amount: f64,
    ) -> Result<Transaction, String> {
        if amount <= 0.0 {
            return Err("Amount must be positive".to_string());
        }

        let transaction_id = generate_transaction_id();
        let timestamp = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap()
            .as_secs();

        let mut db = self.db.lock().unwrap();

        // Validate accounts and balances
        let from_balance = db.get_balance(from_account)?;
        let to_balance = db.get_balance(to_account)?;

        if from_balance < amount {
            return Err("Insufficient funds".to_string());
        }

        // Create transaction
        let transaction = Transaction {
            transaction_id: transaction_id.clone(),
            from_account: from_account.to_string(),
            to_account: to_account.to_string(),
            amount,
            timestamp,
            status: TransactionStatus::Pending,
        };

        // Update balances and record transaction
        db.update_balance(from_account, -amount)?;
        db.update_balance(to_account, amount)?;
        db.record_transaction(&transaction)?;

        Ok(transaction)
    }
}

// Helper to generate a unique transaction ID
fn generate_transaction_id() -> String {
    use uuid::Uuid;
    Uuid::new_v4().to_string()
}

// Example usage
#[tokio::main]
async fn main() {
    let db = Arc::new(Mutex::new(MockDatabase {
        balances: HashMap::from([
            ("account_123".to_string(), 1000.0),
            ("account_456".to_string(), 500.0),
        ]),
        transactions: HashMap::new(),
    }));

    let processor = PaymentProcessor::new(db.clone());

    // Process a payment
    match processor.process_payment("account_123", "account_456", 200.0).await {
        Ok(tx) => {
            println!("Transaction successful: {:?}", tx);
        }
        Err(e) => {
            println!("Transaction failed: {}", e);
        }
    }
}
```

