func main() {
    // Initialize the payment processor
    processor := payment.NewPaymentProcessor()

    // Define HTTP routes
    http.HandleFunc("/process", func(w http.ResponseWriter, r *http.Request) {
        if r.Method != "POST" {
            http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
            return
        }

        // Parse request body
        var payment payment.PaymentRequest
        if err := payment.Parse(r); err != nil {
            http.Error(w, "Invalid request body", http.StatusBadRequest)
            return
        }

        // Validate payment
        if err := payment.Validate(); err != nil {
            http.Error(w, err.Error(), http.StatusBadRequest)
            return
        }

        // Process payment
        result, err := processor.ProcessPayment(payment)
        if err != nil {
            http.Error(w, err.Error(), http.StatusInternalServerError)
            return
        }

        // Log transaction
        logger.LogTransaction(payment, result)

        // Respond
        fmt.Fprintf(w, "Payment processed: %v", result)
    })

    // Start server
    log.Println("Starting payment service on :8080...")
