```java
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

// Represents a user account
class Account {
    private String accountId;
    private double balance;

    public Account(String accountId, double initialBalance) {
        this.accountId = accountId;
        this.balance = initialBalance;
    }

    public String getAccountId() {
        return accountId;
    }

    public synchronized double getBalance() {
        return balance;
    }

    public synchronized boolean deduct(double amount) {
        if (balance >= amount) {
            balance -= amount;
            return true;
        }
        return false;
    }

    public synchronized void add(double amount) {
        balance += amount;
    }
}

// Payment processor with thread-safe handling
class PaymentProcessor {
    private final Map<String, Account> accounts;
    private final ExecutorService executor;

    public PaymentProcessor() {
        this.accounts = new HashMap<>();
        this.executor = Executors.newFixedThreadPool(4); // Thread pool for concurrency
    }

    public void createAccount(String accountId, double initialBalance) {
        accounts.put(accountId, new Account(accountId, initialBalance));
    }

    public void processPayment(String senderId, String receiverId, double amount) {
        executor.submit(() -> {
            try {
                if (validatePayment(senderId, receiverId, amount)) {
                    performPayment(senderId, receiverId, amount);
                    logTransaction("SUCCESS", senderId, receiverId, amount);
                } else {
                    logTransaction("FAILURE", senderId, receiverId, amount);
                }
            } catch (Exception e) {
                logTransaction("ERROR", senderId, receiverId, amount);
                e.printStackTrace();
            }
        });
    }

    private boolean validatePayment(String senderId, String receiverId, double amount) {
        if (!accounts.containsKey(senderId) || !accounts.containsKey(receiverId)) {
            return false;
        }
        if (amount <= 0) {
            return false;
        }
        return true;
    }

    private void performPayment(String senderId, String receiverId, double amount) {
        Account sender = accounts.get(senderId);
        Account receiver = accounts.get(receiverId);

        if (sender.deduct(amount)) {
            receiver.add(amount);
        } else {
            throw new RuntimeException("Insufficient balance for payment.");
        }
    }

    private void logTransaction(String status, String senderId, String receiverId, double amount) {
        System.out.printf("[%s] Transaction: %s -> %s, Amount: %.2f%n", 
                          status, senderId, receiverId, amount);
    }

    public void shutdown() {
        executor.shutdown();
    }
}

// Main application
public class PaymentProcessingService {
    public static void main(String[] args) {
        PaymentProcessor processor = new PaymentProcessor();

        // Initialize accounts
        processor.createAccount("A123", 1000.0);
        processor.createAccount("B456", 500.0);

        // Simulate concurrent transactions
        processor.processPayment("A123", "B456", 200.0);
        processor.processPayment("A123", "B456", 300.0);
        processor.processPayment("B456", "A123", 100.0);
        processor.processPayment("A123", "B456", 600.0); // Should fail due to insufficient balance

        // Gracefully shut down
        try {
            Thread.sleep(2000); // Wait for tasks to complete
        } catch (InterruptedException e) {
            e.printStackTrace();
        }
        processor.shutdown();
    }
}
```

