    private final Map<String, BigDecimal> userBalances = new HashMap<>();
    private final List<PaymentTransaction> transactionHistory = new ArrayList<>();

    // Process a payment request
    public boolean processPayment(PaymentRequest request) {
        try {
            // Validate request
            if (request == null || request.getAmount().compareTo(BigDecimal.ZERO) <= 0) {
                throw new IllegalArgumentException("Invalid payment amount.");
            }

            String fromUser = request.getFromUser();
            String toUser = request.getToUser();
            BigDecimal amount = request.getAmount();
            String currency = request.getCurrency();

            // Basic validation
            if (!userBalances.containsKey(fromUser) || !userBalances.containsKey(toUser)) {
                throw new IllegalArgumentException("User not found.");
            }
            if (!currency.equals("USD")) {
                throw new IllegalArgumentException("Only USD currency is supported.");
            }

            // Check for sufficient balance
            BigDecimal fromBalance = userBalances.get(fromUser);
            if (fromBalance.compareTo(amount) < 0) {
                throw new IllegalArgumentException("Insufficient balance.");
            }

            // Simulate transaction
            BigDecimal newFromBalance = fromBalance.subtract(amount);
            BigDecimal newToBalance = userBalances.get(toUser).add(amount);

            // Update balances (in real systems, use a database transaction)
            userBalances.put(fromUser, newFromBalance);
            userBalances.put(toUser, newToBalance);

            // Log the transaction
            transactionHistory.add(new PaymentTransaction(
                    request.getId(),
                    fromUser,
                    toUser,
                    amount,
                    currency,
                    LocalDateTime.now()
            ));

            return true;
        } catch (Exception e) {
            System.err.println("Payment failed: " + e.getMessage());
            return false;
