            System.out.println("Payment processed successfully.");
            System.out.println("Transaction history:");
            for (PaymentTransaction tx : service.getTransactionHistory()) {
                System.out.println(tx);
            }
        } else {
            System.out.println("Payment failed.");
        }
    }
}
```

