import java.util.Optional;
import java.util.UUID;

@Service
public class OrderService {
    @Autowired
    private OrderRepository orderRepository;

    @Autowired
    private LegacySystemClient legacySystemClient;

    public UUID createOrder(String customerName, double amount) {
        // Validate against legacy system
        String validationResult = legacySystemClient.validateCustomer(customerName);
        if (!validationResult.equals("VALID")) {
            throw new IllegalArgumentException("Customer validation failed: " + validationResult);
        }

        // Create and save order
        Order order = new Order();
        order.setCustomerName(customerName);
        order.setAmount(amount);
        Order savedOrder = orderRepository.save(order);
        return savedOrder.getId();
    }

    public Optional<Order> getOrder(UUID id) {
        return orderRepository.findById(id);
    }
}
