using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Azure.Cosmos.Table;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Identity.Web;
using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;

namespace EnterpriseBackendService
{
    public class Program
    {
        public static void Main(string[] args)
        {
            CreateHostBuilder(args).Build().Run();
        }

        public static IHostBuilder CreateHostBuilder(string[] args) =>
            Host.CreateDefaultBuilder(args)
                .ConfigureWebHostDefaults(webBuilder =>
                {
                    webBuilder.UseStartup<Startup>();
                });
    }

    public class Startup
    {
        public IConfiguration Configuration { get; }

        public Startup(IConfiguration configuration)
        {
            Configuration = configuration;
        }

        public void ConfigureServices(IServiceCollection services)
        {
            // Azure App Configuration for centralized configuration
            services.ConfigureAzureAppConfiguration();

            // Azure AD authentication
            services.AddAuthentication(AzureADDefaults.BearerAuthenticationScheme)
                .AddAzureADBearer(options => Configuration.Bind("AzureAd", options));

            // Dependency injection for Azure Table Storage
            services.AddSingleton<CloudStorageAccount>(CreateStorageAccount());
            services.AddSingleton<ITableClient, TableClient>();

            services.AddControllers();

            // Add health checks
            services.AddHealthChecks();
        }

        public void Configure(IApplicationBuilder app, IWebHostEnvironment env)
        {
            if (env.IsDevelopment())
            {
                app.UseDeveloperExceptionPage();
            }

            app.UseRouting();

            app.UseAuthentication();
            app.UseAuthorization();

            app.UseEndpoints(endpoints =>
            {
                endpoints.MapControllers();
                endpoints.MapHealthChecks("/health");
            });
        }

        private CloudStorageAccount CreateStorageAccount()
        {
            var storageConnectionString = Configuration["AzureStorage:ConnectionString"];
            return CloudStorageAccount.Parse(storageConnectionString);
        }
    }

    // Example Entity for Azure Table Storage
    public class EmployeeEntity : TableEntity
    {
        public string Name { get; set; }
        public string Department { get; set; }
    }

    // Azure Table Storage Repository
    public interface ITableClient
    {
        Task<List<EmployeeEntity>> GetEmployeesAsync();
    }

    public class TableClient : ITableClient
    {
        private readonly CloudStorageAccount _storageAccount;
        private readonly CloudTable _table;

        public TableClient(CloudStorageAccount storageAccount)
        {
            _storageAccount = storageAccount;
            var tableClient = _storageAccount.CreateCloudTableClient();
            _table = tableClient.GetTableReference("employees");
            _table.CreateIfNotExists();
        }

        public async Task<List<EmployeeEntity>> GetEmployeesAsync()
        {
            var query = new TableQuery<EmployeeEntity>();
            var result = await _table.ExecuteQuerySegmentedAsync(query, null);
            return result.Results.ToList();
        }
    }

    // Example API Controller
    [ApiController]
    [Route("api/[controller]")]
    public class EmployeesController : ControllerBase
    {
        private readonly ITableClient _tableClient;

        public EmployeesController(ITableClient tableClient)
        {
            _tableClient = tableClient;
        }

        [HttpGet]
        [ProducesResponseType(StatusCodes.Status200OK)]
        [ProducesResponseType(StatusCodes.Status500InternalServerError)]
        public async Task<IActionResult> GetEmployees()
        {
            try
            {
                var employees = await _tableClient.GetEmployeesAsync();
                return Ok(employees);
            }
            catch (Exception ex)
            {
                // Log error using Azure Application Insights or Serilog
                return StatusCode(500, "Internal server error");
            }
        }
    }
}
