    public async Task<IActionResult> UploadData([FromBody] DataModel data)
    {
        try
        {
            await _context.DataModels.AddAsync(data);
            await _context.SaveChangesAsync();

            // Upload to Azure Blob Storage
            await _blobStorageService.UploadBlobAsync("data-container", data.FileName, data.FileContent);

            return Ok("Data uploaded and stored successfully.");
        }
        catch (Exception ex)
        {
            // Log error to Application Insights
            _blobStorageService.LogErrorToApplicationInsights(ex);
            return StatusCode(500, "Internal server error.");
        }
    }
}
