```csharp
public interface IBlobStorageService
{
    Task UploadBlobAsync(string containerName, string fileName, byte[] fileContent);
    void LogErrorToApplicationInsights(Exception ex);
}

public class BlobStorageService : IBlobStorageService
{
    private readonly BlobServiceClient _blobServiceClient;

    public BlobStorageService()
    {
        _blobServiceClient = new BlobServiceClient(Environment.GetEnvironmentVariable("AzureStorageConnectionString"));
    }

    public async Task UploadBlobAsync(string containerName, string fileName, byte[] fileContent)
    {
        var containerClient = _blobServiceClient.GetBlobContainerClient(containerName);
        await containerClient.CreateIfNotExistsAsync();

        var blobClient = containerClient.GetBlobClient(fileName);
        await blobClient.UploadAsync(new MemoryStream(fileContent), true);
    }

    public void LogErrorToApplicationInsights(Exception ex)
    {
        // Log to Azure Application Insights (requires TelemetryClient)
        // Example: TelemetryClient.TrackException(ex);
    }
}
```

