#### 7. **Repositories/CosmosDbUserRepository.cs**
```csharp
public class CosmosDbUserRepository : IUserRepository
{
    private readonly Container _container;

    public CosmosDbUserRepository()
    {
        var endpoint = Environment.GetEnvironmentVariable("CosmosDb:EndpointUrl");
        var key = Environment.GetEnvironmentVariable("CosmosDb:AuthorizationKey");
        var databaseId = Environment.GetEnvironmentVariable("CosmosDb:DatabaseId");
        var containerId = Environment.GetEnvironmentVariable("CosmosDb:ContainerId");

        var client = new CosmosClient(endpoint, key);
        _container = client.GetContainer(databaseId, containerId);
    }

    public async Task<List<User>> GetAllAsync()
    {
        var query = _container.GetItemLinqQueryable<User>(true)
            .Where(u => u != null)
            .ToList();

        return query;
    }

    public async Task<User> GetByIdAsync(string id)
    {
        var response = await _container.ReadItemAsync<User>(id, new PartitionKey(id));
        return response.Resource;
    }

    public async Task AddAsync(User user)
    {
        await _container.UpsertItemAsync(user, new PartitionKey(user.Id));
    }
}
```

