#include <boost/asio.hpp>
#include <iostream>
#include <thread>

using boost::asio::ip::tcp;

class Session : public std::enable_shared_from_this<Session> {
    tcp::socket socket_;
    std::string message_;

public:
    Session(tcp::socket socket) : socket_(std::move(socket)), message_("Hello from C++!\r\n") {}

    void start() {
        auto self = shared_from_this();
        socket_.async_write_some(
            boost::asio::buffer(message_),
            [self](boost::system::error_code /*ec*/, std::size_t /*bytes_transferred*/) {
                // No need to handle errors in this minimal example
            });
    }
};

class Server {
    boost::asio::io_context io_context_;
    tcp::acceptor acceptor_;

public:
    Server(short port) : acceptor_(io_context_, tcp::endpoint(tcp::v4(), port)) {
        do_accept();
    }

    void do_accept() {
        acceptor_.async_accept(
            [this](boost::system::error_code ec, tcp::socket socket) {
                if (!ec) {
                    std::make_shared<Session>(std::move(socket))->start();
                }
                do_accept(); // Accept next connection
            });
    }

    void run() {
        io_context_.run();
    }
};

int main() {
    Server server(8080);
    server.run();
    return 0;
}
```

