### <language>C</language>
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <pthread.h>

#define PORT 8080
#define MAX_CLIENTS 1000

void *handle_client(void *arg) {
    int client_fd = *(int *)arg;
    char buffer[1024] = {0};
    read(client_fd, buffer, 1024);
    write(client_fd, "HTTP/1.1 200 OK\r\nContent-Length: 13\r\n\r\nHello, World!", 53);
    close(client_fd);
    free(arg);
    return NULL;
}

int main() {
    int server_fd, new_socket;
    struct sockaddr_in address;
    int opt = 1;
    int addrlen = sizeof(address);
    pthread_t thread_id;

    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        exit(EXIT_FAILURE);
    }

    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        perror("setsockopt");
        exit(EXIT_FAILURE);
    }

    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        exit(EXIT_FAILURE);
    }

    if (listen(server_fd, MAX_CLIENTS) < 0) {
        perror("listen");
        exit(EXIT_FAILURE);
    }

    while (1) {
        if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t *)&addrlen)) < 0) {
            perror("accept");
            exit(EXIT_FAILURE);
        }

        int *client_fd = (int *)malloc(sizeof(int));
        *client_fd = new_socket;
        pthread_create(&thread_id, NULL, handle_client, (void *)client_fd);
    }

    return 0;
}
```

**Why C?**  
C provides low-level control over system resources, which is ideal for fine-tuning performance in high-throughput environments. However, it requires careful memory and thread management.

