#include <iostream>
#include <boost/asio.hpp>
#include <thread>
#include <vector>

using boost::asio::ip::tcp;

class Server {
public:
    Server(short port) : io_context_(), acceptor_(io_context_, tcp::endpoint(tcp::v4(), port)) {
        do_accept();
    }

private:
    void do_accept() {
        acceptor_.async_accept([this](const boost::system::error_code& error, tcp::socket socket) {
            if (!error) {
                std::thread([socket = std::move(socket)]() {
                    char data[1024];
                    socket.read_some(boost::asio::buffer(data), boost::asio::null_buffers());
                    boost::asio::write(socket, boost::asio::buffer("HTTP/1.1 200 OK\r\nContent-Length: 13\r\n\r\nHello, World!", 53));
                }).detach();
            }
            do_accept();
        });
    }

    boost::asio::io_context io_context_;
    tcp::acceptor acceptor_;
};

int main() {
    Server server(8080);
    server.io_context_.run();
    return 0;
}
